window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0123", [{"word":"nitrogen cycle","ipa_uk":"/ˈnaɪtrədʒən ˈsaɪkl/","ipa_us":"/ˈnaɪtrədʒən ˈsaɪkəl/","definition_zh":"氮循环（氮在大气、土壤、水体与生物体之间不断转化与流转的循环过程）","definition_en":"the circulation of nitrogen among the atmosphere, soil, water and living organisms through chemical and biological transformations","core_image":"空中大量的氮气谁也直接用不了，根瘤里的细菌把它拆开，植物吸收，动物转手，微生物再把它还原成气体送回天空，一圈合拢","scene":"老师让学生把大气、土壤与生物连成一条回路画在黑板上。Bacteria in root nodules drive the nitrogen cycle in a meadow soil.","sceneCN":"这里 nitrogen cycle 指「氮在各圈层间转化流转的整个循环」（第 1 个义项：作为整体过程）；句意为草甸土壤中根瘤里的细菌驱动着氮循环。","pos":[{"tag":"n.","zh":"氮循环（术语短语，常带定冠词；复数直接加 -s 指不同系统中的循环）"}],"collocations":[{"phrase":"global nitrogen cycle","zh":"全球氮循环"},{"phrase":"soil nitrogen cycle","zh":"土壤氮循环"},{"phrase":"marine nitrogen cycle","zh":"海洋氮循环"},{"phrase":"nitrogen cycle model","zh":"氮循环模型"},{"phrase":"human alteration of the nitrogen cycle","zh":"人类对氮循环的改变"},{"phrase":"nitrogen cycle budget","zh":"氮循环收支"}],"forms":[{"label":"带冠词用法","form":"the nitrogen cycle"},{"label":"复数","form":"nitrogen cycles"},{"label":"限定成分","form":"nitrogen"},{"label":"核心名词","form":"cycle"},{"label":"相关形容词","form":"nitrogenous"},{"label":"相关过程名词","form":"nitrification"}],"derivatives":[{"word":"nitrogen","pos":"n.","zh":"nitre（硝石）+ -gen（希腊 -genēs「产生」）→ 氮：从硝石中取得的元素"},{"word":"nitrogenous","pos":"adj.","zh":"nitrogen + -ous（形容词后缀）→ 含氮的：成分中含氮的"},{"word":"nitrify","pos":"v.","zh":"nitre + -ify（使……化）→ 硝化：把铵盐转成硝酸盐"},{"word":"nitrification","pos":"n.","zh":"nitrify + -ation（名词后缀）→ 硝化作用：铵被氧化为硝酸盐的过程"},{"word":"denitrification","pos":"n.","zh":"de-（去除）+ nitrification → 反硝化：把硝酸盐还原成氮气送回大气"},{"word":"fixation","pos":"n.","zh":"fix（拉丁 fixus「固定」）+ -ation → 固定：把气态氮转成生物可用的形态"},{"word":"cycle","pos":"n.","zh":"希腊 kyklos「圆环」→ 循环：回到起点的一轮过程"}],"senses":[{"no":"01","title":"The loop as a whole","titleCN":"作为整体的氮循环","definition":"the complete circuit that moves nitrogen through air, soil, water and life","definitionCN":"让氮在空气、土壤、水与生命体中走完一圈的完整回路","example":"Bacteria in root nodules drive the nitrogen cycle in a meadow soil.","exampleCN":"草甸土壤中根瘤里的细菌驱动着氮循环。","why":"the phrase names the whole circuit, not any single step inside it.","whyCN":"这个短语命名的是整个回路，而不是回路中的任何单一步骤。"},{"no":"02","title":"The atmospheric reservoir","titleCN":"大气储库","definition":"the enormous pool of inert nitrogen gas that most organisms cannot use directly","definitionCN":"绝大多数生物无法直接利用的巨大惰性氮气储库","example":"The nitrogen cycle starts from a reservoir no plant can open on its own.","exampleCN":"氮循环的起点是一个任何植物都无法独自打开的储库。","why":"the circuit has to begin somewhere, and its largest store is the air itself.","whyCN":"循环总得有起点，而它最大的储存处就是空气本身。"},{"no":"03","title":"Fixation","titleCN":"固氮：把惰性气体拆开","definition":"the conversion of nitrogen gas into ammonia by microbes, lightning or industry","definitionCN":"由微生物、闪电或工业把氮气转成氨的过程","example":"Fixation is the gate through which the nitrogen cycle admits new reactive nitrogen.","exampleCN":"固氮是氮循环接纳新活性氮的那道门。","why":"the triple bond in nitrogen gas must be broken before any organism can use it, so this step opens the loop.","whyCN":"氮气中的三键必须先被打破生物才能利用，因此这一步打开了循环。"},{"no":"04","title":"Nitrification","titleCN":"硝化：铵转为硝酸盐","definition":"the two-stage microbial oxidation of ammonium first to nitrite and then to nitrate","definitionCN":"微生物把铵先氧化成亚硝酸盐、再氧化成硝酸盐的两段过程","example":"Nitrification keeps the nitrogen cycle running in aerated soils.","exampleCN":"硝化作用让氮循环在通气良好的土壤中持续运转。","why":"plants take up nitrate readily, so the cycle needs a step that converts ammonium into that form.","whyCN":"植物容易吸收硝酸盐，所以循环需要一个把铵转成该形态的步骤。"},{"no":"05","title":"Assimilation","titleCN":"同化：进入生物体","definition":"the uptake of nitrate or ammonium and its incorporation into amino acids and proteins","definitionCN":"吸收硝酸盐或铵并把它并入氨基酸与蛋白质","example":"Assimilation moves nitrogen from soil water into living tissue.","exampleCN":"同化把氮从土壤水带进活体组织。","why":"a cycle only becomes biological at the point where the element enters a cell.","whyCN":"只有当元素进入细胞，循环才真正变成生物过程。"},{"no":"06","title":"Ammonification","titleCN":"氨化：分解者归还","definition":"the release of ammonium when decomposers break down dead tissue and waste","definitionCN":"分解者分解死亡组织与排泄物时释放铵","example":"Ammonification returns nitrogen to the soil after the harvest.","exampleCN":"收获之后，氨化把氮送回土壤。","why":"the loop must recover what living things borrowed, and decomposition is that return path.","whyCN":"循环必须收回生物借走的东西，分解正是这条归还路径。"},{"no":"07","title":"Denitrification","titleCN":"反硝化：回到大气","definition":"the microbial reduction of nitrate to nitrogen gas, closing the loop","definitionCN":"微生物把硝酸盐还原成氮气、从而闭合循环","example":"Waterlogged fields lose nitrogen because denitrification speeds up there.","exampleCN":"积水田块会损失氮，因为那里的反硝化加快了。","why":"without a gas-producing step the element would pile up in soils and waters, so this step closes the wheel.","whyCN":"没有产气的一步，元素会在土壤与水体中堆积，因此这一步闭合了轮子。"},{"no":"08","title":"Human acceleration","titleCN":"人类加速的氮循环","definition":"the modern surplus created by industrial ammonia, fertiliser runoff and fossil-fuel burning","definitionCN":"工业合成氨、化肥径流与化石燃料燃烧造成的现代过量","example":"The nitrogen cycle is now dominated by fertiliser made with industrial ammonia.","exampleCN":"如今的氮循环主要由工业合成氨制成的化肥主导。","why":"people broke the atmospheric lock at industrial scale, so the loop gained a human-driven shortcut.","whyCN":"人类以工业规模打开了大气这把锁，循环因此多了一条人为捷径。"},{"no":"09","title":"A budget and a model","titleCN":"收支核算与模型","definition":"the accounting of stores and fluxes used to predict losses, emissions and eutrophication","definitionCN":"用储库与通量核算来预测损失、排放与富营养化","example":"Researchers built a nitrogen cycle budget for the whole river basin.","exampleCN":"研究者为整个流域建立了氮循环收支。","why":"once the loop is described as stores and flows, it can be added up and projected.","whyCN":"一旦把循环描述成储库与流动，它就能被加总与预测。"}],"etymology":{"intro":{"en":"Nitrogen cycle joins a French-coined element name to a Greek word for a wheel. Nitrogen was named in 1790 from nitre plus a Greek suffix meaning 'producing'; cycle goes back to Greek kyklos 'circle, wheel'. The phrase itself is a nineteenth-century term of agricultural chemistry.","cn":"nitrogen cycle 把法国人取的元素名接在一个希腊语的轮子上。nitrogen 于一七九〇年由 nitre 加希腊后缀「产生」命名；cycle 可上溯希腊 kyklos「圆圈、轮子」。这个短语本身是十九世纪农业化学的术语。"},"items":[{"era":"GREEK NITRON","en":"Nitron meant native soda, a mineral salt; Latin took it as nitrum 'saltpetre'.","cn":"nitron 意为天然碱，一种矿物盐；拉丁语借作 nitrum「硝石」。"},{"era":"NITRE","en":"English nitre, the old word for saltpetre, came through French from Latin nitrum.","cn":"英语 nitre 是硝石的旧称，经法语来自拉丁 nitrum。"},{"era":"NITROGEN 1790","en":"The French chemist Chaptal coined nitrogène from nitre plus -gène 'producing', and English adopted it as nitrogen.","cn":"法国化学家夏普塔尔以 nitre 加 -gène「产生」造出 nitrogène，英语取用为 nitrogen。"},{"era":"GREEK KYKLOS","en":"Kyklos meant circle or wheel and passed through Latin cyclus into English cycle.","cn":"kyklos 意为圆圈或轮子，经拉丁 cyclus 进入英语成为 cycle。"},{"era":"THE PHRASE","en":"Nineteenth-century agricultural chemistry applied cycle to the turnover of an element, giving nitrogen cycle.","cn":"十九世纪农业化学把 cycle 用于元素的周转，于是有了 nitrogen cycle。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (first date only): the phrase's earliest printed use is not consistently dated, though both elements are fully documented.","cn":"来源不确定（仅首见年代存疑）：这个短语最早的印刷使用各家年代不一，但两个成分的来历记载完整。"}]},"similar":{"note":{"en":"Group one holds the steps and look-alike forms most easily mistaken for the whole cycle; group two holds the wider accounting terms it belongs to.","cn":"第一组是最容易被当成整个循环的步骤与形近形式；第二组是它所属的更宽的核算术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"nitrogen fixation","ipa":"/ˈnaɪtrədʒən fɪkˈseɪʃn/","tag":"one step, not the loop","definition":"The conversion of inert nitrogen gas into ammonia or nitrate; it opens the cycle but is only its first move.","definitionCN":"把惰性氮气转成氨或硝酸盐；它打开循环，但只是循环的第一步。"},{"word":"nitrification","ipa":"/ˌnaɪtrɪfɪˈkeɪʃn/","tag":"one step, ammonium to nitrate","definition":"The microbial oxidation of ammonium to nitrate; it is a single stage inside the cycle, not the cycle itself.","definitionCN":"微生物把铵氧化为硝酸盐；它是循环中的单一阶段，而非循环本身。"},{"word":"denitrification","ipa":"/diːˌnaɪtrɪfɪˈkeɪʃn/","tag":"the closing step","definition":"The reduction of nitrate back to nitrogen gas; it ends one turn of the cycle.","definitionCN":"把硝酸盐还原回氮气；它结束循环的一圈。"},{"word":"nitrogenous","ipa":"/ˈnaɪtrədʒənəs/","tag":"an adjective, not a process","definition":"Containing nitrogen, as in nitrogenous waste; it describes a substance rather than a circulation.","definitionCN":"含氮的，如含氮废物；它描述物质，而非循环。"}]},{"heading":"NEAR MEANING","entries":[{"word":"nutrient cycle","ipa":"/ˈnjuːtriənt ˈsaɪkl/","tag":"any element","definition":"The general circulation of a nutrient through living things and their setting; nitrogen is one instance of it.","definitionCN":"养分在生物与其环境中的一般循环；氮循环是它的一个实例。"},{"word":"biogeochemical cycle","ipa":"/ˌbaɪəʊdʒiːəʊˈkemɪkl ˈsaɪkl/","tag":"the umbrella term","definition":"The broad class of element cycles driven by biological, geological and chemical processes; it covers carbon, nitrogen and phosphorus alike.","definitionCN":"由生物、地质与化学过程驱动的元素循环大类；碳、氮、磷循环都归入其中。"},{"word":"nitrogen budget","ipa":"/ˈnaɪtrədʒən ˈbʌdʒɪt/","tag":"an accounting","definition":"A quantified balance of nitrogen inputs, outputs and storage in a defined system; it measures the cycle but is not the cycle.","definitionCN":"某一系统内氮输入、输出与储存的量化平衡；它测量循环，但不等于循环。"},{"word":"nitrogen cascade","ipa":"/ˈnaɪtrədʒən ˈkæskeɪd/","tag":"the leakage view","definition":"The sequential transfer of reactive nitrogen from air to soil, water and coast, each step adding an environmental cost.","definitionCN":"活性氮从空气到土壤、水体与海岸的接连转移，每一步都增加环境代价。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real Greek and Latin roots and the real sequence of microbial steps.","cn":"正常联想：真实的希腊与拉丁词根，以及真实的微生物步骤顺序。"},"normal":[{"en":"nitro- traces to Greek nitron, native soda: the element was first obtained from a nitrate mineral.","cn":"nitro- 上溯希腊 nitron「天然碱」：这种元素最初得自硝酸盐矿物。"},{"en":"-gen is Greek -genes, 'born, producing': nitrogen is literally the soda-born element.","cn":"-gen 即希腊 -genes「生出、产生」：氮字面上就是由碱而生的元素。"},{"en":"cycle is kyklos, a wheel: the element ends where it began, in the air.","cn":"cycle 即 kyklos「轮子」：元素回到起点，也就是空气。"},{"en":"Four moves turn the wheel: fixation, nitrification, assimilation, denitrification.","cn":"四步转动这个轮子：固氮、硝化、同化、反硝化。"},{"en":"Two microbial jobs carry the load: nodule bacteria open the lock, soil nitrifiers change the key.","cn":"两类微生物承担主要工作：根瘤细菌开锁，土壤硝化菌换钥匙。"}],"abstract":[{"en":"A nitrogen cycle is an economy whose currency is locked in a vault almost nobody can open.","cn":"氮循环是一门经济，其通货锁在几乎无人能开的金库里。"},{"en":"It is a wheel whose spokes are microbes.","cn":"它是一只轮子，辐条是微生物。"},{"en":"Industry pried the vault open, and the surplus now leaks into rivers.","cn":"工业撬开了金库，盈余如今漏进河里。"}]},"examples":[{"en":"Fertiliser has doubled the amount of reactive nitrogen in the global nitrogen cycle.","cn":"化肥使全球氮循环中的活性氮翻了一倍。"},{"en":"Wetlands remove nitrate before it leaves, which is one reason the nitrogen cycle matters for water quality.","cn":"湿地在硝酸盐流走前将其去除，这是氮循环关乎水质的一个原因。"},{"en":"Students trace the nitrogen cycle from a legume root to the atmosphere and back.","cn":"学生从豆科植物根部一路追踪氮循环，直到大气再返回。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"nitrogen（氮）+ cycle（循环）＝氮在大气、土壤、水与生物之间转一圈；记四步：固氮、硝化、同化、反硝化。","word":"nitrogen cycle"},"root":"nitrogen（nitre 硝石 + 希腊 -genēs「产生」，一七九〇年法语造词）+ cycle（希腊 kyklos「圆环」经拉丁 cyclus）；短语为十九世纪农业化学所立。","sensesIntro":{"en":"Nine senses follow one turn of the wheel: the whole loop, its atmospheric store, fixation, nitrification, assimilation, ammonification, denitrification, human acceleration and the budget version.","cn":"九个义项沿轮子转一圈展开：整体、大气储库、固氮、硝化、同化、氨化、反硝化、人类加速，以及收支版本。"},"semanticMap":{"core":{"en":"CORE IMAGE: nitrogen gas fills the air, bacteria crack it open, plants take it up, animals pass it on, decomposers release it, other bacteria return it to the sky.","cn":"核心意象：氮气充满空气，细菌把它拆开，植物吸收，动物传递，分解者释放，另一些细菌把它送回天空。"},"chain":["GAS IN AIR","FIXATION","PLANT UPTAKE","ANIMAL TRANSFER","DECOMPOSITION","RETURN TO AIR"],"branches":[{"senses":"S1 · S2","en":"WHOLE AND STORE: the circuit as one object, then the air that holds nearly all of it.","cn":"整体与储库：先是作为一个对象的回路，再是容纳几乎全部氮的空气。"},{"senses":"S3 · S4","en":"OPENING THE LOCK: biological or industrial fixation, then the nitrifying change of form.","cn":"打开锁：先是生物或工业固氮，再是硝化带来的形态改变。"},{"senses":"S5 · S6","en":"THROUGH LIFE: uptake into tissue, then release by decomposers.","cn":"穿过生命：先被吸收进组织，再由分解者释放。"},{"senses":"S7","en":"CLOSING THE LOOP: nitrate reduced to gas and handed back to the atmosphere.","cn":"闭合回路：硝酸盐被还原为气体，交还大气。"},{"senses":"S8 · S9","en":"HUMAN AND ACCOUNTING: the industrial shortcut, then the budget that measures it.","cn":"人类与核算：先是工业捷径，再是衡量它的收支。"}]},"affixes":{"intro":{"en":"Nitrogen cycle is a two-word technical phrase: an element name built on Greek suffixes, plus a Greek-derived noun.","cn":"nitrogen cycle 是两词技术短语：一个用希腊后缀构造成的元素名，加一个希腊语源名词。"},"latinIntro":{"en":"Latin supplies nitrum directly and borrowed Greek kyklos as cyclus; the element name itself was coined in French.","cn":"拉丁语直接提供 nitrum，并借入希腊 kyklos 作 cyclus；元素名本身则是在法语中造出的。"},"items":[{"word":"nitron","structure":"nitron (Greek noun, neuter)","meaning":"native soda; a mineral alkali","meaningCN":"天然碱；矿物碱","example":"Nitron named the mineral from which nitre was known.","exampleCN":"nitron 命名了人们认识硝石所用的那种矿物。"},{"word":"nitrum","structure":"nitrum, -i (Latin noun, neuter)","meaning":"saltpetre; nitre","meaningCN":"硝石","example":"Latin nitrum became English nitre.","exampleCN":"拉丁 nitrum 变成英语 nitre。"},{"word":"nitre","structure":"nitre (English noun from Old French, from Latin nitrum)","meaning":"saltpetre, a nitrate mineral","meaningCN":"硝石，一种硝酸盐矿物","example":"Nitre supplied the first half of nitrogen.","exampleCN":"nitre 提供了 nitrogen 的前半截。"},{"word":"-gen","structure":"-gène (French suffix from Greek -genēs 'born')","meaning":"producing; born of","meaningCN":"产生的；由……而生","example":"The suffix marks nitrogen as soda-born.","exampleCN":"这个后缀标明氮由碱而生。"},{"word":"nitrogen","structure":"nitrogène (French coinage, 1790) + English adaptation","meaning":"the element that makes up most of the air","meaningCN":"构成大部分空气的那种元素","example":"Nitrogen is inert for most living things.","exampleCN":"对大多数生物来说氮是惰性的。"},{"word":"kyklos","structure":"kyklos (Greek noun, 'circle, wheel')","meaning":"circle; wheel","meaningCN":"圆圈；轮子","example":"Kyklos is the root of cycle and cyclone.","exampleCN":"kyklos 是 cycle 与 cyclone 的词根。"},{"word":"cyclus","structure":"cyclus, -i (Latin noun borrowed from Greek)","meaning":"circle; recurrent period","meaningCN":"圆环；周而复始的周期","example":"Latin cyclus passed into English cycle.","exampleCN":"拉丁 cyclus 进入英语成为 cycle。"},{"word":"cycle","structure":"cycle (English noun from Latin cyclus)","meaning":"a process that returns to its start","meaningCN":"回到起点的过程","example":"The word marks recurrence, not mere repetition.","exampleCN":"这个词标记的是周而复始，而不只是重复。"},{"word":"fixation","structure":"fixus (Latin 'fixed') + -ation","meaning":"the act of making something available or immobile","meaningCN":"使某物可用或固定的行为","example":"Fixation turns gas into a usable compound.","exampleCN":"固定作用把气体变成可用的化合物。"}],"latinEntries":[{"word":"nitrum","structure":"nitrum, -i (n., second declension)","meaning":"saltpetre; nitre","meaningCN":"硝石"},{"word":"cyclus","structure":"cyclus, -i (n., second declension, from Greek)","meaning":"circle; cycle","meaningCN":"圆环；周期"},{"word":"fixus","structure":"fixus, -a, -um (perfect participle of figere)","meaning":"fixed; fastened","meaningCN":"固定的；系牢的"}]}},{"word":"carbon cycle","ipa_uk":"/ˈkɑːbən ˈsaɪkl/","ipa_us":"/ˈkɑːrbən ˈsaɪkəl/","definition_zh":"碳循环（碳在大气、海洋、陆地、岩石与生物体之间交换与储存的循环过程）","definition_en":"the exchange and storage of carbon among the atmosphere, oceans, land, rocks and living organisms","core_image":"一缕碳从空气钻进叶片，随食物走过食物链，随呼吸与腐烂回到空气，或沉入海底压成岩石，亿万年后再被掘出点燃","scene":"学生用箭头把燃烧的煤、呼吸的牲畜与海面连成一个闭环。The carbon cycle keeps the same atoms moving between air, water, rock and life.","sceneCN":"这里 carbon cycle 指「碳在各储库之间不断交换的整个循环」（第 1 个义项：作为整体过程）；句意为碳循环让同一批碳原子在空气、水、岩石与生命之间流动。","pos":[{"tag":"n.","zh":"碳循环（术语短语，常带定冠词；复数直接加 -s 指不同系统或模型中的循环）"}],"collocations":[{"phrase":"global carbon cycle","zh":"全球碳循环"},{"phrase":"terrestrial carbon cycle","zh":"陆地碳循环"},{"phrase":"ocean carbon cycle","zh":"海洋碳循环"},{"phrase":"carbon cycle model","zh":"碳循环模型"},{"phrase":"carbon cycle feedback","zh":"碳循环反馈"},{"phrase":"perturbation of the carbon cycle","zh":"对碳循环的扰动"}],"forms":[{"label":"带冠词用法","form":"the carbon cycle"},{"label":"复数","form":"carbon cycles"},{"label":"限定成分","form":"carbon"},{"label":"核心名词","form":"cycle"},{"label":"相关名词（储库）","form":"carbon sink"},{"label":"相关名词（释放源）","form":"carbon source"}],"derivatives":[{"word":"carbon","pos":"n.","zh":"拉丁 carbo（炭火、木炭）→ 碳：以炭为原型命名的元素"},{"word":"carbonate","pos":"n./v.","zh":"carbon + -ate（化学名词与动词后缀）→ 碳酸盐；使碳酸化"},{"word":"carbonated","pos":"adj.","zh":"carbonate + -ed（形容词后缀）→ 含二氧化碳的、充气的"},{"word":"carbonaceous","pos":"adj.","zh":"carbon + -aceous（「具有……性质的」）→ 含碳的、碳质的"},{"word":"carbonic","pos":"adj.","zh":"carbon + -ic（形容词后缀）→ 碳的、碳酸的"},{"word":"photosynthesis","pos":"n.","zh":"photo-（希腊 phōs「光」）+ synthesis（希腊「放在一起」）→ 光合作用：用光把二氧化碳合成有机物"},{"word":"respiration","pos":"n.","zh":"re-（反复）+ spirare（拉丁「呼吸」）+ -ation → 呼吸作用：释放能量并放出二氧化碳"}],"senses":[{"no":"01","title":"The loop as a whole","titleCN":"作为整体的碳循环","definition":"the full circuit that moves carbon through air, water, rock and life","definitionCN":"让碳在空气、水、岩石与生命体中走完一圈的完整回路","example":"The carbon cycle keeps the same atoms moving between air, water, rock and life.","exampleCN":"碳循环让同一批碳原子在空气、水、岩石与生命之间流动。","why":"the phrase names the whole exchange system rather than any single flux.","whyCN":"这个短语命名的是整个交换系统，而不是任何单一通量。"},{"no":"02","title":"The atmospheric pool","titleCN":"大气碳库","definition":"the small but decisive store of carbon dioxide and methane in the air","definitionCN":"空气中小而具决定性的二氧化碳与甲烷储库","example":"The atmospheric pool is small, yet it controls the planet's heat balance.","exampleCN":"大气碳库很小，却控制着地球的热量平衡。","why":"the cycle's smallest store is the one that talks back to climate.","whyCN":"循环中最小的储库恰恰是会对气候作出回应的那个。"},{"no":"03","title":"Photosynthetic uptake","titleCN":"光合吸收","definition":"the removal of carbon dioxide from air by plants, algae and some bacteria","definitionCN":"植物、藻类与部分细菌从空气中取走二氧化碳","example":"Photosynthetic uptake pulls carbon into leaves every growing season.","exampleCN":"每个生长季，光合吸收都把碳拉进叶片。","why":"carbon enters the living part of the loop only after light splits it out of the air.","whyCN":"只有光把碳从空气中拆出之后，碳才进入循环的生物部分。"},{"no":"04","title":"Respiration and return","titleCN":"呼吸与归还","definition":"the release of carbon dioxide when organisms burn sugar for energy","definitionCN":"生物燃烧糖以获取能量时释放二氧化碳","example":"Respiration sends carbon back to the air within hours.","exampleCN":"呼吸在数小时内就把碳送回空气。","why":"every organism that takes carbon in must eventually pay it back as gas.","whyCN":"每一个摄入碳的生物最终都必须以气体形式偿还。"},{"no":"05","title":"Decomposition","titleCN":"分解与土壤碳","definition":"the slow release or storage of carbon as dead matter decays","definitionCN":"死亡物质腐烂时碳的缓慢释放或储存","example":"Decomposition can hold carbon in peat for thousands of years.","exampleCN":"分解过程能把碳在泥炭中留住数千年。","why":"decay is the leaky valve of the loop, and sometimes it jams shut into soil.","whyCN":"腐烂是循环中漏气的阀门，有时又会卡住把碳封进土壤。"},{"no":"06","title":"Combustion","titleCN":"燃烧：快速释放","definition":"the burning of fossil fuel, wood or biomass that returns stored carbon to air at once","definitionCN":"燃烧化石燃料、木材或生物质，把储存的碳一下子送回空气","example":"Combustion moves carbon that took ages to store into the air in seconds.","exampleCN":"燃烧把耗费漫长时间储存的碳在几秒内送入空气。","why":"fire compresses geological time into an instant, which is what makes it matter.","whyCN":"火把地质时间压缩成一瞬，这正是它要紧的原因。"},{"no":"07","title":"Ocean exchange","titleCN":"海气交换与生物泵","definition":"the dissolving of carbon dioxide in seawater and its sinking with dead plankton","definitionCN":"二氧化碳溶入海水，并随死亡浮游生物下沉","example":"Ocean exchange absorbs roughly a quarter of human emissions each year.","exampleCN":"海气交换每年吸收约四分之一的人类排放。","why":"the sea is the loop's largest moving store, taking gas in at the surface and sinking it below.","whyCN":"海洋是循环中最大的活动储库，在表层吸收气体并把它沉到下面。"},{"no":"08","title":"Geological storage","titleCN":"地质储存：石灰岩与化石","definition":"carbon locked in limestone, dolomite, coal, oil, gas and kerogen over millions of years","definitionCN":"经数百万年封存在石灰岩、白云岩、煤、石油、天然气与干酪根中的碳","example":"Geological storage holds most of the planet's carbon in rock.","exampleCN":"地质储存把地球上大部分的碳锁在岩石里。","why":"the loop has a long-term vault, and rock is where the element waits out epochs.","whyCN":"循环有一个长期金库，岩石就是元素用来等待漫长年代的地方。"},{"no":"09","title":"Human perturbation and monitoring","titleCN":"人类扰动与监测","definition":"the measured imbalance caused by emissions, land use and the instruments that track it","definitionCN":"排放与土地利用造成并被仪器追踪的失衡","example":"The carbon cycle is now monitored by instruments on a Hawaiian volcano.","exampleCN":"如今，夏威夷一座火山上的仪器在监测碳循环。","why":"once people add a new flux, the loop becomes something to measure and forecast.","whyCN":"一旦人类加入新的通量，循环便成了需要测量与预测的对象。"}],"etymology":{"intro":{"en":"Carbon cycle pairs a Latin word for charcoal with a Greek word for a wheel. Carbon was named in French in 1789 from Latin carbo 'charcoal, ember'; cycle came through Latin cyclus from Greek kyklos 'circle'. The compound belongs to nineteenth-century geochemistry and plant science.","cn":"carbon cycle 把拉丁语的「木炭」与希腊语的「轮子」配在一起。carbon 于一七八九年以拉丁 carbo「木炭、炭火」在法语中命名；cycle 经拉丁 cyclus 来自希腊 kyklos「圆圈」。这个复合词属于十九世纪的地球化学与植物学。"},"items":[{"era":"LATIN CARBO","en":"Carbo, carbonis meant charcoal or a burning ember, and also named the element in French charbon.","cn":"carbo、carbonis 意为木炭或燃烧的炭火，也在法语 charbon 中命名这种元素。"},{"era":"CARBON 1789","en":"Lavoisier's circle fixed the name carbone for the element; English adopted it as carbon.","cn":"拉瓦锡一派为这种元素确定了 carbone 之名；英语取用为 carbon。"},{"era":"GREEK KYKLOS","en":"Kyklos 'circle, wheel' became Latin cyclus and English cycle, a word for returning processes.","cn":"kyklos「圆圈、轮子」变成拉丁 cyclus 与英语 cycle，指回归性的过程。"},{"era":"PHOTOSYNTHESIS 1840S","en":"The discovery that light builds organic matter from carbon dioxide made the biological half of the loop visible.","cn":"发现光能把二氧化碳建成有机物，使循环的生物那一半变得可见。"},{"era":"THE PHRASE","en":"Geochemists and plant physiologists of the later nineteenth century applied cycle to carbon's exchange between air, life and rock.","cn":"十九世纪后期的地球化学家与植物生理学家把 cycle 用于碳在空气、生命与岩石间的交换。"},{"era":"KEELING 1958","en":"Continuous measurements on Mauna Loa turned the carbon cycle into a monitored, quantified system.","cn":"冒纳罗亚的连续测量把碳循环变成可监测、可量化的系统。"}]},"similar":{"note":{"en":"Group one holds the sibling terms built on carbon that are often confused with the cycle itself; group two holds the accounting and cycling terms it belongs to.","cn":"第一组是最常与碳循环本身混淆的碳类同族术语；第二组是它所属的核算与循环术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"carbon footprint","ipa":"/ˈkɑːbən ˈfʊtprɪnt/","tag":"a measure, not a loop","definition":"The total greenhouse gas emissions attributed to a person, product or organisation; it is an account drawn from the cycle.","definitionCN":"归到个人、产品或机构名下的温室气体排放总量；它是从循环中取出的一笔账。"},{"word":"carbon sequestration","ipa":"/ˈkɑːbən ˌsiːkwəˈstreɪʃn/","tag":"one direction only","definition":"The deliberate removal and storage of carbon dioxide; it works one side of the cycle.","definitionCN":"有意移除并储存二氧化碳；它只作用于循环的一侧。"},{"word":"carbon sink","ipa":"/ˈkɑːbən sɪŋk/","tag":"a store, not the motion","definition":"Any reservoir that takes in more carbon than it releases, such as a forest or the ocean; it is a component of the cycle.","definitionCN":"吸收多于释放的储库，如森林或海洋；它是循环的一个组成部分。"},{"word":"carbon source","ipa":"/ˈkɑːbən sɔːs/","tag":"the opposite store","definition":"A reservoir that releases more carbon than it absorbs; the cycle is the balance between sources and sinks.","definitionCN":"释放多于吸收的储库；循环正是源与汇之间的平衡。"}]},{"heading":"NEAR MEANING","entries":[{"word":"nutrient cycle","ipa":"/ˈnjuːtriənt ˈsaɪkl/","tag":"any element","definition":"The general circulation of a nutrient through organisms and environment; carbon is one case of it.","definitionCN":"养分在生物与环境中的一般循环；碳循环是它的一个例子。"},{"word":"biogeochemical cycle","ipa":"/ˌbaɪəʊdʒiːəʊˈkemɪkl ˈsaɪkl/","tag":"the umbrella term","definition":"The class of element cycles combining biological, geological and chemical processes; it includes carbon and nitrogen.","definitionCN":"结合生物、地质与化学过程的元素循环大类；包含碳循环与氮循环。"},{"word":"carbon budget","ipa":"/ˈkɑːbən ˈbʌdʒɪt/","tag":"an accounting","definition":"A quantified balance of carbon inputs and outputs for a system, often used to set emission limits.","definitionCN":"某系统碳输入与输出的量化平衡，常用于设定排放上限。"},{"word":"greenhouse effect","ipa":"/ˈɡriːnhaʊs ɪˈfekt/","tag":"the consequence, not the circuit","definition":"The warming caused by gases that trap heat; carbon cycling affects it but is not the same phenomenon.","definitionCN":"气体截留热量造成的升温；碳循环影响它，但两者不是同一现象。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real Latin and Greek sources plus the actual routes carbon takes.","cn":"正常联想：真实的拉丁与希腊来源，加上碳实际走过的路径。"},"normal":[{"en":"Carbon is carbo, charcoal: the element was named after the soot and embers that first revealed it.","cn":"carbon 即 carbo「木炭」：这种元素以最早显露它的烟灰与炭火命名。"},{"en":"cycle is kyklos, a wheel: carbon ends where it started, in air or in rock.","cn":"cycle 即 kyklos「轮子」：碳回到起点，或在空气，或在岩石。"},{"en":"Two pumps move the loop: photosynthesis down, respiration up.","cn":"两台泵推动循环：光合作用向下，呼吸作用向上。"},{"en":"Three stores to remember: air, sea, rock, with life as the shuttle between them.","cn":"记住三个储库：空气、海洋、岩石，生命是它们之间的穿梭者。"},{"en":"The slow loop is stone; the fast loop is breath.","cn":"慢循环是石头，快循环是呼吸。"}],"abstract":[{"en":"The carbon cycle is an old ledger in which burning reads the past aloud.","cn":"碳循环是一本旧账，燃烧把过去大声念了出来。"},{"en":"It is a wheel with two speeds: seasons and epochs.","cn":"它是一只两速的轮子：季节与纪元。"},{"en":"Every flame is a withdrawal from an account that took ages to fill.","cn":"每一簇火焰都是从一笔积攒许久的账户里取钱。"}]},"examples":[{"en":"Deforestation alters the carbon cycle by removing a sink and adding a source.","cn":"毁林通过去掉一个汇、增加一个源而改变碳循环。"},{"en":"The ocean slows climate change because it takes up carbon from the air.","cn":"海洋减缓气候变化，因为它从空气中吸收碳。"},{"en":"Models of the carbon cycle disagree mainly about how soils will respond to warming.","cn":"碳循环模型的歧见主要在于土壤将如何回应变暖。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"carbon（碳）+ cycle（循环）＝碳在空气、海洋、岩石与生物之间转一圈；记两个泵：光合向下、呼吸向上，再加燃烧这个快阀门。","word":"carbon cycle"},"root":"carbon（拉丁 carbo「木炭」，一七八九年法语定名）+ cycle（希腊 kyklos「圆环」经拉丁 cyclus）；短语为十九世纪地球化学与植物学所立。","sensesIntro":{"en":"Nine senses follow the element's route: the whole loop, its air store, uptake, respiration, decay, fire, the sea, the rock vault and the measured human change.","cn":"九个义项沿元素的路径展开：整体、大气储库、吸收、呼吸、腐烂、火、海洋、岩石金库，以及被测量的人类改变。"},"semanticMap":{"core":{"en":"CORE IMAGE: a carbon atom leaves the air through a leaf, travels through eaters, returns through breath or decay, or sinks into rock and waits.","cn":"核心意象：一个碳原子经叶片离开空气，穿过取食者，经呼吸或腐烂返回，或沉进岩石里等待。"},"chain":["CO2 IN AIR","LEAF UPTAKE","FOOD CHAIN","BREATH AND DECAY","SEA OR ROCK","RETURN BY FIRE"],"branches":[{"senses":"S1 · S2","en":"WHOLE AND AIR: the circuit as one system, then the small store that governs climate.","cn":"整体与大气：先是作为一个系统的回路，再是左右气候的小储库。"},{"senses":"S3 · S4 · S5","en":"THE FAST LOOP: uptake, respiration and decay turning within seasons.","cn":"快循环：吸收、呼吸与腐烂在季节内转动。"},{"senses":"S6 · S9","en":"FIRE AND MEASUREMENT: ancient carbon released at once, then the instruments watching the imbalance.","cn":"火与测量：古老碳被一次性释放，然后是盯着失衡的仪器。"},{"senses":"S7","en":"THE SEA: gas dissolving at the surface and sinking with dead plankton.","cn":"海洋：气体在表层溶解，随死亡浮游生物下沉。"},{"senses":"S8","en":"THE ROCK VAULT: limestone, coal and kerogen holding carbon for epochs.","cn":"岩石金库：石灰岩、煤与干酪根把碳封存许多纪元。"}]},"affixes":{"intro":{"en":"Carbon cycle is a two-word technical phrase: a Latin-derived element name plus a Greek-derived noun for recurrence.","cn":"carbon cycle 是两词技术短语：拉丁语源的元素名，加一个表示回归的希腊语源名词。"},"latinIntro":{"en":"Latin carbo gives carbon and carbonate; Latin cyclus, borrowed from Greek, gives cycle; respiration and combustion also trace to Latin verbs.","cn":"拉丁 carbo 给出 carbon 与 carbonate；拉丁 cyclus 借自希腊语，给出 cycle；respiration 与 combustion 也上溯拉丁动词。"},"items":[{"word":"carbo","structure":"carbo, carbonis (Latin noun, masculine)","meaning":"charcoal; burning ember","meaningCN":"木炭；燃烧的炭火","example":"Carbo named the element in French charbon.","exampleCN":"carbo 在法语 charbon 中命名了这种元素。"},{"word":"carbon","structure":"carbone (French coinage 1789) + English adaptation","meaning":"the element of charcoal and diamond","meaningCN":"木炭与钻石所含的那种元素","example":"Carbon forms the backbone of organic chemistry.","exampleCN":"碳构成有机化学的骨架。"},{"word":"carbonate","structure":"carbon + -ate (chemical suffix)","meaning":"a salt of carbonic acid","meaningCN":"碳酸的盐","example":"Limestone is mostly calcium carbonate.","exampleCN":"石灰岩主要是碳酸钙。"},{"word":"carbonaceous","structure":"carbon + -aceous ('of the nature of')","meaning":"rich in carbon","meaningCN":"富含碳的","example":"Carbonaceous shale burns poorly.","exampleCN":"碳质页岩不易燃烧。"},{"word":"kyklos","structure":"kyklos (Greek noun, 'circle, wheel')","meaning":"circle; wheel","meaningCN":"圆圈；轮子","example":"Kyklos gave cycle and cyclone.","exampleCN":"kyklos 给出 cycle 与 cyclone。"},{"word":"cyclus","structure":"cyclus, -i (Latin noun borrowed from Greek)","meaning":"circle; recurring period","meaningCN":"圆环；周期","example":"Cyclus entered English as cycle.","exampleCN":"cyclus 进入英语成为 cycle。"},{"word":"photosynthesis","structure":"phōs (Greek 'light') + synthesis (Greek 'placing together')","meaning":"building sugar from light and carbon dioxide","meaningCN":"用光与二氧化碳造糖","example":"Photosynthesis removes carbon from the air.","exampleCN":"光合作用从空气中取走碳。"},{"word":"respiration","structure":"spirare (Latin 'to breathe') + -ation","meaning":"the release of energy with carbon dioxide","meaningCN":"伴随二氧化碳释放的能量释放","example":"Respiration returns carbon to the atmosphere.","exampleCN":"呼吸把碳送回大气。"},{"word":"combustion","structure":"comburere (Latin 'to burn up') + -tion","meaning":"rapid burning with release of heat and gas","meaningCN":"释放热量与气体的快速燃烧","example":"Combustion releases fossil carbon.","exampleCN":"燃烧释放化石碳。"}],"latinEntries":[{"word":"carbo","structure":"carbo, carbonis (n., third declension)","meaning":"charcoal; ember","meaningCN":"木炭；炭火"},{"word":"cyclus","structure":"cyclus, -i (n., second declension, from Greek)","meaning":"circle; cycle","meaningCN":"圆环；循环"},{"word":"spirare","structure":"spirare (verb, first conjugation)","meaning":"to breathe","meaningCN":"呼吸"},{"word":"comburere","structure":"comburere (verb, third conjugation)","meaning":"to burn up","meaningCN":"烧尽"}]}},{"word":"phosphorus cycle","ipa_uk":"/ˈfɒsfərəs ˈsaɪkl/","ipa_us":"/ˈfɑːsfərəs ˈsaɪkəl/","definition_zh":"磷循环（磷在岩石、土壤、水体与生物体之间迁移周转的过程，以沉积循环为主要特征）","definition_en":"the movement of phosphorus among rocks, soils, water and living organisms, driven mainly by weathering and sedimentation","core_image":"山岩被雨水慢慢啃蚀，磷随泥沙进入土壤与河流，被植物吸走、被动物吃掉，随遗体沉入海底压成新岩，直到地壳抬升再露出地面","scene":"老师在图上画出一条从山岩到海底、再被抬回地面的长线。Weathering of apatite rock is the only natural entry into the phosphorus cycle.","sceneCN":"这里 phosphorus cycle 指「磷在岩石、水体与生物之间迁移的整个循环」（第 1 个义项：作为整体过程）；句意为磷灰石岩石的风化是磷循环唯一的天然入口。","pos":[{"tag":"n.","zh":"磷循环（术语短语，常带定冠词；复数直接加 -s 指不同系统或地质时期的循环）"}],"collocations":[{"phrase":"global phosphorus cycle","zh":"全球磷循环"},{"phrase":"soil phosphorus cycle","zh":"土壤磷循环"},{"phrase":"phosphorus cycle in lakes","zh":"湖泊磷循环"},{"phrase":"phosphorus cycle model","zh":"磷循环模型"},{"phrase":"human impact on the phosphorus cycle","zh":"人类对磷循环的影响"},{"phrase":"phosphorus cycle budget","zh":"磷循环收支"}],"forms":[{"label":"带冠词用法","form":"the phosphorus cycle"},{"label":"复数","form":"phosphorus cycles"},{"label":"限定成分","form":"phosphorus"},{"label":"核心名词","form":"cycle"},{"label":"相关矿物名词","form":"phosphate"},{"label":"相关过程名词","form":"eutrophication"}],"derivatives":[{"word":"phosphorus","pos":"n.","zh":"希腊 phōsphoros（「带光者」，晨星之名）→ 磷：发光而得名"},{"word":"phosphate","pos":"n.","zh":"phosphorus + -ate（化学盐类后缀）→ 磷酸盐：磷在土壤与水中的主要存在形式"},{"word":"phosphatic","pos":"adj.","zh":"phosphate + -ic（形容词后缀）→ 含磷酸盐的"},{"word":"phosphorescent","pos":"adj.","zh":"phosphorus + -escent（「正在呈现」）→ 发冷光的：不是燃烧而是缓慢发光的"},{"word":"weathering","pos":"n.","zh":"weather（古英语「天气、风化」）+ -ing → 风化：岩石在原地被水与空气分解"},{"word":"sedimentation","pos":"n.","zh":"sediment（拉丁 sedimentum「沉降物」）+ -ation → 沉积：颗粒沉落并层层堆积"},{"word":"eutrophication","pos":"n.","zh":"eu-（希腊「良好」）+ trophē（「营养」）+ -ation → 富营养化：养分过多导致藻类暴发"}],"senses":[{"no":"01","title":"The loop as a whole","titleCN":"作为整体的磷循环","definition":"the full circuit that moves phosphorus from rock through life and water and back into rock","definitionCN":"让磷从岩石穿过生命与水体、再回到岩石的完整回路","example":"Weathering of apatite rock is the only natural entry into the phosphorus cycle.","exampleCN":"磷灰石岩石的风化是磷循环唯一的天然入口。","why":"the phrase names the whole circuit, which here is mostly a sedimentary one.","whyCN":"这个短语命名的是整个回路，而这里它主要是一条沉积回路。"},{"no":"02","title":"Weathering as the source","titleCN":"风化：唯一的天然来源","definition":"the slow release of phosphate from apatite and other minerals as rock breaks down","definitionCN":"岩石分解时磷灰石等矿物缓慢释放磷酸盐","example":"Without weathering the phosphorus cycle would have no new supply.","exampleCN":"没有风化，磷循环就没有新的补给。","why":"phosphorus has no gaseous phase, so the loop must start with solid rock being broken.","whyCN":"磷没有气态阶段，所以循环必须从固体岩石被分解开始。"},{"no":"03","title":"Plant uptake","titleCN":"植物吸收与菌根协作","definition":"the uptake of dissolved phosphate by roots, often assisted by mycorrhizal fungi","definitionCN":"根系吸收溶解态磷酸盐，常由菌根真菌协助","example":"Mycorrhizal fungi extend the reach of plant uptake in the phosphorus cycle.","exampleCN":"菌根真菌在磷循环中扩大了植物吸收的范围。","why":"phosphate is scarce and immobile in soil, so plants must partner with fungi to reach it.","whyCN":"磷酸盐在土壤中稀少且不易移动，植物必须与真菌合作才能取得。"},{"no":"04","title":"Transfer through the food chain","titleCN":"沿食物链传递","definition":"the passage of phosphorus from plants to herbivores and predators, concentrated at each step","definitionCN":"磷从植物到食草动物再到捕食者的传递，每一步都富集","example":"Each trophic step in the phosphorus cycle passes on a smaller total but a richer concentration.","exampleCN":"磷循环中每个营养级传下去的总量更少，浓度却更高。","why":"phosphorus builds bones, teeth and DNA, so bodies keep and concentrate it as it moves up.","whyCN":"磷构成骨骼、牙齿与遗传物质，所以它在向上传递时被身体保留并富集。"},{"no":"05","title":"Decomposition and return","titleCN":"分解与归还土壤","definition":"the release of phosphate when dead tissue and waste are broken down","definitionCN":"死亡组织与排泄物被分解时释放磷酸盐","example":"Decomposition closes the short loop of the phosphorus cycle within a forest floor.","exampleCN":"分解在林地上层闭合了磷循环的短回路。","why":"most phosphate is recycled quickly, so the loop has a tight biological circle inside the slow rock one.","whyCN":"大部分磷酸盐被迅速回收，于是循环在缓慢的岩石回路里还套着一个紧密的生物圈。"},{"no":"06","title":"Sedimentation and burial","titleCN":"沉积与埋藏成岩","definition":"the sinking of phosphate particles to the seabed and their consolidation into new rock","definitionCN":"含磷颗粒沉到海底并固结成新岩石","example":"Sedimentation removes phosphate from the ocean over geological time.","exampleCN":"在地质时间尺度上，沉积把磷酸盐从海洋中移走。","why":"the loop's exit is the sea floor, where the element is locked into sediment.","whyCN":"循环的出口是海底，元素在那里被锁进沉积物。"},{"no":"07","title":"Uplift and the long return","titleCN":"抬升与漫长的回归","definition":"the tectonic rise of phosphate-bearing rock that makes the element available again","definitionCN":"含磷岩石经构造抬升重新变得可用","example":"Tectonic uplift restarts the phosphorus cycle after millions of years.","exampleCN":"构造抬升在数百万年后重新启动磷循环。","why":"burial would end the story, so the loop depends on mountains rising out of old seabeds.","whyCN":"埋藏本该结束一切，因此循环依赖旧海底升成山脉。"},{"no":"08","title":"Scarcity and fertiliser","titleCN":"稀缺与磷肥","definition":"the mining of phosphate rock and guano to supplement a naturally tight supply","definitionCN":"开采磷矿石与鸟粪石以补充天然的紧供给","example":"Modern agriculture runs the phosphorus cycle at twice its natural pace.","exampleCN":"现代农业让磷循环以天然速度的两倍运转。","why":"because the natural flow is so small, farming had to open a new industrial inflow.","whyCN":"正因为天然流量如此之小，农业不得不开一个工业的新流入。"},{"no":"09","title":"Runoff and eutrophication","titleCN":"径流流失与富营养化","definition":"the leakage of excess phosphate into rivers and lakes, where it feeds algal blooms","definitionCN":"过量磷酸盐漏入河流湖泊，喂养藻类暴发","example":"Farm runoff adds a shortcut to the phosphorus cycle that ends in dead lakes.","exampleCN":"农田径流给磷循环加了一条以死湖收尾的捷径。","why":"the element that limits growth in most fresh waters becomes a pollutant once it arrives in surplus.","whyCN":"在多数淡水中限制生长的元素，一旦过量到达便成了污染物。"}],"etymology":{"intro":{"en":"Phosphorus cycle joins a Greek name for the morning star to a Greek word for a wheel. Phosphorus means 'light-bearer', from phōs 'light' and pherein 'to carry'. The element was isolated about 1669 because it glowed in the dark; cycle came through Latin cyclus from Greek kyklos.","cn":"phosphorus cycle 把希腊语的晨星之名接在希腊语的轮子上。phosphorus 意为「带光者」，来自 phōs「光」与 pherein「携带」。这种元素约在一六六九年因在暗处发光而被分离出来；cycle 经拉丁 cyclus 来自希腊 kyklos。"},"items":[{"era":"GREEK PHOSPHOROS","en":"Phōsphoros, 'light-bearer', named the planet Venus as the morning star; Latin took it as Phosphorus.","cn":"phōsphoros「带光者」是金星作为晨星的名字；拉丁语借作 Phosphorus。"},{"era":"ELEMENT 1669","en":"A glowing substance isolated from urine around 1669 was given the name of the light-bearer, and the element kept it.","cn":"约一六六九年从尿液中分离出的发光物质被冠以「带光者」之名，这种元素沿用至今。"},{"era":"GREEK KYKLOS","en":"Kyklos 'circle, wheel' passed through Latin cyclus into English cycle.","cn":"kyklos「圆圈、轮子」经拉丁 cyclus 进入英语 cycle。"},{"era":"MINERAL THEORY 1840","en":"Liebig's mineral theory established phosphorus as a limiting plant nutrient, making its circulation a subject of agricultural chemistry.","cn":"李比希的矿物营养理论确立磷为限制性植物养分，使磷的流转成为农业化学的课题。"},{"era":"THE PHRASE","en":"Twentieth-century soil science and limnology named the sedimentary circuit of phosphorus a cycle, in deliberate contrast to the gaseous nitrogen cycle.","cn":"二十世纪的土壤学与湖沼学把磷的沉积回路称为循环，以与气态的氮循环形成对照。"},{"era":"EUTROPHICATION 1960S","en":"Research on lake pollution tied the phrase to phosphate runoff and algal blooms.","cn":"湖泊污染研究把这个短语与磷酸盐径流和藻类暴发联系起来。"}]},"similar":{"note":{"en":"Group one holds the phosphorus compounds and processes most easily confused with the cycle; group two holds the cycling terms it is compared with.","cn":"第一组是最容易与磷循环混淆的磷类化合物与过程；第二组是常与它比较的循环术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"phosphate","ipa":"/ˈfɒsfeɪt/","tag":"the compound, not the circuit","definition":"A salt or ester of phosphoric acid; it is the form phosphorus takes in soil and water, not the circulation itself.","definitionCN":"磷酸的盐或酯；它是磷在土壤与水中的存在形式，而非流转过程本身。"},{"word":"phosphorescent","ipa":"/ˌfɒsfəˈresnt/","tag":"the glow, not the element","definition":"Glowing without heat; the adjective recalls the element's discovery but says nothing about nutrient movement.","definitionCN":"不发热的发光；这个形容词让人想起该元素的发现，与养分迁移无关。"},{"word":"eutrophication","ipa":"/ˌjuːtrəfɪˈkeɪʃn/","tag":"the consequence","definition":"Nutrient over-enrichment that causes algal blooms; excess phosphate triggers it but it is not the cycle.","definitionCN":"养分过度富集引发藻类暴发；过量磷酸盐会触发它，但它不是循环。"},{"word":"apatite","ipa":"/ˈæpətaɪt/","tag":"the mineral source","definition":"A phosphate mineral that holds most rock phosphorus; it is the starting store, not the loop.","definitionCN":"一种磷酸盐矿物，容纳大部分岩石磷；它是起始储库，不是循环。"}]},{"heading":"NEAR MEANING","entries":[{"word":"nutrient cycle","ipa":"/ˈnjuːtriənt ˈsaɪkl/","tag":"any element","definition":"The general circulation of a nutrient through organisms and environment; phosphorus is one case.","definitionCN":"养分在生物与环境中的一般循环；磷循环是其中一个例子。"},{"word":"sedimentary cycle","ipa":"/ˌsedɪˈmentri ˈsaɪkl/","tag":"the type","definition":"A cycle whose main store is rock rather than air; the phosphorus cycle is the textbook example.","definitionCN":"主要储库是岩石而非空气的循环；磷循环是教科书例子。"},{"word":"biogeochemical cycle","ipa":"/ˌbaɪəʊdʒiːəʊˈkemɪkl ˈsaɪkl/","tag":"the umbrella term","definition":"The general class of element cycles driven by life, rock and chemistry; it includes phosphorus.","definitionCN":"由生命、岩石与化学驱动的元素循环大类；包含磷循环。"},{"word":"nitrogen cycle","ipa":"/ˈnaɪtrədʒən ˈsaɪkl/","tag":"the gaseous contrast","definition":"The circulation of nitrogen, whose huge atmospheric store makes it far faster than the rock-bound phosphorus cycle.","definitionCN":"氮的循环，其巨大的大气储库使它远比受岩石束缚的磷循环快。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Greek roots and the real sedimentary route.","cn":"正常联想：真实的希腊词根与真实的沉积路径。"},"normal":[{"en":"Phosphorus is phōsphoros, 'light-bearer': the element glows, and the morning star carries the same name.","cn":"phosphorus 即 phōsphoros「带光者」：元素会发光，晨星也用同一个名字。"},{"en":"No gas phase: phosphorus travels by rock, not by air, so its cycle is slow.","cn":"没有气态：磷靠岩石而非空气旅行，所以它的循环很慢。"},{"en":"Start at the quarry: weathering releases phosphate, everything else follows.","cn":"从采石场想起：风化释放磷酸盐，其余环节随之而来。"},{"en":"Four stops: rock, root, animal, seabed, then uplift back to rock.","cn":"四站：岩石、根、动物、海底，然后抬升回到岩石。"},{"en":"Guano and phosphate rock are the two mined shortcuts into the loop.","cn":"鸟粪石与磷矿石是进入这个循环的两条采矿捷径。"}],"abstract":[{"en":"The phosphorus cycle is a mountain slowly walking to the sea and back.","cn":"磷循环是一座慢慢走向大海又走回来的山。"},{"en":"It is a budget with no income except erosion.","cn":"它是一份除了侵蚀别无收入的预算。"},{"en":"Life borrows the same few atoms of phosphorus over and over.","cn":"生命一遍又一遍地借用同一些磷原子。"}]},"examples":[{"en":"Phosphate fertiliser has roughly doubled the natural flow of the phosphorus cycle.","cn":"磷肥使磷循环的天然流量大约翻了一倍。"},{"en":"Because the phosphorus cycle lacks a gas phase, it responds slowly to change.","cn":"由于磷循环没有气态阶段，它对变化的回应很慢。"},{"en":"Scientists study the phosphorus cycle to predict when reserves of phosphate rock will run short.","cn":"科学家研究磷循环，以预测磷矿石储量何时会短缺。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"phosphorus（磷，意为带光者）+ cycle（循环）＝磷从岩石出发、经植物与动物、沉到海底再抬升回来；记它没有气态，所以特别慢。","word":"phosphorus cycle"},"root":"phosphorus（希腊 phōsphoros「带光者」，phōs「光」+ pherein「携带」）+ cycle（希腊 kyklos「圆环」经拉丁 cyclus）；短语为二十世纪土壤学与湖沼学所立。","sensesIntro":{"en":"Nine senses follow the slow sedimentary route: the whole loop, weathering, uptake, food chain, decay, burial, uplift, scarcity and runoff.","cn":"九个义项沿缓慢的沉积路径展开：整体、风化、吸收、食物链、腐烂、埋藏、抬升、稀缺，以及径流。"},"semanticMap":{"core":{"en":"CORE IMAGE: rain cracks apatite, roots take the phosphate, animals pass it on, dead matter sinks to the seabed, and uplift brings the rock back to the surface.","cn":"核心意象：雨水劈开磷灰石，根吸走磷酸盐，动物把它传下去，遗体沉到海底，抬升再把岩石带回地表。"},"chain":["ROCK WEATHERS","ROOT UPTAKE","ANIMAL TRANSFER","DECAY RETURNS","SEABED BURIAL","UPLIFT EXPOSES"],"branches":[{"senses":"S1 · S7","en":"WHOLE AND DEEP TIME: the circuit as one object, then the tectonic return that completes it.","cn":"整体与深时：先是作为一个对象的回路，再是完成它的构造回归。"},{"senses":"S2 · S3","en":"FROM ROCK TO ROOT: weathering opens the supply, fungi help roots take it.","cn":"从岩石到根：风化打开供给，真菌帮根系取得。"},{"senses":"S4 · S5","en":"THROUGH BODIES: transfer up the food chain, then release by decay.","cn":"穿过身体：沿食物链上移，再经腐烂释放。"},{"senses":"S6","en":"BURIAL: phosphate sinking and hardening into future rock.","cn":"埋藏：磷酸盐下沉并固结成未来的岩石。"},{"senses":"S8 · S9","en":"HUMAN USE AND LEAK: mined supplements, then runoff that feeds algal blooms.","cn":"人类取用与泄漏：先是采矿补充，再是喂养藻华的径流。"}]},"affixes":{"intro":{"en":"Phosphorus cycle is a two-word technical phrase: a Greek name for the morning star plus a Greek noun for recurrence.","cn":"phosphorus cycle 是两词技术短语：希腊语的晨星之名，加一个希腊语源名词表示周而复始。"},"latinIntro":{"en":"Latin borrowed Greek Phosphorus as a proper name and Greek kyklos as cyclus, so both halves reached English through Latin channels.","cn":"拉丁语借入希腊 Phosphorus 作专名，也借入 kyklos 作 cyclus，所以两半都经拉丁渠道到达英语。"},"items":[{"word":"phōs","structure":"phōs, phōtos (Greek noun, neuter)","meaning":"light","meaningCN":"光","example":"Phōs opens the name of the morning star.","exampleCN":"phōs 开启了晨星之名。"},{"word":"pherein","structure":"pherein (Greek verb)","meaning":"to carry, to bear","meaningCN":"携带、承载","example":"Pherein supplies the bearer in phosphorus.","exampleCN":"pherein 提供 phosphorus 中的「携带者」。"},{"word":"Phosphoros","structure":"Phōsphoros (Greek adjective and proper name)","meaning":"light-bearer; the morning star","meaningCN":"带光者；晨星","example":"Phosphoros named Venus at dawn.","exampleCN":"phosphoros 命名黎明时的金星。"},{"word":"phosphorus","structure":"phosphorus (Latin proper name and English element name)","meaning":"the glowing element","meaningCN":"会发光的元素","example":"Phosphorus glows faintly in moist air.","exampleCN":"磷在潮湿空气中微微发光。"},{"word":"phosphate","structure":"phosphorus + -ate (chemical suffix)","meaning":"a phosphorus-bearing salt","meaningCN":"含磷的盐类","example":"Phosphate is the form plants absorb.","exampleCN":"磷酸盐是植物吸收的形式。"},{"word":"kyklos","structure":"kyklos (Greek noun, 'circle, wheel')","meaning":"circle; wheel","meaningCN":"圆圈；轮子","example":"Kyklos gave cycle.","exampleCN":"kyklos 给出 cycle。"},{"word":"cycle","structure":"cycle (English noun from Latin cyclus)","meaning":"a returning process","meaningCN":"回归性的过程","example":"The cycle closes at the rock again.","exampleCN":"这个循环再次在岩石处闭合。"},{"word":"apatite","structure":"apatite (mineral name, from Greek apatē 'deceit')","meaning":"the main phosphate mineral","meaningCN":"主要的磷酸盐矿物","example":"Apatite is the largest rock store of phosphorus.","exampleCN":"磷灰石是磷最大的岩石储库。"},{"word":"eutrophication","structure":"eu- (Greek 'well') + trophē (Greek 'nourishment') + -ation","meaning":"over-enrichment of water with nutrients","meaningCN":"水体养分过度富集","example":"Eutrophication follows phosphate runoff.","exampleCN":"富营养化紧随磷酸盐径流而来。"}],"latinEntries":[{"word":"Phosphorus","structure":"Phosphorus, -i (Latin proper noun from Greek)","meaning":"the morning star; light-bearer","meaningCN":"晨星；带光者"},{"word":"cyclus","structure":"cyclus, -i (n., second declension, from Greek)","meaning":"circle; cycle","meaningCN":"圆环；循环"}]}},{"word":"biogeochemical","ipa_uk":"/ˌbaɪəʊdʒiːəʊˈkemɪkl/","ipa_us":"/ˌbaɪoʊˌdʒiːoʊˈkemɪkəl/","definition_zh":"生物地球化学的（把生物、地质与化学过程放在一起考察的，尤其用于元素在圈层间的循环）","definition_en":"relating to the combined biological, geological and chemical processes by which elements move through the earth system","core_image":"一块岩石被细菌啃出细缝，根须钻进缝里吸走金属，雨水再把残余冲进河里，生、地、化三股力在同一处交叠","scene":"研究者在同一块岩石上同时记录菌群、矿物与酸碱变化。A biogeochemical approach explains why the lake turned acidic after the mine opened.","sceneCN":"这里 biogeochemical 指「把生物、地质与化学过程合并考察的」（第 1 个义项：跨学科属性）；句意为生物地球化学的视角解释了矿场开采后湖泊为何变酸。","pos":[{"tag":"adj.","zh":"生物地球化学的（用于名词前，无比较级；副词形式加 -ly）"}],"collocations":[{"phrase":"biogeochemical process","zh":"生物地球化学过程"},{"phrase":"biogeochemical cycle","zh":"生物地球化学循环"},{"phrase":"biogeochemical model","zh":"生物地球化学模型"},{"phrase":"biogeochemical tracer","zh":"生物地球化学示踪物"},{"phrase":"biogeochemical gradient","zh":"生物地球化学梯度"},{"phrase":"biogeochemical hotspot","zh":"生物地球化学热点区"}],"forms":[{"label":"原级","form":"biogeochemical"},{"label":"副词","form":"biogeochemically"},{"label":"名词（学科）","form":"biogeochemistry"},{"label":"名词（从业者）","form":"biogeochemist"},{"label":"复合名词","form":"biogeochemical cycle"}],"derivatives":[{"word":"biogeochemistry","pos":"n.","zh":"bio-（希腊 bios「生命」）+ geo-（希腊 gē「大地」）+ chemistry → 生物地球化学：研究生命、岩石与化学过程的交互"},{"word":"biogeochemist","pos":"n.","zh":"biogeochemistry + -ist（从业者后缀）→ 生物地球化学家"},{"word":"geochemical","pos":"adj.","zh":"geo- + chemical + -al → 地球化学的：只讲岩石与化学，不含生物这一维"},{"word":"biochemical","pos":"adj.","zh":"bio- + chemical + -al → 生物化学的：只讲生物体内的化学，不含地质这一维"},{"word":"biogeographic","pos":"adj.","zh":"bio- + geographic → 生物地理的：讲物种分布，不讲元素流转"},{"word":"chemistry","pos":"n.","zh":"希腊 khēmeia（冶炼之术）经阿拉伯 al-kīmiyā 与拉丁 alchimia → 化学：研究物质组成与变化的学问"}],"senses":[{"no":"01","title":"The combined viewpoint","titleCN":"三过程合并的视角","definition":"treating biological, geological and chemical processes as one interacting system","definitionCN":"把生物、地质与化学过程当作一个相互作用的系统来处理","example":"A biogeochemical approach explains why the lake turned acidic after the mine opened.","exampleCN":"生物地球化学的视角解释了矿场开采后湖泊为何变酸。","why":"the word exists precisely because no one of the three processes explains the result alone.","whyCN":"这个词之所以存在，正因为三者中任何一个单独都解释不了结果。"},{"no":"02","title":"Element circulation","titleCN":"元素在圈层间的循环","definition":"describing the movement of an element among air, water, rock and life","definitionCN":"描述元素在空气、水、岩石与生命之间的移动","example":"Carbon and nitrogen are studied as biogeochemical cycles.","exampleCN":"碳与氮都作为生物地球化学循环来研究。","why":"the compound's main job is to name element turnover that crosses the living and non-living divide.","whyCN":"这个复合词的主要职责，是命名跨越生物与非生物界限的元素周转。"},{"no":"03","title":"Stores and fluxes","titleCN":"储库与通量","definition":"expressing a system as measurable reservoirs linked by flows","definitionCN":"把系统表达为由流动连接的可测储库","example":"The biogeochemical budget lists every store and flux in the watershed.","exampleCN":"这份生物地球化学收支列出了流域中每个储库与通量。","why":"to combine three processes quantitatively, they must be turned into stocks and rates.","whyCN":"要把三种过程定量合并，就必须把它们变成存量与速率。"},{"no":"04","title":"Rock, water and microbes","titleCN":"岩石、水与微生物的交界","definition":"concerning the weathering zone where microbes alter minerals and water carries the products","definitionCN":"涉及微生物改造矿物、水搬运产物的风化带","example":"Biogeochemical weathering releases metals that plants then absorb.","exampleCN":"生物地球化学风化释放金属，随后被植物吸收。","why":"the most literal use is at the surface where life touches rock directly.","whyCN":"最字面的用法就在生命直接接触岩石的地表。"},{"no":"05","title":"Tracers and signatures","titleCN":"示踪物与化学印记","definition":"using isotopes or chemical ratios to follow a process through the environment","definitionCN":"用同位素或化学比值追踪环境中的一个过程","example":"A biogeochemical tracer revealed that the sulphur came from the mine.","exampleCN":"一种生物地球化学示踪物表明硫来自那座矿。","why":"when the processes are invisible, their chemical fingerprints become the evidence.","whyCN":"当过程不可见时，它们的化学指纹就成了证据。"},{"no":"06","title":"Models and prediction","titleCN":"模型与预测","definition":"describing computer models that couple biology, geology and chemistry to forecast change","definitionCN":"描述把生物、地质与化学耦合起来预测变化的计算模型","example":"The biogeochemical model predicted a drop in soil carbon.","exampleCN":"该生物地球化学模型预测土壤碳将下降。","why":"prediction requires all three processes in one set of equations.","whyCN":"预测要求把三种过程装进同一组方程。"},{"no":"07","title":"Natural processes","titleCN":"自然过程的属性","definition":"characterising ordinary natural processes such as decay, weathering or sedimentation","definitionCN":"刻画腐烂、风化或沉积等寻常自然过程","example":"Decay is a biogeochemical process as much as a biological one.","exampleCN":"腐烂既是生物过程，也是生物地球化学过程。","why":"the adjective reminds us that a plain natural process always has a chemical and a mineral side.","whyCN":"这个形容词提醒我们，寻常的自然过程总有化学与矿物的一面。"},{"no":"08","title":"Human disturbance","titleCN":"人类扰动的属性","definition":"describing altered cycles, acidification, contamination or nutrient loading caused by people","definitionCN":"描述由人造成的循环改变、酸化、污染或养分负荷","example":"Mine drainage creates a biogeochemical problem that persists for decades.","exampleCN":"矿场排水造成一个持续数十年的生物地球化学问题。","why":"the term became urgent when human activity began to reshape the same three processes.","whyCN":"当人类活动开始重塑同样这三种过程，这个词才变得紧迫。"},{"no":"09","title":"The discipline label","titleCN":"学科标签","definition":"marking a field, a method or a researcher as belonging to biogeochemistry","definitionCN":"标明某一领域、方法或研究者属于生物地球化学","example":"Her biogeochemical training let her read both the rock and the microbes.","exampleCN":"她的生物地球化学训练让她既能读懂岩石，也能读懂微生物。","why":"as a discipline grew up, the adjective became a label for its people and methods.","whyCN":"随着一门学科成长，这个形容词成了其研究者与方法的标签。"}],"etymology":{"intro":{"en":"Biogeochemical stacks three Greek elements: bios 'life', gē 'earth', and khēmeia, the art of working metals, which reached English as chemistry through Arabic and Latin. The compound belongs to the twentieth century, when Vernadsky and others made the biosphere a chemical object of study.","cn":"biogeochemical 叠了三个希腊成分：bios「生命」、gē「大地」，以及 khēmeia「冶炼金属之术」，后者经阿拉伯语与拉丁语成为英语 chemistry。这个复合词属于二十世纪，是维尔纳茨基等人把生物圈变成化学研究对象的时期。"},"items":[{"era":"GREEK BIOS","en":"Bios meant life or a way of living and supplies the bio- of biology and biogeochemistry.","cn":"bios 意为生命或生活方式，提供 biology 与 biogeochemistry 的 bio-。"},{"era":"GREEK GĒ","en":"Gē meant earth, the ground; it gives the geo- of geology and geography.","cn":"gē 意为大地、地面，给出 geology 与 geography 的 geo-。"},{"era":"GREEK KHĒMEIA","en":"Khēmeia named the art of working metals; Arabic al-kīmiyā and Latin alchimia carried it to English chemistry.","cn":"khēmeia 指冶炼金属之术；阿拉伯 al-kīmiyā 与拉丁 alchimia 把它带到英语 chemistry。"},{"era":"BIOGEOGRAPHY 1800S","en":"Nineteenth-century naturalists joined bio- to geo- to describe the distribution of life over the earth.","cn":"十九世纪博物学家把 bio- 与 geo- 拼合，描述生命在地球上的分布。"},{"era":"BIOGEOCHEMISTRY 1920S","en":"Vernadsky's work on the biosphere established biogeochemistry as the study of life as a geological and chemical force.","cn":"维尔纳茨基关于生物圈的工作确立了生物地球化学，把生命当作地质与化学力量来研究。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (first date only): the adjective's earliest recorded use is not consistently dated, though every element is documented.","cn":"来源不确定（仅首见年代存疑）：这个形容词最早的使用记录各家年代不一，但每个成分都有据可查。"}]},"similar":{"note":{"en":"Group one holds the look-alike adjectives that keep only part of the meaning; group two holds the fields and adjectives it overlaps with.","cn":"第一组是只保留了部分含义的形近形容词；第二组是与它重叠的学科与形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"geochemical","ipa":"/ˌdʒiːəʊˈkemɪkl/","tag":"no biology","definition":"Relating to the chemistry of rocks and earth materials; it leaves out the living processes that biogeochemical includes.","definitionCN":"与岩石和地球物质的化学有关；它略去了生物地球化学所包含的生命过程。"},{"word":"biochemical","ipa":"/ˌbaɪəʊˈkemɪkl/","tag":"no geology","definition":"Relating to chemistry inside living things; it says nothing about rock, soil or sediment.","definitionCN":"与生物体内的化学有关；它不涉及岩石、土壤或沉积物。"},{"word":"biogeographic","ipa":"/ˌbaɪəʊdʒiːəˈɡræfɪk/","tag":"distribution, not elements","definition":"Relating to the geographic distribution of species; it is about where organisms live, not how elements move.","definitionCN":"与物种的地理分布有关；讲生物住在哪里，不讲元素如何流动。"},{"word":"biogeochemistry","ipa":"/ˌbaɪəʊˈdʒiːəʊkemɪstri/","tag":"the noun behind the adjective","definition":"The discipline itself; the adjective describes work belonging to it.","definitionCN":"学科本身；形容词描述属于该学科的工作。"}]},{"heading":"NEAR MEANING","entries":[{"word":"ecological","ipa":"/ˌiːkəˈlɒdʒɪkl/","tag":"relations, not chemistry","definition":"Relating to the relations of organisms and environment; it overlaps but does not name chemical or geological processes.","definitionCN":"与生物和环境的关系有关；有重叠，但不命名化学或地质过程。"},{"word":"environmental","ipa":"/ɪnˌvaɪrənˈmentl/","tag":"broader and vaguer","definition":"Relating to the surroundings in general; the biogeochemical label is narrower and technical.","definitionCN":"与环境总体有关；生物地球化学这个标签更窄、更技术化。"},{"word":"earth system science","ipa":"/ɜːθ ˈsɪstəm ˈsaɪəns/","tag":"the parent field","definition":"The study of the planet as interacting spheres; biogeochemistry is one of its working languages.","definitionCN":"把行星当作互相作用的圈层来研究；生物地球化学是其工作语言之一。"},{"word":"nutrient cycling","ipa":"/ˈnjuːtriənt ˈsaɪklɪŋ/","tag":"one application","definition":"The turnover of nutrients in an ecosystem; it is a common subject of biogeochemical study, not a synonym.","definitionCN":"生态系统中养分的周转；它是生物地球化学的常见课题，而非同义词。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the three real Greek roots and the three real processes they name.","cn":"正常联想：三个真实的希腊词根，以及它们命名的三种真实过程。"},"normal":[{"en":"bio- is bios, life; geo- is gē, earth; chemical is khēmeia, metalworking.","cn":"bio- 即 bios「生命」；geo- 即 gē「大地」；chemical 即 khēmeia「冶炼」。"},{"en":"Three hands on one rock: a microbe, a rain cloud and a chemical reaction.","cn":"三只手同在一块岩石上：微生物、雨云与化学反应。"},{"en":"If a question involves life, rock and chemistry at once, the adjective fits.","cn":"若一个问题同时涉及生命、岩石与化学，这个形容词就适用。"},{"en":"Vernadsky is the name to attach: he treated the biosphere as a chemical engine.","cn":"该记住的名字是维尔纳茨基：他把生物圈当作化学引擎。"},{"en":"The usual partner noun is cycle, because elements are what travel.","cn":"最常搭配的名词是 cycle，因为流动的正是元素。"}],"abstract":[{"en":"It is a conversation between a stone, a bacterium and a river.","cn":"它是一场石头、细菌与河流之间的对话。"},{"en":"The word is a three-way junction with no dead ends.","cn":"这个词是一个没有死路的三岔口。"},{"en":"Life is not outside geology; it is one of geology's chemists.","cn":"生命并不在地质之外；它是地质的化学家之一。"}]},"examples":[{"en":"Biogeochemical models couple soil microbes to mineral weathering.","cn":"生物地球化学模型把土壤微生物与矿物风化耦合起来。"},{"en":"The team measured biogeochemical gradients across the sediment surface.","cn":"团队测量了穿过沉积物表层的生物地球化学梯度。"},{"en":"Her paper treats the wetland as a single biogeochemical reactor.","cn":"她的论文把这片湿地当作一个整体的生物地球化学反应器。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"bio（生命）+ geo（大地）+ chemical（化学）＝把生命、岩石与化学放在一起看；常见搭配是 cycle，因为元素在圈层间流动。","word":"biogeochemical"},"root":"bio-（希腊 bios「生命」）+ geo-（希腊 gē「大地」）+ chemical（希腊 khēmeia「冶炼术」经阿拉伯语与拉丁语入英语）；复合词为二十世纪生物地球化学所立。","sensesIntro":{"en":"Nine senses move from the widest view to the narrowest: the combined viewpoint, element circulation, stores and fluxes, the rock-water-microbe zone, tracers, models, natural processes, human disturbance and the discipline label.","cn":"九个义项从最宽到最窄：合并视角、元素循环、储库与通量、岩石与水与微生物的交界、示踪物、模型、自然过程、人类扰动，以及学科标签。"},"semanticMap":{"core":{"en":"CORE IMAGE: a microbe etching a mineral, a root following the crack, rain carrying the residue into a stream.","cn":"核心意象：微生物蚀刻矿物，根须沿着裂缝跟进，雨水把残余带进溪流。"},"chain":["LIFE AT THE SURFACE","MICROBE ETCHES ROCK","MINERAL RELEASES","ROOT ABSORBS","WATER CARRIES","SEDIMENT STORES"],"branches":[{"senses":"S1 · S9","en":"THE VIEW AND THE FIELD: first the combined outlook, then the discipline that institutionalises it.","cn":"视角与学科：先是合并的眼光，再是把它制度化为一门学科。"},{"senses":"S2 · S3","en":"CIRCULATION AND ACCOUNTING: element turnover, then the stores and fluxes that measure it.","cn":"循环与核算：先是元素周转，再是衡量它的储库与通量。"},{"senses":"S4 · S7","en":"THE CONTACT ZONE: rock-water-microbe weathering, then ordinary natural processes of the same kind.","cn":"接触带：岩石与水与微生物的风化，再是同类寻常自然过程。"},{"senses":"S5 · S6","en":"EVIDENCE AND PREDICTION: chemical tracers, then coupled models.","cn":"证据与预测：先是化学示踪物，再是耦合模型。"},{"senses":"S8","en":"HUMAN DAMAGE: acid drainage, contamination and nutrient loading as biogeochemical problems.","cn":"人类造成的损害：酸性排水、污染与养分负荷成为生物地球化学问题。"}]},"affixes":{"intro":{"en":"Biogeochemical is a three-part Greek compound with an English adjective ending: life, earth and metalworking, joined by -al.","cn":"biogeochemical 是希腊语三部分复合词加上英语形容词词尾：生命、大地与冶炼，由 -al 连接。"},"latinIntro":{"en":"The roots are Greek and have no native Latin cognates; Latin acted only as a carrier, taking khēmeia through Arabic as alchimia and borrowing Greek terms such as geographia.","cn":"这些词根属希腊语，拉丁语中没有本土同族词；拉丁语只作传递通道，把 khēmeia 经阿拉伯语作 alchimia 传入，并借入 geographia 等希腊词。"},"items":[{"word":"bios","structure":"bios (Greek noun, masculine)","meaning":"life; a way of living","meaningCN":"生命；生活方式","example":"Bios is the root of biology.","exampleCN":"bios 是 biology 的词根。"},{"word":"gē","structure":"gē (Greek noun, feminine)","meaning":"earth; the ground","meaningCN":"大地；地面","example":"Gē gives the geo- of geology.","exampleCN":"gē 给出 geology 的 geo-。"},{"word":"khēmeia","structure":"khēmeia (Greek noun, 'art of metalworking')","meaning":"the craft of transforming metals","meaningCN":"改变金属的技艺","example":"Khēmeia travelled through Arabic into chemistry.","exampleCN":"khēmeia 经阿拉伯语进入 chemistry。"},{"word":"al-kīmiyā","structure":"al-kīmiyā (Arabic noun, with the definite article)","meaning":"alchemy, the art of transmutation","meaningCN":"炼金术，转化之术","example":"Al-kīmiyā became Medieval Latin alchimia.","exampleCN":"al-kīmiyā 变成中世纪拉丁 alchimia。"},{"word":"chemistry","structure":"chemistry (English noun from alchimia and earlier Greek khēmeia)","meaning":"the science of substances and their changes","meaningCN":"研究物质及其变化的科学","example":"Chemistry now names a laboratory science.","exampleCN":"chemistry 如今指一门实验科学。"},{"word":"biogeochemistry","structure":"bio- + geo- + chemistry","meaning":"the study of life, rock and chemical interaction","meaningCN":"研究生命、岩石与化学交互的学科","example":"Biogeochemistry grew out of biosphere science.","exampleCN":"生物地球化学由生物圈科学发展而来。"},{"word":"biogeochemical","structure":"biogeochemistry + -al (adjective suffix)","meaning":"belonging to that combined study","meaningCN":"属于那门合并研究的","example":"Biogeochemical data mix field and lab work.","exampleCN":"生物地球化学数据混合了野外与实验室工作。"},{"word":"geochemical","structure":"geo- + chemical + -al","meaning":"relating to earth chemistry alone","meaningCN":"只与地球化学有关的","example":"Geochemical surveys map ore bodies.","exampleCN":"地球化学测量绘制矿体分布。"},{"word":"biochemical","structure":"bio- + chemical + -al","meaning":"relating to chemistry inside organisms","meaningCN":"与生物体内化学有关的","example":"Biochemical assays measure enzymes.","exampleCN":"生化测定测量酶。"}],"latinEntries":[]}},{"word":"biogeochemical cycle","ipa_uk":"/ˌbaɪəʊdʒiːəʊˈkemɪkl ˈsaɪkl/","ipa_us":"/ˌbaɪoʊˌdʒiːoʊˈkemɪkəl ˈsaɪkəl/","definition_zh":"生物地球化学循环（元素在生物、地质与化学过程共同驱动下，在空气、水、岩石与生物体之间循环的过程）","definition_en":"the circulation of an element among air, water, rock and living organisms, driven jointly by biological, geological and chemical processes","core_image":"同一批原子在四个房间里轮转：空气、水、岩石、生命，每换一个房间就换一种化学身份，一本账记着进与出","scene":"课堂上老师把四个储库画成一个环路，让学生标出每一步的化学变化。The biogeochemical cycle of sulphur links volcanic rock, seawater and living cells.","sceneCN":"这里 biogeochemical cycle 指「元素在生物、地质与化学共同驱动下的整个循环」（第 1 个义项：作为整体过程）；句意为硫的生物地球化学循环把火山岩、海水与活细胞连在一起。","pos":[{"tag":"n.","zh":"生物地球化学循环（术语短语，常带定冠词；复数直接加 -s 指不同元素或不同系统的循环）"}],"collocations":[{"phrase":"global biogeochemical cycle","zh":"全球生物地球化学循环"},{"phrase":"coupled biogeochemical cycles","zh":"耦合的生物地球化学循环"},{"phrase":"biogeochemical cycle model","zh":"生物地球化学循环模型"},{"phrase":"biogeochemical cycle of carbon","zh":"碳的生物地球化学循环"},{"phrase":"marine biogeochemical cycle","zh":"海洋生物地球化学循环"},{"phrase":"perturbation of biogeochemical cycles","zh":"生物地球化学循环的扰动"}],"forms":[{"label":"带冠词用法","form":"the biogeochemical cycle"},{"label":"复数","form":"biogeochemical cycles"},{"label":"限定成分","form":"biogeochemical"},{"label":"核心名词","form":"cycle"},{"label":"相关术语（储库）","form":"reservoir"},{"label":"相关术语（通量）","form":"flux"}],"derivatives":[{"word":"biogeochemistry","pos":"n.","zh":"bio-（生命）+ geo-（大地）+ chemistry → 生物地球化学：研究生命、岩石与化学交互的学科"},{"word":"biogeochemical","pos":"adj.","zh":"biogeochemistry + -al → 生物地球化学的：属于该合并研究的"},{"word":"reservoir","pos":"n.","zh":"reservoir（法语 réservoir，源自 réserver「保留」）→ 储库：暂时容纳物质的库"},{"word":"flux","pos":"n.","zh":"flux（拉丁 fluxus「流动」，fluere「流」）→ 通量：单位时间通过的量"},{"word":"cycle","pos":"n.","zh":"希腊 kyklos「圆环」经拉丁 cyclus → 循环：回到起点的一轮过程"},{"word":"nutrient","pos":"n.","zh":"nutrire（拉丁「滋养」）+ -ent → 养分：供生物生长所需的物质"}],"senses":[{"no":"01","title":"The loop as a whole","titleCN":"作为整体的生物地球化学循环","definition":"the complete circuit of an element through air, water, rock and life","definitionCN":"元素经空气、水、岩石与生命体走完一圈的完整回路","example":"The biogeochemical cycle of sulphur links volcanic rock, seawater and living cells.","exampleCN":"硫的生物地球化学循环把火山岩、海水与活细胞连在一起。","why":"the phrase names a whole circuit in which biological, geological and chemical processes all take part.","whyCN":"这个短语命名的是一个完整回路，生物、地质与化学过程全都参与其中。"},{"no":"02","title":"Reservoirs","titleCN":"储库","definition":"the stores where an element sits, such as the atmosphere, ocean, soil or rock","definitionCN":"元素停留的储存处，如大气、海洋、土壤或岩石","example":"The ocean is the largest reservoir in most biogeochemical cycles of carbon.","exampleCN":"在多数碳的生物地球化学循环中，海洋是最大的储库。","why":"a cycle cannot be described until you say where the element waits.","whyCN":"不先说清元素在哪里等待，就无法描述一个循环。"},{"no":"03","title":"Fluxes","titleCN":"通量","definition":"the rates at which an element moves between reservoirs","definitionCN":"元素在储库之间移动的速率","example":"Fluxes in the biogeochemical cycle are measured in tonnes per year.","exampleCN":"生物地球化学循环中的通量以每年吨数计量。","why":"the loop is defined as much by its speeds as by its stores.","whyCN":"循环既由储库定义，也由速度定义。"},{"no":"04","title":"The biological half","titleCN":"生物那一半","definition":"uptake, assimilation, growth, death and decomposition carried out by organisms","definitionCN":"由生物完成的吸收、同化、生长、死亡与分解","example":"The biological half of the biogeochemical cycle runs on seasons.","exampleCN":"生物地球化学循环中生物的那一半随季节运转。","why":"life accelerates the loop by pulling elements into tissue and releasing them again.","whyCN":"生命通过把元素拉进组织再释放，加速了循环。"},{"no":"05","title":"The geological half","titleCN":"地质那一半","definition":"weathering, erosion, burial, sedimentation and tectonic uplift","definitionCN":"风化、侵蚀、埋藏、沉积与构造抬升","example":"The geological half of the biogeochemical cycle sets its long rhythm.","exampleCN":"地质那一半为生物地球化学循环定下漫长的节拍。","why":"rock stores and rock release give the loop its slow floor and ceiling.","whyCN":"岩石的储存与释放给了循环缓慢的下限与上限。"},{"no":"06","title":"Chemical transformation","titleCN":"化学形态转变","definition":"changes of oxidation state or bonding that decide whether an element can move or be used","definitionCN":"决定元素能否移动或可用的氧化态与键合变化","example":"Chemical transformation decides whether iron stays in rock or dissolves.","exampleCN":"化学形态转变决定铁留在岩石里还是溶解出来。","why":"the same atom behaves differently in each chemical form, so the loop is partly a sequence of reactions.","whyCN":"同一个原子在不同化学形态下行为不同，因此循环部分是一串反应。"},{"no":"07","title":"Coupled cycles","titleCN":"耦合的循环","definition":"the interlocking of element cycles so that a change in one alters the others","definitionCN":"各元素循环彼此扣合，一处变化会改动其余","example":"Coupled biogeochemical cycles explain why adding nitrogen changes how carbon is stored.","exampleCN":"耦合的生物地球化学循环解释了为何加入氮会改变碳的储存。","why":"elements do not cycle alone; the chemistry of one is the environment of another.","whyCN":"元素不会各自循环；一种元素的化学环境就是另一种元素的处境。"},{"no":"08","title":"Timescales and feedback","titleCN":"时间尺度与反馈","definition":"the fast biological loops and slow geological loops whose mismatch produces feedback","definitionCN":"快生物回路与慢地质回路之间的错配产生的反馈","example":"The mismatch of timescales inside the biogeochemical cycle is what makes it hard to model.","exampleCN":"生物地球化学循环内部时间尺度的错配，正是它难以建模的原因。","why":"a process that takes days and one that takes epochs obey different rules, and their friction is the feedback.","whyCN":"以天计的过程与以纪元计的过程遵守不同规则，它们的摩擦就是反馈。"},{"no":"09","title":"Human modification","titleCN":"人类改动","definition":"the altered fluxes caused by burning, fertilising, mining, damming and land clearing","definitionCN":"由燃烧、施肥、采矿、筑坝与开荒造成的通量改变","example":"Human activity has doubled several fluxes in the biogeochemical cycle of nitrogen.","exampleCN":"人类活动使氮的生物地球化学循环中多条通量翻倍。","why":"once people move more material than nature does, the cycle must be described with human terms.","whyCN":"一旦人搬运的物质超过自然，循环就必须用人类的词来描述。"}],"etymology":{"intro":{"en":"Biogeochemical cycle stacks Greek bios 'life', gē 'earth' and khēmeia 'metalworking', then adds kyklos 'wheel'. The phrase is a twentieth-century coinage of earth and life science, built once biogeochemistry became a recognised field in the 1920s.","cn":"biogeochemical cycle 叠起希腊 bios「生命」、gē「大地」与 khēmeia「冶炼」，再加上 kyklos「轮子」。这个短语是二十世纪地球与生命科学的造词，产生于生物地球化学在一九二〇年代成为公认领域之后。"},"items":[{"era":"GREEK BIOS","en":"Bios meant life and supplies the bio- of biology and biogeochemistry.","cn":"bios 意为生命，提供 biology 与 biogeochemistry 的 bio-。"},{"era":"GREEK GĒ","en":"Gē meant earth and gives the geo- of geology, geography and geochemistry.","cn":"gē 意为大地，给出 geology、geography 与 geochemistry 的 geo-。"},{"era":"GREEK KHĒMEIA","en":"Khēmeia named the art of working metals; through Arabic and Latin it became English chemistry.","cn":"khēmeia 指冶炼金属之术；经阿拉伯语与拉丁语成为英语 chemistry。"},{"era":"GREEK KYKLOS","en":"Kyklos 'circle, wheel' passed through Latin cyclus into English cycle.","cn":"kyklos「圆圈、轮子」经拉丁 cyclus 进入英语 cycle。"},{"era":"BIOGEOCHEMISTRY 1920S","en":"Vernadsky's biosphere work made the chemistry of life and rock a single subject, and the adjective followed.","cn":"维尔纳茨基的生物圈工作把生命与岩石的化学变成同一个课题，形容词随之出现。"},{"era":"THE PHRASE 1930S","en":"Mid-century earth scientists applied cycle to these coupled element flows, fixing the phrase in textbooks.","cn":"二十世纪中期的地球科学家把 cycle 用于这些耦合的元素流动，使这个短语固定在教科书里。"}]},"similar":{"note":{"en":"Group one holds the shorter or narrower terms that are mistaken for this phrase; group two holds the named element cycles it includes.","cn":"第一组是最容易被当成这个短语的较短或较窄术语；第二组是它所包含的具体元素循环。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"biogeochemical","ipa":"/ˌbaɪəʊdʒiːəʊˈkemɪkl/","tag":"the adjective only","definition":"Describing something that involves life, rock and chemistry; alone it names no circuit.","definitionCN":"描述同时涉及生命、岩石与化学的事物；单独使用并不命名任何回路。"},{"word":"geochemical cycle","ipa":"/ˌdʒiːəʊˈkemɪkl ˈsaɪkl/","tag":"no biology","definition":"A cycle of an element driven by rock and water alone; it leaves out the biological pump.","definitionCN":"仅由岩石与水驱动的元素循环；它不含生物泵。"},{"word":"nutrient cycle","ipa":"/ˈnjuːtriənt ˈsaɪkl/","tag":"ecosystem scale","definition":"The recycling of nutrients within an ecosystem; it is a small, fast subset of the larger cycle.","definitionCN":"生态系统内部的养分回收；它是更大循环中一个小而快的子集。"},{"word":"element cycle","ipa":"/ˈelɪmənt ˈsaɪkl/","tag":"a generic label","definition":"Any circulation of a chemical element; the term says nothing about how many processes drive it.","definitionCN":"任何化学元素的循环；这个说法不说明由多少种过程驱动。"}]},{"heading":"NEAR MEANING","entries":[{"word":"carbon cycle","ipa":"/ˈkɑːbən ˈsaɪkl/","tag":"one instance","definition":"The circulation of carbon among air, sea, rock and life; it is the best-known biogeochemical cycle.","definitionCN":"碳在空气、海洋、岩石与生命之间的循环；它是最著名的生物地球化学循环。"},{"word":"nitrogen cycle","ipa":"/ˈnaɪtrədʒən ˈsaɪkl/","tag":"one instance","definition":"The circulation of nitrogen, notable for its huge atmospheric store and microbial steps.","definitionCN":"氮的循环，以巨大的大气储库与微生物步骤著称。"},{"word":"sedimentary cycle","ipa":"/ˌsedɪˈmentri ˈsaɪkl/","tag":"a type","definition":"A cycle dominated by rock stores rather than air, such as phosphorus; it is one kind of biogeochemical cycle.","definitionCN":"由岩石储库而非空气主导的循环，如磷循环；它是生物地球化学循环的一种。"},{"word":"earth system","ipa":"/ɜːθ ˈsɪstəm/","tag":"the container, not the motion","definition":"The planet's interacting air, water, rock and life; cycles run inside it but it is not a cycle.","definitionCN":"行星互相作用的空气、水、岩石与生命；循环在其中运行，但它本身不是循环。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the four real roots plus the four real reservoirs of any element cycle.","cn":"正常联想：四个真实词根，加上任何元素循环的四个真实储库。"},"normal":[{"en":"bio is life, geo is earth, chemical is metalworking, cycle is a wheel: life and earth turning chemistry in a circle.","cn":"bio 是生命，geo 是大地，chemical 是冶炼，cycle 是轮子：生命与大地把化学转成一个圈。"},{"en":"Four reservoirs: air, water, rock, life.","cn":"四个储库：空气、水、岩石、生命。"},{"en":"Two speeds: seasons for biology, epochs for geology.","cn":"两种速度：生物按季节，地质按纪元。"},{"en":"One accounting trick: store plus flux equals the whole story.","cn":"一个核算诀窍：储库加通量就是全部故事。"},{"en":"Vernadsky is the anchor name for the field behind the phrase.","cn":"维尔纳茨基是这个短语背后学科的关键名字。"}],"abstract":[{"en":"It is a relay race in which the baton is an atom and the runners are a forest, a river and a volcano.","cn":"它是一场接力赛，接力棒是一个原子，跑者是森林、河流与火山。"},{"en":"The cycle is a conversation between the fast and the slow.","cn":"这个循环是一场快与慢之间的对话。"},{"en":"Nothing is wasted; everything is only between appointments.","cn":"没有东西被浪费，一切只是处在两次约见之间。"}]},"examples":[{"en":"Each element has its own biogeochemical cycle, but the cycles interact.","cn":"每种元素各有自己的生物地球化学循环，但各循环彼此作用。"},{"en":"Ocean eddies influence the biogeochemical cycle of iron in the Southern Ocean.","cn":"海洋涡旋影响南大洋中铁的生物地球化学循环。"},{"en":"The course compares the biogeochemical cycle of carbon with that of phosphorus.","cn":"这门课比较碳与磷的生物地球化学循环。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"bio（生命）+ geo（大地）+ chemical（化学）+ cycle（循环）＝生命与大地共同把元素转一圈；记四个储库与两种速度。","word":"biogeochemical cycle"},"root":"bio-（希腊 bios「生命」）+ geo-（希腊 gē「大地」）+ chemical（希腊 khēmeia「冶炼术」）+ cycle（希腊 kyklos「圆环」）；短语为二十世纪地球科学所立。","sensesIntro":{"en":"Nine senses move from the whole to its parts and uses: the circuit, reservoirs, fluxes, the biological half, the geological half, chemical form, coupling, timescale feedback and human change.","cn":"九个义项从整体走向部件与用途：回路、储库、通量、生物那一半、地质那一半、化学形态、耦合、时间尺度反馈，以及人类改动。"},"semanticMap":{"core":{"en":"CORE IMAGE: one atom leaving air for a leaf, then soil, then a river, then a shell on the seabed, then rock, then a volcano, then air again.","cn":"核心意象：一个原子离开空气进入叶片，再到土壤、河流、海底贝壳、岩石、火山，最后回到空气。"},"chain":["ATMOSPHERE","LIVING TISSUE","SOIL AND WATER","SEDIMENT","ROCK","VOLCANO AND WEATHERING"],"branches":[{"senses":"S1 · S8","en":"WHOLE AND RHYTHM: the circuit, then the mismatch of fast and slow loops that creates feedback.","cn":"整体与节拍：先是回路，再是快慢回路错配造成的反馈。"},{"senses":"S2 · S3","en":"STATICS AND MOTION: reservoirs, then the fluxes between them.","cn":"静与动：先是储库，再是储库之间的通量。"},{"senses":"S4 · S5","en":"TWO HALVES: the biological pump and the geological engine.","cn":"两半：生物泵与地质引擎。"},{"senses":"S6","en":"CHEMICAL FORM: oxidation state and bonding deciding mobility.","cn":"化学形态：氧化态与键合决定迁移能力。"},{"senses":"S7 · S9","en":"COUPLING AND HUMAN CHANGE: linked cycles, then the fluxes people have rewritten.","cn":"耦合与人类改动：先是彼此扣合的循环，再是人改写过的通量。"}]},"affixes":{"intro":{"en":"Biogeochemical cycle joins three Greek roots and an English adjective ending to a Greek noun for a wheel.","cn":"biogeochemical cycle 把三个希腊词根与一个英语形容词词尾，接在一个表示轮子的希腊名词上。"},"latinIntro":{"en":"All four roots are Greek; Latin carried khēmeia through Arabic as alchimia and borrowed kyklos as cyclus, but has no native cognates for bios or gē.","cn":"四个词根都属希腊语；拉丁语把 khēmeia 经阿拉伯语作 alchimia 传入，并借入 kyklos 作 cyclus，但 bios 与 gē 在拉丁语中无本土同族词。"},"items":[{"word":"bios","structure":"bios (Greek noun)","meaning":"life","meaningCN":"生命","example":"Bios opens the compound.","exampleCN":"bios 开启了这个复合词。"},{"word":"gē","structure":"gē (Greek noun)","meaning":"earth; ground","meaningCN":"大地；地面","example":"Gē supplies the middle element.","exampleCN":"gē 提供了中间那个成分。"},{"word":"khēmeia","structure":"khēmeia (Greek noun)","meaning":"the art of metalworking","meaningCN":"冶炼金属的技艺","example":"Khēmeia became chemistry.","exampleCN":"khēmeia 变成了 chemistry。"},{"word":"chemistry","structure":"chemistry (English noun, via alchimia)","meaning":"the science of substances","meaningCN":"研究物质的科学","example":"Chemistry supplies the third part.","exampleCN":"chemistry 提供第三部分。"},{"word":"biogeochemistry","structure":"bio- + geo- + chemistry","meaning":"the study of life, rock and chemistry together","meaningCN":"合并研究生命、岩石与化学的学科","example":"Biogeochemistry named the field in the 1920s.","exampleCN":"生物地球化学在一九二〇年代为这个领域命名。"},{"word":"kyklos","structure":"kyklos (Greek noun)","meaning":"circle; wheel","meaningCN":"圆圈；轮子","example":"Kyklos ends the phrase.","exampleCN":"kyklos 收尾这个短语。"},{"word":"cycle","structure":"cycle (English noun from Latin cyclus)","meaning":"a returning process","meaningCN":"回归性的过程","example":"The cycle returns the element to its start.","exampleCN":"循环把元素送回起点。"},{"word":"reservoir","structure":"reservoir (French noun from réserver 'to reserve')","meaning":"a store that holds something","meaningCN":"容纳某物的储库","example":"Each reservoir has a capacity.","exampleCN":"每个储库都有容量。"},{"word":"flux","structure":"fluxus (Latin 'a flowing', from fluere)","meaning":"a rate of flow","meaningCN":"流动的速率","example":"Flux is measured per year.","exampleCN":"通量按年计量。"}],"latinEntries":[{"word":"fluxus","structure":"fluxus, -us (n., fourth declension)","meaning":"a flowing; flow","meaningCN":"流动；流"},{"word":"cyclus","structure":"cyclus, -i (n., second declension, from Greek)","meaning":"circle; cycle","meaningCN":"圆环；循环"}]}},{"word":"carbon sequestration","ipa_uk":"/ˈkɑːbən ˌsiːkwəˈstreɪʃn/","ipa_us":"/ˈkɑːrbən ˌsiːkwəˈstreɪʃən/","definition_zh":"碳封存（把二氧化碳从大气中移除并长期储存在植被、土壤、海洋或地质构造中的过程）","definition_en":"the removal of carbon dioxide from the atmosphere and its long-term storage in biomass, soil, the ocean or geological formations","core_image":"烟囱里的气被捕获、压缩、注入地下砂岩层；另一条路上，森林与土壤把碳慢慢收进木头与腐殖质里锁住","scene":"工程师在图上把电厂排出的气导入地下深处的砂岩层。Forest regrowth offers cheap carbon sequestration, though the storage is reversible.","sceneCN":"这里 carbon sequestration 指「把二氧化碳移除并长期储存的过程」（第 1 个义项：作为整体行为）；句意为森林再生长提供了廉价的碳封存，尽管这种储存可逆。","pos":[{"tag":"n.","zh":"碳封存（不可数术语短语；工程语境中可加不定冠词指具体项目）"}],"collocations":[{"phrase":"carbon sequestration capacity","zh":"碳封存容量"},{"phrase":"geological carbon sequestration","zh":"地质碳封存"},{"phrase":"biological carbon sequestration","zh":"生物碳封存"},{"phrase":"soil carbon sequestration","zh":"土壤碳封存"},{"phrase":"carbon sequestration project","zh":"碳封存项目"},{"phrase":"carbon sequestration potential","zh":"碳封存潜力"}],"forms":[{"label":"不可数用法","form":"carbon sequestration"},{"label":"核心名词","form":"sequestration"},{"label":"动词","form":"sequester"},{"label":"过去分词作形容词","form":"sequestered"},{"label":"限定成分","form":"carbon"}],"derivatives":[{"word":"sequestration","pos":"n.","zh":"sequestrare（拉丁「隔离、托管」）+ -ation → 封存：把某物隔开并保管起来"},{"word":"sequester","pos":"v.","zh":"sequester（拉丁「受托人、中间人」）→ 隔离、扣押、封存：把东西放到别处保管"},{"word":"sequestrate","pos":"v.","zh":"sequestrare 的英语动词形 → 依法扣押、强制管理：法律上的隔离"},{"word":"carbon","pos":"n.","zh":"拉丁 carbo（木炭）→ 碳：以炭命名的元素"},{"word":"carbonate","pos":"n./v.","zh":"carbon + -ate → 碳酸盐；使碳酸化"},{"word":"capture","pos":"n./v.","zh":"capere（拉丁「抓取」）→ 捕获：把气流中的二氧化碳抓住"},{"word":"storage","pos":"n.","zh":"store（古法语 estore，源自拉丁 instaurare「恢复、置备」）+ -age → 储存：把东西收起来备用"}],"senses":[{"no":"01","title":"Capture plus durable storage","titleCN":"捕获加长期储存","definition":"the deliberate removal of carbon dioxide from the air or a flue gas and its secure long-term storage","definitionCN":"有意从空气或烟道气中移除二氧化碳并安全长期储存","example":"Forest regrowth offers cheap carbon sequestration, though the storage is reversible.","exampleCN":"森林再生长提供了廉价的碳封存，尽管这种储存可逆。","why":"both halves matter: without capture nothing is removed, without storage the gas simply returns.","whyCN":"两半都重要：没有捕获就没有移除，没有储存气体就会回来。"},{"no":"02","title":"Biological uptake","titleCN":"生物吸收：森林与湿地","definition":"carbon stored in wood, roots and wetland peat as plants grow","definitionCN":"植物生长时把碳存进木材、根系与湿地泥炭","example":"Biological carbon sequestration depends on how long the trees live.","exampleCN":"生物碳封存取决于树木活多久。","why":"photosynthesis is the oldest capture technology, and living biomass is its first warehouse.","whyCN":"光合作用是最古老的捕获技术，活体生物量是它的第一座仓库。"},{"no":"03","title":"Soil carbon","titleCN":"土壤碳","definition":"carbon held in humus and soil organic matter for decades to centuries","definitionCN":"在腐殖质与土壤有机质中保存数十年至数百年的碳","example":"Soil carbon sequestration is slow to build and quick to lose.","exampleCN":"土壤碳封存积累得慢，失去得却快。","why":"the largest land store is underground, and farming practices decide whether it grows.","whyCN":"最大的陆地储库在地下，农作方式决定它是否增长。"},{"no":"04","title":"Geological storage","titleCN":"地质封存","definition":"carbon dioxide injected into saline aquifers, depleted oil or gas fields, or deep coal seams","definitionCN":"把二氧化碳注入咸水层、枯竭油气田或深部煤层","example":"Geological carbon sequestration needs rock that will hold gas for millennia.","exampleCN":"地质碳封存需要能把气体留住数千年的岩石。","why":"the industrial method imitates what rock has always done: trap fluid for long spans.","whyCN":"工业方法只是模仿岩石一直在做的事：长时间困住流体。"},{"no":"05","title":"Ocean storage","titleCN":"海洋封存","definition":"carbon taken up by seawater or deliberately injected into the deep ocean","definitionCN":"由海水吸收或有意注入深海的碳","example":"Ocean carbon sequestration already happens without any engineering.","exampleCN":"海洋碳封存无需任何工程就已经在发生。","why":"the sea absorbs gas at the surface and carries it down with currents and sinking particles.","whyCN":"海洋在表层吸收气体，并用洋流与下沉颗粒把它带走。"},{"no":"06","title":"Mineralisation","titleCN":"矿化：变成石头","definition":"the conversion of carbon dioxide into stable carbonate minerals, sometimes accelerated by crushed rock","definitionCN":"把二氧化碳转成稳定的碳酸盐矿物，有时用碎石加速","example":"Mineralisation turns carbon sequestration into permanent stone.","exampleCN":"矿化把碳封存变成永久的石头。","why":"if carbon becomes a mineral, leakage is no longer a risk.","whyCN":"如果碳变成矿物，泄漏就不再是风险。"},{"no":"07","title":"Permanence and leakage","titleCN":"持久性与泄漏","definition":"the question of how long storage lasts and whether monitoring can prove it","definitionCN":"储存能维持多久，以及监测能否证明这一点","example":"Permanence is the weak point of most carbon sequestration claims.","exampleCN":"持久性是多数碳封存主张的软肋。","why":"a store that leaks is not a store, so duration and verification become the real measure.","whyCN":"会漏的储库不算储库，因此时长与核查成了真正的衡量标准。"},{"no":"08","title":"Accounting and policy","titleCN":"核算与政策","definition":"credits, offset schemes and regulations that pay for or require removal","definitionCN":"为移除付费或作出要求的信用、抵消机制与法规","example":"Carbon sequestration credits pay landholders for measured storage.","exampleCN":"碳封存信用为可测量的储存向土地持有者付费。","why":"once storage can be measured, it can be bought, sold and regulated.","whyCN":"一旦储存可测量，它就能被买卖与监管。"},{"no":"09","title":"Natural versus engineered","titleCN":"自然与工程之分","definition":"the distinction between passive uptake by ecosystems and active industrial capture","definitionCN":"生态系统被动吸收与工业主动捕获之间的区别","example":"The debate over carbon sequestration turns on natural uptake versus engineered removal.","exampleCN":"关于碳封存的争论，关键在于自然吸收与工程移除之别。","why":"the same phrase covers a forest and a pipeline, so it carries a built-in ambiguity.","whyCN":"同一个短语既指森林也指管道，因此自带一层歧义。"}],"etymology":{"intro":{"en":"Carbon sequestration joins the Latin-derived name of an element to a Latin legal verb meaning 'to set aside for safekeeping'. Sequestration entered English in the fifteenth century as a term about property and juries; the climate sense is late twentieth century. The deeper origin of sequester is uncertain (source uncertain), and it is generally thought to be related to sequi 'to follow'.","cn":"carbon sequestration 把拉丁语源的元素名接在一个意为「另行保管」的拉丁法律动词上。sequestration 于十五世纪进入英语，用于财产与陪审团；气候义项则是二十世纪后期。sequester 的更早来源不确定，一般认为与 sequi「跟随」有关。"},"items":[{"era":"LATIN SEQUESTER","en":"Sequester named a trustee or mediator who held property in dispute; its deeper origin is uncertain (source uncertain), and it is generally thought to be related to sequi 'to follow'.","cn":"sequester 指在争议中托管财产的受托人或中间人；其更早来源不确定，一般认为与 sequi「跟随」有关。"},{"era":"SEQUESTRARE","en":"The verb sequestrare meant to separate something and place it in safe keeping, a legal move rather than a physical one.","cn":"动词 sequestrare 意为把某物分开并放到安全保管处，先是法律动作而非物理动作。"},{"era":"SEQUESTRATION 1400S","en":"English sequestration first meant the setting aside of disputed property or the isolation of a jury.","cn":"英语 sequestration 最初指把有争议的财产另行保管，或把陪审团隔离。"},{"era":"CARBON 1789","en":"Lavoisier's circle fixed carbone as the element's name; English took it as carbon.","cn":"拉瓦锡一派把 carbone 定为该元素之名；英语取用为 carbon。"},{"era":"THE PHRASE 1970S","en":"Scientists studying greenhouse warming borrowed the legal word to mean the removal of carbon dioxide from circulation.","cn":"研究温室升温的科学家借用了这个法律词，用来指把二氧化碳从循环中移除。"},{"era":"CCS 1990S","en":"The acronym for carbon capture and storage fixed the phrase in energy policy and engineering.","cn":"碳捕集与封存的缩写在能源政策与工程中固定了这个短语。"}]},"similar":{"note":{"en":"Group one holds the carbon-management terms most easily confused with sequestration itself; group two holds the wider removal and accounting terms.","cn":"第一组是最容易与封存本身混淆的碳管理术语；第二组是更宽的移除与核算术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"carbon capture","ipa":"/ˈkɑːbən ˈkæptʃə/","tag":"only the first half","definition":"The separation of carbon dioxide from a gas stream; it does not by itself guarantee storage.","definitionCN":"把二氧化碳从气流中分离出来；它本身并不保证储存。"},{"word":"carbon storage","ipa":"/ˈkɑːbən ˈstɔːrɪdʒ/","tag":"only the second half","definition":"Keeping captured carbon in a reservoir; it assumes capture has already happened.","definitionCN":"把已捕获的碳保存在储库中；它假定捕获已经完成。"},{"word":"carbon sink","ipa":"/ˈkɑːbən sɪŋk/","tag":"a place, not a process","definition":"A reservoir that absorbs more carbon than it releases; sequestration is the act that fills it.","definitionCN":"吸收多于释放的储库；封存是把它填满的行为。"},{"word":"sequestration","ipa":"/ˌsiːkwəˈstreɪʃn/","tag":"the bare legal word","definition":"The general act of setting something aside; without carbon it may mean a jury, property or a budget cut.","definitionCN":"另行保管的一般行为；不带 carbon 时，它可能指陪审团、财产或预算削减。"}]},{"heading":"NEAR MEANING","entries":[{"word":"carbon removal","ipa":"/ˈkɑːbən rɪˈmuːvl/","tag":"the umbrella goal","definition":"Any deliberate taking of carbon dioxide out of the air; sequestration is one family of methods for it.","definitionCN":"任何有意把二氧化碳从空气中取走的行为；封存是其中一类方法。"},{"word":"carbon offset","ipa":"/ˈkɑːbən ˈɒfset/","tag":"a financial instrument","definition":"A credit bought to compensate for emissions elsewhere; it may or may not fund real sequestration.","definitionCN":"为抵消他处排放而购买的信用；它未必资助真正的封存。"},{"word":"negative emissions","ipa":"/ˈneɡətɪv ɪˈmɪʃnz/","tag":"the net result","definition":"A net removal of carbon dioxide from the atmosphere; sequestration is one route to it.","definitionCN":"从大气中净移除二氧化碳；封存是达到它的一条路径。"},{"word":"carbon cycle","ipa":"/ˈkɑːbən ˈsaɪkl/","tag":"the whole system","definition":"The full circulation of carbon among air, sea, rock and life; sequestration deliberately shifts one flux in it.","definitionCN":"碳在空气、海洋、岩石与生命之间的完整循环；封存有意改变其中一条通量。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin legal root and the real physical routes carbon can take.","cn":"正常联想：真实的拉丁法律词根，以及碳实际能走的物理路径。"},"normal":[{"en":"Sequestration is a courtroom word: property set aside, now gas set aside.","cn":"sequestration 本是法庭用语：财产被另行保管，如今是气体被另行保管。"},{"en":"Sequester is the verb, sequestration the act, sequestered the state.","cn":"sequester 是动词，sequestration 是行为，sequestered 是状态。"},{"en":"Three warehouses: trees, soil, rock. The sea is a fourth, less controllable one.","cn":"三座仓库：树木、土壤、岩石。海洋是第四座，较难控制。"},{"en":"Capture is the front door, storage is the vault, permanence is the lock.","cn":"捕获是前门，储存是金库，持久性是那把锁。"},{"en":"If it leaks, it was not sequestration but delay.","cn":"如果它漏了，那就不是封存，只是拖延。"}],"abstract":[{"en":"Carbon sequestration is putting a genie back into a bottle made of stone.","cn":"碳封存是把精灵塞回一只石头做的瓶子里。"},{"en":"It is a loan taken from the atmosphere, and the term is the interest rate.","cn":"它是向大气借的一笔款，期限就是利率。"},{"en":"A forest is a vault that can walk away.","cn":"森林是一座会走掉的金库。"}]},"examples":[{"en":"The plant is a test of carbon sequestration at industrial scale.","cn":"这座工厂是对工业规模碳封存的检验。"},{"en":"Carbon sequestration in soils depends on how the land is farmed.","cn":"土壤中的碳封存取决于土地如何耕作。"},{"en":"Critics say carbon sequestration promises storage that no one can guarantee.","cn":"批评者认为碳封存承诺了无人能保证的储存。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"carbon（碳）+ sequestration（另行保管）＝把二氧化碳抓走并锁进森林、土壤、海洋或岩层；记三道门：捕获、储存、持久。","word":"carbon sequestration"},"root":"carbon（拉丁 carbo「木炭」）+ sequestration（拉丁 sequestrare「分开并保管」，源自 sequester「受托人」，更早来源不确定，一般认为与 sequi「跟随」有关）。","sensesIntro":{"en":"Nine senses follow the carbon from capture to credit: the whole act, forests, soil, geological storage, the ocean, mineralisation, permanence, accounting and the natural-engineered split.","cn":"九个义项跟碳从捕获走到信用：整体行为、森林、土壤、地质储存、海洋、矿化、持久性、核算，以及自然与工程之分。"},"semanticMap":{"core":{"en":"CORE IMAGE: gas is caught at a chimney, compressed, piped into sandstone, and years later a monitor confirms it has not moved.","cn":"核心意象：气体在烟囱处被抓住，压缩后送进砂岩，多年后一台监测器确认它没有移动。"},"chain":["CAPTURE GAS","COMPRESS","INJECT OR ABSORB","LOCK IN STORE","MONITOR LEAKAGE","COUNT AS CREDIT"],"branches":[{"senses":"S1 · S9","en":"THE ACT AND ITS TWO FORMS: capture plus storage, then the split between natural and engineered versions.","cn":"行为及其两种形态：捕获加储存，再是自然与工程版本之分。"},{"senses":"S2 · S3","en":"THE LAND: wood and peat above ground, humus below it.","cn":"陆地：地上的木材与泥炭，地下的腐殖质。"},{"senses":"S4 · S5","en":"UNDERGROUND AND UNDERWATER: saline aquifers and depleted fields, then the deep ocean.","cn":"地下与水下：先是咸水层与枯竭油气田，再是深海。"},{"senses":"S6","en":"STONE: carbon turned into carbonate mineral, where leakage stops being possible.","cn":"石头：碳变成碳酸盐矿物，泄漏从此不再可能。"},{"senses":"S7 · S8","en":"PROOF AND PAYMENT: permanence checked by monitoring, then credits and rules.","cn":"证明与付款：先由监测核查持久性，再是信用与规则。"}]},"affixes":{"intro":{"en":"Carbon sequestration is a two-word technical phrase: a Latin-derived element name plus a Latin-derived noun of legal origin.","cn":"carbon sequestration 是两词技术短语：拉丁语源的元素名，加一个源于法律的拉丁语源名词。"},"latinIntro":{"en":"Latin carbo gives carbon; sequester and sequestrare give sequestration; capere gives capture and instaurare lies behind storage.","cn":"拉丁 carbo 给出 carbon；sequester 与 sequestrare 给出 sequestration；capere 给出 capture，storage 背后则是 instaurare。"},"items":[{"word":"carbo","structure":"carbo, carbonis (Latin noun)","meaning":"charcoal; ember","meaningCN":"木炭；炭火","example":"Carbo is the source of carbon.","exampleCN":"carbo 是 carbon 的来源。"},{"word":"carbon","structure":"carbone (French coinage) + English adaptation","meaning":"the element of charcoal","meaningCN":"木炭所含的那种元素","example":"Carbon is the object being stored.","exampleCN":"碳是被储存的对象。"},{"word":"sequester","structure":"sequester (Latin noun, 'trustee, mediator')","meaning":"one who holds disputed property","meaningCN":"保管争议财产的人","example":"Sequester began as a legal person, not a gas.","exampleCN":"sequester 最初指一个法律上的人，而非气体。"},{"word":"sequestrare","structure":"sequestrare (Latin verb, first conjugation)","meaning":"to set aside and keep safe","meaningCN":"另行放置并保管","example":"Sequestrare is the verb behind sequestration.","exampleCN":"sequestrare 是 sequestration 背后的动词。"},{"word":"sequestration","structure":"sequestrare + -ation (noun suffix)","meaning":"the act of setting aside","meaningCN":"另行保管的行为","example":"Sequestration kept its legal tone for centuries.","exampleCN":"sequestration 的法律语气维持了数百年。"},{"word":"capere","structure":"capere (Latin verb, third conjugation)","meaning":"to seize; to take","meaningCN":"抓取；拿取","example":"Capere gives capture.","exampleCN":"capere 给出 capture。"},{"word":"capture","structure":"captura (Latin 'a catching') from capere","meaning":"the act of catching a gas stream","meaningCN":"抓住气流的行为","example":"Capture is the first stage.","exampleCN":"捕获是第一道工序。"},{"word":"instaurare","structure":"instaurare (Latin verb, first conjugation)","meaning":"to set up; to restore","meaningCN":"设置；恢复","example":"Instaurare lies behind Old French estore and English store.","exampleCN":"instaurare 是古法语 estore 与英语 store 的背后来源。"},{"word":"storage","structure":"store + -age (noun suffix)","meaning":"the keeping of something for later use","meaningCN":"把某物留存备用","example":"Storage is the second stage.","exampleCN":"储存是第二道工序。"}],"latinEntries":[{"word":"carbo","structure":"carbo, carbonis (n., third declension)","meaning":"charcoal; ember","meaningCN":"木炭；炭火"},{"word":"sequester","structure":"sequester (n., third declension)","meaning":"trustee; mediator","meaningCN":"受托人；中间人"},{"word":"sequestrare","structure":"sequestrare (verb, first conjugation)","meaning":"to set aside; to sequestrate","meaningCN":"另行放置；扣押"},{"word":"capere","structure":"capere (verb, third conjugation)","meaning":"to seize; to take","meaningCN":"抓取；拿取"}]}},{"word":"sequestration","ipa_uk":"/ˌsiːkwəˈstreɪʃn/","ipa_us":"/ˌsiːkwəˈstreɪʃən/","definition_zh":"隔离、扣押、封存（把某物分开并另行保管的行为；法律、财政、医学与气候语境各有专指）","definition_en":"the act of setting something apart and keeping it in safekeeping, with specialised meanings in law, budgeting, medicine and climate policy","core_image":"一件有争议的财物被锁进第三方的柜子，钥匙不在当事人手里；同一动作移到陪审团、病人或预算上，各自成了一种隔离","scene":"法庭上法官下令把陪审团与外界隔开，以免他们读到案情报道。The sequestration of the jury kept them away from news reports during the trial.","sceneCN":"这里 sequestration 指「把陪审团与外界隔离」（第 2 个义项：陪审团隔离）；句意为对陪审团的隔离使他们在庭审期间接触不到新闻报道。","pos":[{"tag":"n.","zh":"隔离；扣押；封存（可数指一次具体隔离，不可数指行为本身）"}],"collocations":[{"phrase":"jury sequestration","zh":"陪审团隔离"},{"phrase":"budget sequestration","zh":"预算自动削减"},{"phrase":"carbon sequestration","zh":"碳封存"},{"phrase":"sequestration order","zh":"扣押令"},{"phrase":"pulmonary sequestration","zh":"肺隔离症"},{"phrase":"sequestration of assets","zh":"资产扣押"}],"forms":[{"label":"不可数用法","form":"sequestration"},{"label":"复数","form":"sequestrations"},{"label":"动词","form":"sequester"},{"label":"法律动词","form":"sequestrate"},{"label":"形容词","form":"sequestrated"}],"derivatives":[{"word":"sequester","pos":"v.","zh":"sequester（拉丁「受托人」）→ 隔离、扣押、封存：把某物放到别处保管"},{"word":"sequestrate","pos":"v.","zh":"sequestrare（拉丁「另行保管」）的英语动词形 → 依法扣押：法律上的强制隔离"},{"word":"sequestrated","pos":"adj.","zh":"sequestrate + -ed（过去分词形容词）→ 被扣押的：处于强制保管状态"},{"word":"sequestrum","pos":"n.","zh":"sequestrum（拉丁「寄存物」）→ 死骨片：与健康骨分离的一块骨"},{"word":"sequestrotomy","pos":"n.","zh":"sequestrum + -otomy（希腊「切开」）→ 死骨切除术"}],"senses":[{"no":"01","title":"Setting something apart","titleCN":"把某物另行放置","definition":"the general act of separating a thing from ordinary use and holding it elsewhere","definitionCN":"把某物从日常使用中分出、另存他处的总称","example":"Sequestration in its oldest sense simply means setting a disputed thing aside.","exampleCN":"sequestration 最古老的含义只是把有争议的东西另行放置。","why":"every specialised sense keeps this core move: separation plus custody.","whyCN":"每个专门义项都保留这个核心动作：分开加保管。"},{"no":"02","title":"Jury isolation","titleCN":"陪审团隔离","definition":"the confinement of jurors away from public contact and news during a trial","definitionCN":"庭审期间让陪审员与公众接触和新闻隔绝","example":"The sequestration of the jury kept them away from news reports during the trial.","exampleCN":"对陪审团的隔离使他们在庭审期间接触不到新闻报道。","why":"a verdict must rest only on evidence heard in court, so the jury is physically set apart.","whyCN":"裁决必须只依据庭上听到的证据，因此陪审团被物理地隔开。"},{"no":"03","title":"Property in custody","titleCN":"争议财产的扣押","definition":"the legal holding of disputed property by a third party until a case is decided","definitionCN":"案件裁断前由第三方保管争议财产","example":"A sequestration order froze the company's accounts during the dispute.","exampleCN":"一项扣押令在争议期间冻结了公司的账户。","why":"the word began as a trustee holding property, so the legal sense is the ancestral one.","whyCN":"这个词最初指受托保管财产的受托人，因此法律义项是它的祖义。"},{"no":"04","title":"Automatic budget cuts","titleCN":"预算自动削减","definition":"mandatory across-the-board spending reductions triggered when budget limits are breached","definitionCN":"预算上限被突破时触发的强制性全面开支削减","example":"Budget sequestration cut both defence and domestic programmes.","exampleCN":"预算自动削减同时砍掉了国防与国内项目。","why":"the money is set aside by rule rather than by negotiation, which is exactly the old legal move applied to a treasury.","whyCN":"这笔钱按规则而非谈判被扣下，正是古老的法律动作用在国库上。"},{"no":"05","title":"The lung anomaly","titleCN":"肺隔离症","definition":"a congenital mass of lung tissue that has no normal connection to the airway","definitionCN":"一块与气道没有正常连接的先天性肺组织","example":"Pulmonary sequestration is usually found on one side of the chest.","exampleCN":"肺隔离症通常见于胸腔的一侧。","why":"the tissue is literally separated from the airway it should serve, so medicine borrowed the word for anatomy.","whyCN":"那块组织确实与它本该服务的气道分开，因此医学借用了这个词来指解剖。"},{"no":"06","title":"Chemical binding","titleCN":"化学螯合与固定","definition":"the locking of an ion or compound into a stable complex so it cannot react freely","definitionCN":"把离子或化合物锁进稳定络合物使其不能自由反应","example":"Chemical sequestration of metals reduces their toxicity in soil.","exampleCN":"金属的化学固定降低了它们在土壤中的毒性。","why":"the substance is held by another molecule the way property is held by a trustee.","whyCN":"物质被另一个分子握住，就像财产被受托人保管。"},{"no":"07","title":"Carbon sequestration","titleCN":"碳封存","definition":"the removal of carbon dioxide from the atmosphere and its long-term storage","definitionCN":"把二氧化碳从大气中移除并长期储存","example":"Carbon sequestration is counted only if the storage lasts for centuries.","exampleCN":"碳封存只有在储存延续数百年时才被计入。","why":"the climate sense applies the legal idea to a gas: take it out of circulation and put it under guard.","whyCN":"气候义项把法律观念用在气体上：让它退出循环并置于看管之下。"},{"no":"08","title":"Ecclesiastical holding","titleCN":"教会财产的代管","definition":"the temporary transfer of a benefice or church income to another custodian","definitionCN":"把教职俸禄或教会收入临时交给另一位代管人","example":"The sequestration of the parish income lasted until a new priest was appointed.","exampleCN":"该堂区收入的代管一直持续到新司铎被任命。","why":"church law inherited the Roman idea of a neutral custodian for property in dispute.","whyCN":"教会法继承了罗马法为争议财产设中立保管人的观念。"},{"no":"09","title":"Being cut off","titleCN":"被隔断的状态","definition":"a figurative condition of isolation or withdrawal from normal relations","definitionCN":"与正常联系相隔绝的比喻状态","example":"The sequestration of the village by snow left it outside all supply routes.","exampleCN":"大雪对村庄的隔绝使它脱离了所有补给路线。","why":"the core image survives in plain speech whenever something is shut away from the rest.","whyCN":"只要有某物被隔开在其余之外，这个核心意象就在日常语言中存活。"}],"etymology":{"intro":{"en":"Sequestration comes from Latin sequestrare 'to set aside, to give into custody', built on sequester, a trustee or mediator who held disputed property. The deeper origin of sequester is uncertain (source uncertain), and it is generally thought to be related to sequi 'to follow'. English took the word in the fifteenth century as a legal term.","cn":"sequestration 来自拉丁 sequestrare「另行放置、交付保管」，其词基 sequester 指保管争议财产的受托人或中间人。sequester 的更早来源不确定，一般认为与 sequi「跟随」有关。英语于十五世纪作为法律术语借入。"},"items":[{"era":"LATIN SEQUESTER","en":"A sequester was a neutral party who held property while a dispute was pending; its deeper origin is uncertain (source uncertain), and it is generally thought to be related to sequi 'to follow'.","cn":"sequester 是在争议未决时保管财产的中立方；其更早来源不确定，一般认为与 sequi「跟随」有关。"},{"era":"SEQUESTRARE","en":"The verb meant to separate a thing and place it in safe keeping, a procedural act of Roman law.","cn":"这个动词意为把某物分开并放到安全保管处，是罗马法中的程序性动作。"},{"era":"ENGLISH 1400S","en":"Sequestration entered English as the setting aside of disputed property or church income.","cn":"sequestration 进入英语时指把争议财产或教会收入另行保管。"},{"era":"JURY 1700S","en":"The word was extended to the isolation of jurors, applying custody to people rather than goods.","cn":"这个词扩展到陪审员的隔离，把保管的对象从财物变成人。"},{"era":"MEDICINE 1800S","en":"Sequestrum named a fragment of dead bone separated from healthy tissue, and pulmonary sequestration followed.","cn":"sequestrum 指与健康组织分离的死骨片，肺隔离症之名随后出现。"},{"era":"BUDGET 1980S","en":"American budget law revived the word for automatic spending cuts, and climate policy borrowed it again for carbon storage.","cn":"美国预算法律用这个词指自动削减开支，气候政策随后又借它指碳储存。"}]},"similar":{"note":{"en":"Group one holds the look-alike forms of the same Latin family; group two holds the general words for isolating and impounding.","cn":"第一组是同一拉丁词族的形近形式；第二组是表示隔离与扣押的一般词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"sequester","ipa":"/sɪˈkwestə/","tag":"the verb","definition":"To set aside or isolate, especially carbon or funds; the action behind the noun.","definitionCN":"把某物另行放置或隔离，尤指碳或资金；名词背后的动作。"},{"word":"sequestrate","ipa":"/ˈsiːkwəstreɪt/","tag":"the legal verb","definition":"To take legal possession of property until a debt or dispute is settled; narrower than sequestration.","definitionCN":"在债务或争议解决前依法占有财产；比 sequestration 窄。"},{"word":"sequestrum","ipa":"/sɪˈkwestrəm/","tag":"the medical noun","definition":"A piece of dead bone separated from living bone; a single anatomical object, not a policy.","definitionCN":"与活骨分离的死骨片；是一个解剖对象，不是政策。"},{"word":"sequestration","ipa":"/ˌsiːkwəˈstreɪʃn/","tag":"the carbon-only sense","definition":"When used alone in climate writing, the word usually means carbon dioxide removal and storage, not legal custody.","definitionCN":"在气候写作中单独使用时，这个词通常指二氧化碳的移除与储存，而非法律保管。"}]},{"heading":"NEAR MEANING","entries":[{"word":"isolation","ipa":"/ˌaɪsəˈleɪʃn/","tag":"the general state","definition":"Being cut off from contact; it names the condition, while sequestration names an imposed procedure.","definitionCN":"与接触相隔绝；它命名状态，而 sequestration 命名一种强制程序。"},{"word":"confiscation","ipa":"/ˌkɒnfɪˈskeɪʃn/","tag":"permanent taking","definition":"Seizing property outright, usually by the state; sequestration holds it in custody rather than keeping it.","definitionCN":"直接没收财产，通常由国家执行；sequestration 是保管而非占为己有。"},{"word":"impoundment","ipa":"/ɪmˈpaʊndmənt/","tag":"holding in a pound","definition":"The taking and holding of goods, vehicles or water; it is a physical or legal hold, not a budget rule.","definitionCN":"扣留货物、车辆或水；是物理或法律上的扣住，不是预算规则。"},{"word":"quarantine","ipa":"/ˈkwærəntiːn/","tag":"isolation for disease","definition":"The separation of people or animals to prevent contagion; it is a public-health subtype of isolation.","definitionCN":"为防止传染而隔离人或动物；它是隔离的公共卫生子类。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin legal root and the real chain of borrowed senses.","cn":"正常联想：真实的拉丁法律词根，以及真实的一串借用义项。"},"normal":[{"en":"A sequester was a trustee: someone who held what others fought over.","cn":"sequester 曾是受托人：保管他人争夺之物的人。"},{"en":"The pattern never changes: separate the thing, then keep it under guard.","cn":"模式从未改变：先把东西分开，再置于看管之下。"},{"en":"Property, jury, budget, bone, metal, gas: one verb, six stages of custody.","cn":"财产、陪审团、预算、骨头、金属、气体：一个动词，六种保管。"},{"en":"In climate text the bare word usually means carbon, so check the context.","cn":"在气候文本里，单独这个词通常指碳，所以要看清上下文。"},{"en":"The suffix -ation turns the act into a noun, as in fixation and isolation.","cn":"后缀 -ation 把动作变成名词，如 fixation 与 isolation。"}],"abstract":[{"en":"Sequestration is a locked room with a neutral keyholder.","cn":"sequestration 是一间上锁的屋子，钥匙在一位中立方手里。"},{"en":"It is the paperwork of separation.","cn":"它是分离的文书形式。"},{"en":"Every sense asks the same question: who holds it, and for how long.","cn":"每个义项都在问同一个问题：谁保管它，保管多久。"}]},"examples":[{"en":"The judge ordered the sequestration of the disputed funds.","cn":"法官下令扣押争议资金。"},{"en":"Sequestration of the jury is rare because it is expensive and disruptive.","cn":"陪审团隔离很少使用，因为代价高且扰乱生活。"},{"en":"The word sequestration now appears most often in carbon policy.","cn":"sequestration 如今最常出现在碳政策中。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"sequestration（另行保管）＝把东西分开、交给中立方看管；同一动作依次落到财产、陪审团、预算、死骨、金属与二氧化碳上。","word":"sequestration"},"root":"拉丁 sequestrare「另行放置、交付保管」，源自 sequester「受托人、中间人」；更早来源不确定，一般认为与 sequi「跟随」有关。","sensesIntro":{"en":"Nine senses share one move: separation plus custody. They run from the general act through jury, property, budget, lung, chemistry, carbon, church income and figurative isolation.","cn":"九个义项共享一个动作：分开加保管。从一般行为依次经过陪审团、财产、预算、肺、化学、碳、教会收入，到比喻性的隔绝。"},"semanticMap":{"core":{"en":"CORE IMAGE: a disputed object is locked in a third party's cabinet, and the key is held by neither claimant.","cn":"核心意象：有争议的物品被锁进第三方的柜子，钥匙不在任何一方当事人手里。"},"chain":["DISPUTE ARISES","OBJECT SEPARATED","NEUTRAL CUSTODY","USE SUSPENDED","RELEASE LATER","NEW CLAIM SETTLED"],"branches":[{"senses":"S1 · S9","en":"THE CORE AND ITS FIGURE: setting aside in general, then the plain-language image of being cut off.","cn":"核心与比喻：先是一般的另行放置，再是日常语言里的隔绝意象。"},{"senses":"S2 · S3","en":"PEOPLE AND PROPERTY: the jury held away from news, the assets held by a third party.","cn":"人与财物：陪审团被隔在新闻之外，资产由第三方保管。"},{"senses":"S4","en":"THE TREASURY: funds withheld by rule when limits are breached.","cn":"国库：上限被突破时按规则扣下的资金。"},{"senses":"S5 · S6","en":"BODY AND MOLECULE: tissue cut off from the airway, an ion locked into a complex.","cn":"身体与分子：与气道隔开的组织，被锁进络合物的离子。"},{"senses":"S7 · S8","en":"GAS AND CHURCH: carbon put under guard, income held for a vacant benefice.","cn":"气体与教会：被看管起来的碳，为空缺教职代管的收入。"}]},"affixes":{"intro":{"en":"Sequestration is a Latin legal noun with a productive family in law, medicine and climate policy.","cn":"sequestration 是一个拉丁法律名词，在法律、医学与气候政策中都有能产的词族。"},"latinIntro":{"en":"Latin supplies sequester, sequestrare and sequestrum; there is no separate prefix to parse, since the whole word came through as one unit.","cn":"拉丁语提供 sequester、sequestrare 与 sequestrum；这里没有可拆的前缀，因为整个词是作为一个单位传入的。"},"items":[{"word":"sequester","structure":"sequester (Latin noun, 'trustee, mediator')","meaning":"one who holds disputed property","meaningCN":"保管争议财产的人","example":"Sequester is the base of the whole family.","exampleCN":"sequester 是整个词族的词基。"},{"word":"sequestrare","structure":"sequestrare (Latin verb, first conjugation)","meaning":"to set aside; to give into custody","meaningCN":"另行放置；交付保管","example":"Sequestrare produced the English noun.","exampleCN":"sequestrare 产生了这个英语名词。"},{"word":"sequestratio","structure":"sequestratio, -onis (Latin noun of action)","meaning":"a setting apart","meaningCN":"分开保管的行为","example":"The Latin noun of action became English sequestration.","exampleCN":"这个拉丁动作名词变成英语 sequestration。"},{"word":"sequestration","structure":"sequestration (English noun from Latin sequestratio)","meaning":"the act or state of being set apart","meaningCN":"被分开保管的行为或状态","example":"The word carries a legal tone in every sense.","exampleCN":"这个词在每个义项里都带着法律语气。"},{"word":"sequestrate","structure":"sequestrate (English verb from Latin sequestrare)","meaning":"to take legal custody of property","meaningCN":"依法保管财产","example":"Courts sequestrate assets pending judgment.","exampleCN":"法院在判决前扣押资产。"},{"word":"sequestrated","structure":"sequestrate + -ed (past participle)","meaning":"held in legal custody","meaningCN":"处于法律保管之下","example":"The sequestrated estate could not be sold.","exampleCN":"被扣押的产业不能出售。"},{"word":"sequestrum","structure":"sequestrum, -i (Latin noun, 'deposit, thing held')","meaning":"a piece of dead bone separated from living tissue","meaningCN":"与活组织分离的死骨片","example":"Surgeons remove a sequestrum to cure infection.","exampleCN":"外科医生切除死骨片以治愈感染。"},{"word":"sequestrotomy","structure":"sequestrum + -otomy (Greek 'cutting')","meaning":"surgical removal of a dead bone fragment","meaningCN":"死骨片的外科切除","example":"Sequestrotomy is a rare procedure today.","exampleCN":"死骨切除术如今很少施行。"}],"latinEntries":[{"word":"sequester","structure":"sequester (n., third declension)","meaning":"trustee; mediator","meaningCN":"受托人；中间人"},{"word":"sequestrare","structure":"sequestrare (verb, first conjugation)","meaning":"to set aside; to sequestrate","meaningCN":"另行放置；扣押"},{"word":"sequestratio","structure":"sequestratio, -onis (n., third declension)","meaning":"a setting apart","meaningCN":"分开保管"},{"word":"sequestrum","structure":"sequestrum, -i (n., second declension)","meaning":"a thing held in deposit","meaningCN":"寄存之物"}]}},{"word":"carbon footprint","ipa_uk":"/ˈkɑːbən ˈfʊtprɪnt/","ipa_us":"/ˈkɑːrbən ˈfʊtprɪnt/","definition_zh":"碳足迹（某一活动、产品、个人或机构直接与间接产生的温室气体排放总量，通常以二氧化碳当量计）","definition_en":"the total greenhouse gases released directly and indirectly by an activity, product, person or organisation, usually expressed as carbon dioxide equivalent","core_image":"一双脚印从油田、货轮、工厂一路踩到餐盘，每一处都留下看不见的气体，最后合成一个数字","scene":"学生算出一顿午餐从种植、运输到烹饪的全部排放。The carbon footprint of the conference included every flight the speakers took.","sceneCN":"这里 carbon footprint 指「某项活动全链条排放的总量」（第 2 个义项：活动或事件的排放总量）；句意为这场会议的碳足迹包括了每位讲者的每一段飞行。","pos":[{"tag":"n.","zh":"碳足迹（可数名词短语，复数直接加 -s；加不定冠词指一个具体总量）"}],"collocations":[{"phrase":"reduce one's carbon footprint","zh":"减少自己的碳足迹"},{"phrase":"carbon footprint label","zh":"碳足迹标签"},{"phrase":"product carbon footprint","zh":"产品碳足迹"},{"phrase":"corporate carbon footprint","zh":"企业碳足迹"},{"phrase":"household carbon footprint","zh":"家庭碳足迹"},{"phrase":"measure a carbon footprint","zh":"测算碳足迹"}],"forms":[{"label":"单数","form":"a carbon footprint"},{"label":"复数","form":"carbon footprints"},{"label":"限定成分","form":"carbon"},{"label":"核心名词","form":"footprint"},{"label":"相关度量","form":"carbon dioxide equivalent"}],"derivatives":[{"word":"footprint","pos":"n.","zh":"foot（古英语 fōt）+ print（古法语 preinte「印记」，源自拉丁 premere「压」）→ 脚印；影响范围"},{"word":"carbon","pos":"n.","zh":"拉丁 carbo（木炭）→ 碳：以炭命名的元素"},{"word":"ecological footprint","pos":"n.","zh":"eco-（希腊 oikos「家宅」）+ logical + footprint → 生态足迹：人类占用土地与水面的面积"},{"word":"water footprint","pos":"n.","zh":"water + footprint → 水足迹：一项活动耗用的水量"},{"word":"emission","pos":"n.","zh":"e-（向外）+ mittere（拉丁「送出」）+ -ion → 排放：向外释出的气体或物质"},{"word":"offset","pos":"n./v.","zh":"off（离开）+ set（放置）→ 抵消：用另一处的减排补上这里的排放"}],"senses":[{"no":"01","title":"The attributed total","titleCN":"归到某对象头上的排放总量","definition":"the sum of greenhouse gases attributed to a defined object, whether a person, product or institution","definitionCN":"归到某个确定对象名下的温室气体总和，对象可以是人、产品或机构","example":"Every organisation now publishes an annual carbon footprint.","exampleCN":"如今每个机构都会公布年度碳足迹。","why":"the phrase works by attaching an invisible quantity to something you can point at.","whyCN":"这个短语的做法是把一个看不见的量挂到你能指认的对象上。"},{"no":"02","title":"An event's total","titleCN":"活动或事件的排放总量","definition":"the emissions of a gathering, trip or project, including travel, energy and waste","definitionCN":"一次集会、旅程或项目的排放，包含交通、能源与废物","example":"The carbon footprint of the conference included every flight the speakers took.","exampleCN":"这场会议的碳足迹包括了每位讲者的每一段飞行。","why":"a one-off event has no fixed plant to measure, so the accounting follows people and services.","whyCN":"一次性活动没有固定厂房可量，核算只能跟着人与服务走。"},{"no":"03","title":"A product's life cycle","titleCN":"产品全生命周期","definition":"emissions from extracting materials, manufacturing, shipping, use and disposal of a good","definitionCN":"一件商品从取料、制造、运输、使用到处置的排放","example":"The carbon footprint of a beef burger is dominated by land use.","exampleCN":"一个牛肉汉堡的碳足迹主要来自土地利用。","why":"a product touches many processes, so its footprint is assembled from every stage of its life.","whyCN":"一件产品牵涉许多过程，其足迹由生命的每个阶段拼成。"},{"no":"04","title":"The personal account","titleCN":"个人与家庭的账","definition":"the emissions a household causes through heating, travel, food and goods","definitionCN":"家庭因取暖、出行、饮食与购物造成的排放","example":"Flying less is the fastest way to shrink a personal carbon footprint.","exampleCN":"少坐飞机是缩小个人碳足迹最快的办法。","why":"the phrase became popular because it turns a global problem into a number one person can act on.","whyCN":"这个短语流行起来，是因为它把全球问题变成了一个人可以行动的数字。"},{"no":"05","title":"A measurement standard","titleCN":"计量口径与当量","definition":"the accounting convention that converts methane, nitrous oxide and other gases into carbon dioxide equivalent","definitionCN":"把甲烷、氧化亚氮等气体折算成二氧化碳当量的核算口径","example":"The carbon footprint is reported in tonnes of carbon dioxide equivalent.","exampleCN":"碳足迹以二氧化碳当量的吨数报告。","why":"different gases warm differently, so one common unit is needed before anything can be added up.","whyCN":"不同气体的升温能力不同，必须先有共同单位才能相加。"},{"no":"06","title":"A label and a claim","titleCN":"标签与声明","definition":"a figure printed on packaging or advertising to inform buyers","definitionCN":"印在包装或广告上供消费者参考的数字","example":"The carbon footprint on the packet lets shoppers compare brands.","exampleCN":"包装上的碳足迹让购物者可以比较品牌。","why":"once measured, the number becomes a communication device as much as a scientific one.","whyCN":"一旦被测量，这个数字就既是科学工具也是传播工具。"},{"no":"07","title":"Offsetting and neutrality","titleCN":"抵消与碳中和声明","definition":"the use of purchased credits to claim that a footprint has been cancelled","definitionCN":"用购买的信用声称足迹已被抵消","example":"A carbon footprint can be offset on paper without any real reduction.","exampleCN":"碳足迹可以在纸面上被抵消，而实际排放毫无减少。","why":"the accounting unit invites a market answer, and the market answer can diverge from the physical one.","whyCN":"这个核算单位招来了市场式答案，而市场答案可能与物理事实脱节。"},{"no":"08","title":"National and corporate inventories","titleCN":"国家与企业清单","definition":"the aggregate figure used in reporting, regulation and supply-chain management","definitionCN":"用于报告、监管与供应链管理的汇总数字","example":"Governments compare their carbon footprint with their stated targets.","exampleCN":"各国政府把本国碳足迹与既定目标相比较。","why":"the same arithmetic scales from a household to a state, which is why the phrase travels so far.","whyCN":"同一套算法能从家庭放大到国家，这正是这个短语传播如此之广的原因。"},{"no":"09","title":"The critical view","titleCN":"批判视角：个体化与误差","definition":"the objection that personal footprints shift blame from industry and hide large uncertainties","definitionCN":"认为个人足迹把责任从工业转给个人并掩盖巨大不确定性的批评","example":"Critics call the carbon footprint a convenient way to blame shoppers.","exampleCN":"批评者称碳足迹是一种方便地把责任推给购物者的办法。","why":"a measure that is easy to personalise is also easy to use as a distraction.","whyCN":"一个容易个人化的指标，也容易被用来转移注意力。"}],"etymology":{"intro":{"en":"Carbon footprint joins the Latin-derived element name with a compound of Old English foot and Old French print, from Latin premere 'to press'. The phrase is a late twentieth-century extension of ecological footprint, which was coined in the early 1990s; the carbon version spread in the 2000s.","cn":"carbon footprint 把拉丁语源的元素名，接在古英语 foot 与古法语 print（源自拉丁 premere「压」）构成的复合词上。这个短语是二十世纪后期对生态足迹的延伸；生态足迹造于一九九〇年代初，碳版本在二〇〇〇年代流行。"},"items":[{"era":"OLD ENGLISH FŌT","en":"Fōt meant the foot and also the track it leaves, a sense present from the earliest records.","cn":"fōt 指脚，也指脚留下的痕迹，这个含义自最早文献就有。"},{"era":"LATIN PREMERE","en":"Premere 'to press' produced Old French preinte 'impression', the source of English print.","cn":"premere「压」产生古法语 preinte「印痕」，是英语 print 的来源。"},{"era":"FOOTPRINT 1500S","en":"Footprint first meant the mark of a foot, and only later the area a building or activity occupies.","cn":"footprint 最初指脚的印记，后来才指建筑或活动占用的面积。"},{"era":"CARBON 1789","en":"Lavoisier's circle fixed carbone as the element's name; English took it as carbon.","cn":"拉瓦锡一派把 carbone 定为该元素之名；英语取用为 carbon。"},{"era":"ECOLOGICAL FOOTPRINT 1992","en":"Wackernagel and Rees coined ecological footprint for the land area needed to support consumption.","cn":"瓦克纳格尔与里斯造出 ecological footprint，指支撑消费所需的土地面积。"},{"era":"THE PHRASE 2000S","en":"Companies and campaigners turned the metaphor into a carbon-specific figure, and advertising fixed the phrase.","cn":"企业与倡导者把这个比喻改造成以碳为单位的数字，广告使这个短语固定下来。"}]},"similar":{"note":{"en":"Group one holds the sibling footprint and carbon-claim terms most often swapped in; group two holds the formal accounting terms behind them.","cn":"第一组是最常被替换使用的足迹与碳声明术语；第二组是它们背后的正式核算术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"ecological footprint","ipa":"/ˌiːkəˈlɒdʒɪkl ˈfʊtprɪnt/","tag":"land area, not gas","definition":"The area of land and water needed to supply a population's resources and absorb its waste; it is measured in hectares, not tonnes.","definitionCN":"供给人口资源并消纳其废物所需的土地与水域面积；以公顷计，而非吨。"},{"word":"water footprint","ipa":"/ˈwɔːtə ˈfʊtprɪnt/","tag":"litres, not carbon","definition":"The volume of fresh water used directly and indirectly by a product or activity, measured in litres or cubic metres.","definitionCN":"产品或活动直接与间接耗用的淡水量，以升或立方米计。"},{"word":"carbon offset","ipa":"/ˈkɑːbən ˈɒfset/","tag":"a payment, not a measure","definition":"A credit bought to compensate for emissions; it is supposed to cancel part of a footprint but is not itself one.","definitionCN":"为补偿排放而购买的信用；它意在抵消部分足迹，但本身不是足迹。"},{"word":"carbon budget","ipa":"/ˈkɑːbən ˈbʌdʒɪt/","tag":"an allowance, not a history","definition":"The total emissions still permitted within a temperature limit; it looks forward, while a footprint records what has happened.","definitionCN":"在某个温度上限内仍允许的排放总量；它向前看，而足迹记录已发生的事。"}]},{"heading":"NEAR MEANING","entries":[{"word":"greenhouse gas inventory","ipa":"/ˈɡriːnhaʊs ɡæs ɪnˈventri/","tag":"the official ledger","definition":"A formal, methodical count of emissions by source and sector; a footprint is often a simplified version of one.","definitionCN":"按来源与部门系统统计排放的正式账目；足迹常是其简化版。"},{"word":"emissions intensity","ipa":"/ɪˈmɪʃnz ɪnˈtensəti/","tag":"per unit of output","definition":"Emissions divided by output or revenue; it compares efficiency rather than total size.","definitionCN":"排放除以产量或收入；比较的是效率，而非总量。"},{"word":"life cycle assessment","ipa":"/laɪf ˈsaɪkl əˈsesmənt/","tag":"the method","definition":"The systematic study of a product's impacts from cradle to grave; a product footprint is one of its outputs.","definitionCN":"系统研究产品从摇篮到坟墓的影响；产品足迹是它的产出之一。"},{"word":"carbon neutrality","ipa":"/ˈkɑːbən njuːˈtræləti/","tag":"the claim, not the count","definition":"A state in which emissions are balanced by removals or offsets; it is a status claimed after a footprint is calculated.","definitionCN":"排放由移除或抵消平衡的状态；它是算出足迹之后才声明的状态。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Old English and Latin roots and the real accounting logic.","cn":"正常联想：真实的古英语与拉丁词根，以及真实的核算逻辑。"},"normal":[{"en":"footprint is a mark left behind: the phrase asks what mark your consumption leaves in the air.","cn":"footprint 是留下的印子：这个短语问的是你的消费在空气里留下什么印。"},{"en":"print comes from premere, to press: a footprint is something pressed into a surface.","cn":"print 来自 premere「压」：足迹是被压进表面的东西。"},{"en":"The unit is carbon dioxide equivalent, so methane and nitrous oxide are converted into one scale.","cn":"单位是二氧化碳当量，于是甲烷与氧化亚氮被折算到同一把尺上。"},{"en":"Three scopes: direct fuel, purchased power, and everything in the supply chain.","cn":"三个范围：直接燃料、购入电力，以及供应链中的一切。"},{"en":"The older cousin is ecological footprint, measured in land rather than gas.","cn":"更早的表亲是生态足迹，用土地而非气体来计量。"}],"abstract":[{"en":"A carbon footprint is a shadow cast in a gas nobody can see.","cn":"碳足迹是投在一种谁也看不见的气体里的影子。"},{"en":"It is a receipt for things already burned elsewhere.","cn":"它是一张为别处已经烧掉的东西开的收据。"},{"en":"Every number is a small confession.","cn":"每个数字都是一次小小的坦白。"}]},"examples":[{"en":"The label states the carbon footprint per portion.","cn":"标签标明了每份的碳足迹。"},{"en":"Firms audit their supply chains before publishing a carbon footprint.","cn":"企业在公布碳足迹前会审计供应链。"},{"en":"A carbon footprint measures emissions, not the damage they cause.","cn":"碳足迹衡量的是排放，而不是排放造成的损害。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"carbon（碳）+ footprint（脚印）＝你的消费在空气里留下的排放印记；记三个范围：直接燃料、购入电力、供应链。","word":"carbon footprint"},"root":"carbon（拉丁 carbo「木炭」）+ footprint（古英语 fōt「脚」+ print，源自拉丁 premere「压」）；短语为一九九〇年代生态足迹的碳版本延伸。","sensesIntro":{"en":"Nine senses follow the number from its definition to its critiques: attributed total, event, product, household, standard, label, offset, national inventory and the objection that it individualises blame.","cn":"九个义项跟这个数字从定义走到批评：归属总量、活动、产品、家庭、计量口径、标签、抵消、国家清单，以及它把责任个人化的反对意见。"},"semanticMap":{"core":{"en":"CORE IMAGE: footprints walk from an oil well through a ship and a factory to a dinner plate, and each step leaves invisible gas that adds into one figure.","cn":"核心意象：脚印从油井经货轮与工厂走到餐盘，每一步都留下看不见的气体，最后加成一个数字。"},"chain":["EXTRACT FUEL","SHIP AND MAKE","CONSUME","WASTE AND DISPOSE","CONVERT TO EQUIVALENT","SUM INTO ONE FIGURE"],"branches":[{"senses":"S1 · S4","en":"WHOLE AND PERSON: the attributed total, then the household version people can act on.","cn":"整体与人：先是归属总量，再是普通人能行动的家庭版本。"},{"senses":"S2 · S3","en":"EVENTS AND GOODS: a gathering's travel and energy, then a product's whole life.","cn":"活动与商品：先是集会的交通与能源，再是产品的整个生命。"},{"senses":"S5","en":"THE COMMON UNIT: every gas converted into carbon dioxide equivalent.","cn":"共同单位：每种气体都折算成二氧化碳当量。"},{"senses":"S6 · S7","en":"COMMUNICATION AND CLAIM: the printed label, then the purchased offset.","cn":"传播与声明：先是印出的标签，再是购买的抵消。"},{"senses":"S8 · S9","en":"SCALE AND CRITIQUE: national inventories, then the charge that the number shifts blame.","cn":"尺度与批评：先是国家清单，再是指它转移责任的指控。"}]},"affixes":{"intro":{"en":"Carbon footprint is a two-word phrase: a Latin-derived element name plus an English compound of foot and print.","cn":"carbon footprint 是两词短语：拉丁语源的元素名，加上由 foot 与 print 构成的英语复合词。"},"latinIntro":{"en":"Latin carbo gives carbon; Latin premere gives print through Old French; foot is native Old English.","cn":"拉丁 carbo 给出 carbon；拉丁 premere 经古法语给出 print；foot 则是本土古英语。"},"items":[{"word":"carbo","structure":"carbo, carbonis (Latin noun)","meaning":"charcoal; ember","meaningCN":"木炭；炭火","example":"Carbo gave carbon.","exampleCN":"carbo 给出 carbon。"},{"word":"carbon","structure":"carbon (English noun from French carbone)","meaning":"the element counted in the phrase","meaningCN":"这个短语所计的元素","example":"Carbon is the common currency of the figure.","exampleCN":"碳是这个数字的共同货币。"},{"word":"fōt","structure":"fōt (Old English noun, masculine)","meaning":"foot; track","meaningCN":"脚；足迹","example":"Fōt survives unchanged in foot.","exampleCN":"fōt 在 foot 中原样留存。"},{"word":"premere","structure":"premere (Latin verb, third conjugation)","meaning":"to press","meaningCN":"压","example":"Premere produced Old French preinte.","exampleCN":"premere 产生古法语 preinte。"},{"word":"preinte","structure":"preinte (Old French noun, 'impression')","meaning":"a mark pressed into a surface","meaningCN":"压进表面的印记","example":"Preinte became English print.","exampleCN":"preinte 变成英语 print。"},{"word":"print","structure":"print (English noun and verb)","meaning":"a mark; to make a mark","meaningCN":"印记；留下印记","example":"Print supplies the second half of footprint.","exampleCN":"print 提供 footprint 的后半截。"},{"word":"footprint","structure":"foot + print (English compound)","meaning":"the mark a foot leaves; an occupied area","meaningCN":"脚留下的印记；占用的面积","example":"Footprint widened from a track to an impact.","exampleCN":"footprint 由脚印扩展为影响范围。"},{"word":"emission","structure":"e- (out) + mittere (Latin 'to send') + -ion","meaning":"a gas or substance released","meaningCN":"释放出的气体或物质","example":"Emissions are what the footprint totals.","exampleCN":"排放正是足迹所汇总的东西。"},{"word":"offset","structure":"off + set (English compound)","meaning":"a compensation for an emission","meaningCN":"对排放的补偿","example":"An offset is not the same as a reduction.","exampleCN":"抵消并不等同于减排。"}],"latinEntries":[{"word":"carbo","structure":"carbo, carbonis (n., third declension)","meaning":"charcoal; ember","meaningCN":"木炭；炭火"},{"word":"premere","structure":"premere (verb, third conjugation)","meaning":"to press","meaningCN":"压"},{"word":"mittere","structure":"mittere (verb, third conjugation)","meaning":"to send; to let go","meaningCN":"送出；放出"}]}},{"word":"renewable","ipa_uk":"/rɪˈnjuːəbl/","ipa_us":"/rɪˈnuːəbl/","definition_zh":"可再生的（资源使用后能由自然过程或人工方式补充的；也可指可续期、可恢复的）","definition_en":"capable of being replenished by natural processes or renewed by agreement, rather than exhausted by use","core_image":"风车转一圈，风还在；砍掉一棵树，林子又长回来；太阳第二天照旧升起，取用并没有掏空库存","scene":"村口的风车一年年转着，风却没有变少。Wind is a renewable resource because the atmosphere keeps replacing it.","sceneCN":"这里 renewable 指「使用后能被自然过程补充的」（第 1 个义项：资源属性）；句意为风是可再生资源，因为大气不断把它补回来。","pos":[{"tag":"adj.","zh":"可再生的；可续期的（作定语；有比较级与最高级）"},{"tag":"n.","zh":"可再生能源（名词化后常用复数形式，指可再生的能源或资源）"}],"collocations":[{"phrase":"renewable resource","zh":"可再生资源"},{"phrase":"renewable energy","zh":"可再生能源"},{"phrase":"renewable electricity","zh":"可再生电力"},{"phrase":"renewable capacity","zh":"可再生能源装机容量"},{"phrase":"renewable lease","zh":"可续租约"},{"phrase":"renewable term","zh":"可续期限"}],"forms":[{"label":"原级","form":"renewable"},{"label":"比较级","form":"more renewable"},{"label":"最高级","form":"most renewable"},{"label":"复数名词","form":"renewables"},{"label":"动词（词源相关）","form":"renew"},{"label":"名词","form":"renewal"}],"derivatives":[{"word":"renew","pos":"v.","zh":"re-（拉丁「再次」）+ novare（拉丁「使新」，源自 novus「新」）→ 更新、续期：使重新变成新的"},{"word":"renewal","pos":"n.","zh":"renew + -al（名词后缀）→ 更新、续期：重新开始的行为"},{"word":"renewably","pos":"adv.","zh":"renewable + -ly（副词后缀）→ 以可再生方式地（较少用）"},{"word":"nonrenewable","pos":"adj.","zh":"non-（拉丁「不」）+ renewable → 不可再生的：补充速度远慢于消耗"},{"word":"renovate","pos":"v.","zh":"renovare（拉丁「翻新」）+ -ate → 翻修：使旧物重新变新"},{"word":"innovation","pos":"n.","zh":"in-（进入）+ novare（使新）+ -ation → 创新：引入新的事物"}],"senses":[{"no":"01","title":"Replenished by nature","titleCN":"由自然补充的资源","definition":"a resource whose stock is restored by natural processes at least as fast as people use it","definitionCN":"储量由自然过程恢复、速度至少与人使用速度相当的资源","example":"Wind is a renewable resource because the atmosphere keeps replacing it.","exampleCN":"风是可再生资源，因为大气不断把它补回来。","why":"the word says nothing about cleanliness; it only says the supply comes back.","whyCN":"这个词并不说明清洁与否，只说明供给会回来。"},{"no":"02","title":"Renewable energy","titleCN":"可再生能源","definition":"energy from flows that continue, such as sunlight, wind, water and heat from the earth","definitionCN":"来自持续流动的能源，如阳光、风、流水与地热","example":"Renewable electricity now supplies a third of the grid.","exampleCN":"可再生电力如今供应了三分之一的电网。","why":"energy is the most common partner noun, and the adjective narrows to flows rather than fuels.","whyCN":"「能源」是最常见的搭配名词，这个形容词在此收窄为流动而非燃料。"},{"no":"03","title":"Stock versus flow","titleCN":"储量与流量的区别","definition":"the accounting distinction between a finite stock and a rate that keeps arriving","definitionCN":"有限储量与持续到来速率之间的核算区别","example":"A forest is renewable only if the harvest stays below growth.","exampleCN":"只有采伐量低于生长量时，森林才是可再生的。","why":"renewability is a rate comparison, not a property of the material itself.","whyCN":"可再生性是速率的比较，而不是材料本身的属性。"},{"no":"04","title":"Renewable agreements","titleCN":"可续期的合同与租约","definition":"describing a lease, licence or subscription that can be extended by agreement","definitionCN":"描述可按约定延长的租约、许可或订阅","example":"The studio signed a renewable five-year lease.","exampleCN":"工作室签了一份五年期可续租约。","why":"the same Latin base means 'made new again', and a contract can be made new by renewal.","whyCN":"同一个拉丁词基意为「重新变新」，合同也能通过续期重新变新。"},{"no":"05","title":"Renewable materials","titleCN":"可再生材料","definition":"plant or animal-derived materials that can be regrown, such as timber, bamboo, hemp and wool","definitionCN":"可重新种植或养殖的动植物材料，如木材、竹、麻与羊毛","example":"Builders prefer renewable materials such as timber and bamboo.","exampleCN":"建筑者偏爱木材与竹这类可再生材料。","why":"materials inherit the agricultural sense: what is harvested can be grown again.","whyCN":"材料继承了农业含义：收走的东西可以再种回来。"},{"no":"06","title":"Biological renewal","titleCN":"生物性的更新","definition":"tissue, cells or organs able to replace themselves after damage","definitionCN":"受损后能自行替换的组织、细胞或器官","example":"Skin is a renewable tissue that repairs itself quickly.","exampleCN":"皮肤是一种能快速自我修复的可再生组织。","why":"biology uses the older sense of renewing what was lost, without any energy meaning.","whyCN":"生物学用的是「使失去的重新长回」的旧义，与能源无关。"},{"no":"07","title":"Renewable policies and terms","titleCN":"可续保的保单与条款","definition":"insurance or contractual terms that guarantee the option to continue","definitionCN":"保证可以继续的保险或合同条款","example":"The policy is renewable unless the insurer gives notice.","exampleCN":"除非保险人发出通知，这份保单是可续保的。","why":"here renewal is a legal promise, not a natural process.","whyCN":"这里的续期是法律承诺，而不是自然过程。"},{"no":"08","title":"The plural noun","titleCN":"复数名词：可再生能源","definition":"the collective noun for renewable sources, used in markets and policy","definitionCN":"指可再生来源的集合名词，用于市场与政策","example":"Investors moved money into renewables after the price of panels fell.","exampleCN":"光伏板价格下跌后，投资者把钱转向可再生能源。","why":"a category needs a short name, so the adjective became a plural noun.","whyCN":"一个类别需要简称，于是这个形容词变成了复数名词。"},{"no":"09","title":"Targets and shares","titleCN":"目标与占比","definition":"the adjective in mandates, quotas and percentage targets for clean supply","definitionCN":"用于强制性要求、配额与清洁供给占比目标的形容词","example":"The state set a renewable share target for the next decade.","exampleCN":"该州为下一个十年设定了可再生能源占比目标。","why":"policy turns the property into a number to be reached.","whyCN":"政策把这种属性变成一个要达到的数字。"}],"etymology":{"intro":{"en":"Renewable is Latin re- 'again' plus novare 'to make new', from novus 'new', with the English suffix -able. Renew entered English in the fourteenth century through Old French renoveler; renewable followed as the adjective of anything that can be made new or replenished.","cn":"renewable 是拉丁 re-「再次」加 novare「使新」（源自 novus「新」），再接英语后缀 -able。renew 于十四世纪经古法语 renoveler 进入英语；renewable 随后成为表示「可更新、可补充」的形容词。"},"items":[{"era":"LATIN NOVUS","en":"Novus meant new, fresh, recent, and supplies the core of renew, renovate and innovation.","cn":"novus 意为新的、新鲜的、近来的，提供 renew、renovate 与 innovation 的核心。"},{"era":"RENOVARE","en":"Renovare meant to make new again or restore, built from re- plus novare.","cn":"renovare 意为重新变新或恢复，由 re- 加 novare 构成。"},{"era":"OLD FRENCH RENOVELER","en":"Old French renoveler carried the verb into English as renew in the fourteenth century.","cn":"古法语 renoveler 把这个动词在十四世纪带入英语，成为 renew。"},{"era":"-ABLE","en":"The suffix -able, from Latin -abilis, means 'capable of being', so renewable means capable of being made new.","cn":"后缀 -able 源自拉丁 -abilis，意为「能够被……」，因此 renewable 意为能够被更新。"},{"era":"FORESTRY 1800S","en":"Nineteenth-century forestry and agriculture applied the word to crops, timber and fish that regrow after harvest.","cn":"十九世纪的林业与农业把这个词用于收割后能再长的作物、木材与鱼。"},{"era":"ENERGY 1970S","en":"The oil crises fixed renewable in its modern energy sense, as a label for flows that do not run out.","cn":"石油危机把这个词固定在现代能源含义上，用来标记不会耗尽的流动。"}]},"similar":{"note":{"en":"Group one holds the look-alike words that differ by one crucial feature; group two holds the near synonyms that overlap in meaning.","cn":"第一组是只差一个关键特征的形近词；第二组是含义重叠的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"nonrenewable","ipa":"/ˌnɒnrɪˈnjuːəbl/","tag":"the opposite","definition":"Exhaustible because replenishment takes far longer than use; it is the direct antonym, not a variant.","definitionCN":"因补充远慢于消耗而会耗尽；它是直接反义词，不是变体。"},{"word":"renewed","ipa":"/rɪˈnjuːd/","tag":"already done","definition":"Having been made new again; it describes a finished act, while renewable describes a capacity.","definitionCN":"已经被重新变新；描述已完成的行为，而 renewable 描述一种能力。"},{"word":"recyclable","ipa":"/ˌriːˈsaɪkləbl/","tag":"recovered, not regrown","definition":"Able to be processed into new material; recycling recovers matter, while renewing grows or restores it.","definitionCN":"能被加工成新材料；回收恢复物质，而再生是长回或恢复。"},{"word":"sustainable","ipa":"/səˈsteɪnəbl/","tag":"a wider judgement","definition":"Able to continue without exhausting resources or causing harm; sustainability is broader than renewability.","definitionCN":"能在不耗尽资源、不造成损害的情况下持续；可持续比可再生更宽。"}]},{"heading":"NEAR MEANING","entries":[{"word":"replenishable","ipa":"/rɪˈplenɪʃəbl/","tag":"the literal sense","definition":"Able to be filled again after use; it states the refilling plainly, without the energy connotation.","definitionCN":"使用后能再次充满；直白说明补充，不含能源含义。"},{"word":"inexhaustible","ipa":"/ˌɪnɪɡˈzɔːstəbl/","tag":"too strong","definition":"Unable to be used up; it is a stronger claim than renewable, which still requires rates to match.","definitionCN":"无法被耗尽；这比 renewable 的断言更强，后者仍要求速率相配。"},{"word":"clean energy","ipa":"/kliːn ˈenədʒi/","tag":"pollution, not supply","definition":"Energy that emits little or no pollution; cleanliness and renewability are different tests.","definitionCN":"几乎不排放污染的能源；清洁与可再生是两套不同的标准。"},{"word":"alternative energy","ipa":"/ɔːlˈtɜːnətɪv ˈenədʒi/","tag":"relative to the incumbent","definition":"Energy meant to replace fossil fuels; the label is about substitution, not replenishment.","definitionCN":"意在替代化石燃料的能源；这个标签讲的是替代，不是补充。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin base and the real rate comparison that decides renewability.","cn":"正常联想：真实的拉丁词基，以及真正决定可再生性的速率比较。"},"normal":[{"en":"re- is again, novus is new: renewable literally means can be made new again.","cn":"re- 是再次，novus 是新：renewable 字面上就是能够再变新。"},{"en":"The test is a race: growth against harvest, inflow against use.","cn":"检验是一场赛跑：生长对采伐，流入对使用。"},{"en":"Sunlight, wind and water are flows, not stocks: nothing is depleted when you take some.","cn":"阳光、风与水是流量而非存量：取走一些并不会减少库存。"},{"en":"A renewable lease and a renewable forest share one idea: the arrangement can be continued.","cn":"可续租约与可再生森林共享一个观念：这种安排可以延续。"},{"en":"Renewable does not mean clean: a wood stove burns a renewable fuel and still smokes.","cn":"可再生不等于清洁：木柴炉烧的是可再生燃料，照样冒烟。"}],"abstract":[{"en":"Renewable is a promise that the well refills overnight.","cn":"renewable 是一句承诺：这口井一夜之间会重新蓄满。"},{"en":"It is a budget written in sunlight instead of savings.","cn":"它是一份用阳光而不是存款写成的预算。"},{"en":"Nature renews on its own schedule, and the word asks whether ours fits.","cn":"自然按自己的日程更新，这个词问的是我们的日程是否合得上。"}]},"examples":[{"en":"Groundwater in a dry region is often not renewable on a human timescale.","cn":"干旱地区的地下水在人类时间尺度上往往不可再生。"},{"en":"The label renewable applies to the rate of use, not to the fuel alone.","cn":"可再生这个标签适用于使用速率，而不只是燃料本身。"},{"en":"A renewable contract can be ended only at the stated notice period.","cn":"可续合同只能在约定的通知期结束时终止。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"re（再次）+ new（新）+ able（能够）＝能够再变新；判断标准是补充速度能否追上使用速度。","word":"renewable"},"root":"re-（拉丁「再次」）+ novare（拉丁「使新」，源自 novus「新」）+ -able（拉丁 -abilis「能够被……」）；动词 renew 经古法语 renoveler 入英语。","sensesIntro":{"en":"Nine senses run from natural replenishment to policy targets: the resource property, renewable energy, the stock-flow test, contracts, materials, tissue, insurance, the plural noun and mandated shares.","cn":"九个义项从自然补充走到政策目标：资源属性、可再生能源、储量流量检验、合同、材料、组织、保险、复数名词，以及强制占比。"},"semanticMap":{"core":{"en":"CORE IMAGE: a windmill turns, the wind continues; a tree is cut, the forest grows back; the sun rises again without being spent.","cn":"核心意象：风车转动，风继续吹；树被砍下，林子再长回来；太阳照旧升起，没有被花掉。"},"chain":["TAKE FROM NATURE","USE THE FLOW","NATURE REPLACES","RATE MATCHES USE","SUPPLY CONTINUES","CLAIM IS MADE"],"branches":[{"senses":"S1 · S3","en":"THE PROPERTY AND ITS TEST: replenishment by nature, then the rate comparison that decides it.","cn":"属性与检验：先是由自然补充，再是决定它的速率比较。"},{"senses":"S2 · S8","en":"THE ENERGY FAMILY: the adjective before energy, then the plural noun for the market.","cn":"能源家族：先是修饰 energy 的形容词，再是市场用的复数名词。"},{"senses":"S4 · S7","en":"CONTRACTS: leases and policies that can be continued by renewal.","cn":"合同：可通过续期延续的租约与保单。"},{"senses":"S5 · S6","en":"MATTER AND BODY: regrown materials, then tissue that repairs itself.","cn":"物质与身体：先是可再长的材料，再是自我修复的组织。"},{"senses":"S9","en":"POLICY: the adjective turned into a percentage target.","cn":"政策：形容词被变成百分比目标。"}]},"affixes":{"intro":{"en":"Renewable is a Latin verb base with re-, novare and the English suffix -able.","cn":"renewable 是拉丁动词词基加 re-、novare 与英语后缀 -able。"},"latinIntro":{"en":"Latin re- and novare build renovare, which passed through Old French; the suffix -abilis became English -able.","cn":"拉丁 re- 与 novare 构成 renovare，经古法语传入；后缀 -abilis 成为英语 -able。"},"items":[{"word":"re-","structure":"re- (Latin prefix)","meaning":"again; back","meaningCN":"再次；回","example":"Re- marks a second making.","exampleCN":"re- 标记第二次制造。"},{"word":"novus","structure":"novus, -a, -um (Latin adjective)","meaning":"new; fresh","meaningCN":"新的；新鲜的","example":"Novus is the heart of the word.","exampleCN":"novus 是这个词的核心。"},{"word":"novare","structure":"novare (Latin verb, first conjugation)","meaning":"to make new","meaningCN":"使变新","example":"Novare turns new into an action.","exampleCN":"novare 把「新」变成动作。"},{"word":"renovare","structure":"re- + novare (Latin verb)","meaning":"to renew; to restore","meaningCN":"更新；恢复","example":"Renovare gave renew and renovate.","exampleCN":"renovare 给出 renew 与 renovate。"},{"word":"renew","structure":"renew (English verb from Old French renoveler)","meaning":"to make new again; to extend","meaningCN":"重新变新；延长","example":"The lease renews every five years.","exampleCN":"这份租约每五年续一次。"},{"word":"-able","structure":"-able (English suffix from Latin -abilis)","meaning":"capable of being","meaningCN":"能够被……的","example":"The suffix turns an act into a capacity.","exampleCN":"这个后缀把行为变成能力。"},{"word":"renewable","structure":"renew + -able","meaning":"capable of being renewed","meaningCN":"可被更新的","example":"Renewable marks a capacity, not a fact.","exampleCN":"renewable 标记一种能力，而非既成事实。"},{"word":"renewal","structure":"renew + -al (noun suffix)","meaning":"the act of renewing","meaningCN":"更新的行为","example":"Renewal is the noun behind the adjective.","exampleCN":"renewal 是这个形容词背后的名词。"},{"word":"nonrenewable","structure":"non- + renewable","meaning":"not able to be replenished in time","meaningCN":"无法及时补充的","example":"Nonrenewable marks the opposite race.","exampleCN":"nonrenewable 标记反向的赛跑。"}],"latinEntries":[{"word":"novus","structure":"novus, -a, -um (adjective)","meaning":"new; fresh","meaningCN":"新的；新鲜的"},{"word":"novare","structure":"novare (verb, first conjugation)","meaning":"to make new","meaningCN":"使变新"},{"word":"renovare","structure":"renovare (verb, first conjugation)","meaning":"to renew; to restore","meaningCN":"更新；恢复"}]}},{"word":"renewable energy","ipa_uk":"/rɪˈnjuːəbl ˈenədʒi/","ipa_us":"/rɪˈnuːəbl ˈenərdʒi/","definition_zh":"可再生能源（来自持续补充的自然过程、使用时不耗尽储量的能源，如太阳能、风能、水能、生物质能与地热能）","definition_en":"energy from sources that are continually replenished, such as sunlight, wind, moving water, biomass and heat from the earth","core_image":"阳光、风、流水与地热从四面涌来，设备只负责把它们转成电，而源头并不因为发了电就少一点","scene":"山脊上的风车与屋顶的光伏板同时向电网送电。Solar and wind are renewable energy sources that produce no fuel emissions.","sceneCN":"这里 renewable energy 指「来自持续补充的自然过程的能源类别」（第 1 个义项：作为类别总称）；句意为太阳能与风能属于发电时不产生燃料排放的可再生能源。","pos":[{"tag":"n.","zh":"可再生能源（不可数类别名词；具体种类可加不定冠词）"}],"collocations":[{"phrase":"renewable energy source","zh":"可再生能源来源"},{"phrase":"renewable energy target","zh":"可再生能源目标"},{"phrase":"renewable energy capacity","zh":"可再生能源装机容量"},{"phrase":"renewable energy mix","zh":"可再生能源结构"},{"phrase":"renewable energy storage","zh":"可再生能源储能"},{"phrase":"share of renewable energy","zh":"可再生能源占比"}],"forms":[{"label":"不可数用法","form":"renewable energy"},{"label":"可数单位","form":"a renewable energy source"},{"label":"复数","form":"renewable energy sources"},{"label":"限定成分","form":"renewable"},{"label":"核心名词","form":"energy"}],"derivatives":[{"word":"renewable","pos":"adj.","zh":"re-（再次）+ novare（使新）+ -able（能够被……）→ 可再生的：能被自然补充的"},{"word":"energy","pos":"n.","zh":"希腊 energeia（「活动、运作」，en-「在内」+ ergon「工作」）→ 能量：做功的能力"},{"word":"energetic","pos":"adj.","zh":"energy + -etic（希腊 -ētikos「擅长……的」）→ 精力充沛的；能量相关的"},{"word":"renewables","pos":"n.","zh":"renewable 的复数名词化 → 可再生能源（总称）"},{"word":"intermittent","pos":"adj.","zh":"inter-（之间）+ mittere（拉丁「送」）+ -ent → 间歇的：时有时无的"}],"senses":[{"no":"01","title":"The category","titleCN":"作为类别的可再生能源","definition":"the whole class of energy sources that nature keeps supplying","definitionCN":"自然持续供给的能源来源的整个类别","example":"Solar and wind are renewable energy sources that produce no fuel emissions.","exampleCN":"太阳能与风能属于发电时不产生燃料排放的可再生能源。","why":"the phrase names a class, not one technology, so it behaves like a collective label.","whyCN":"这个短语命名的是一个类别而非一项技术，因此像集合标签一样使用。"},{"no":"02","title":"Solar","titleCN":"太阳能","definition":"electricity or heat captured from sunlight by panels or concentrators","definitionCN":"用光伏板或聚光装置从阳光取得的电或热","example":"Solar renewable energy grows fastest where land is cheap.","exampleCN":"在土地便宜的地方，太阳能这种可再生能源增长最快。","why":"the sun delivers more energy in an hour than people use in a year, so it anchors the category.","whyCN":"太阳一小时送来的能量超过人类一年的使用，因此它撑起了这个类别。"},{"no":"03","title":"Wind","titleCN":"风能","definition":"electricity from turbines turned by moving air","definitionCN":"由流动空气推动涡轮产生的电","example":"Offshore wind supplies renewable energy to coastal cities.","exampleCN":"海上风电为沿海城市供应可再生能源。","why":"wind is a flow driven by uneven heating, which makes it a renewable by-product of sunlight.","whyCN":"风是不均匀受热驱动的流动，因此它是阳光的可再生副产品。"},{"no":"04","title":"Hydro and water power","titleCN":"水能与水力发电","definition":"electricity from falling or flowing water, including rivers, dams and tidal currents","definitionCN":"来自落水或流水（含河流、水坝与潮汐）的电","example":"Hydro is the oldest form of renewable energy in the grid.","exampleCN":"水力是电网中最古老的可再生能源。","why":"the water cycle refills the reservoir, so the fuel arrives without being mined.","whyCN":"水循环重新填满水库，因此燃料无需开采就会到来。"},{"no":"05","title":"Biomass","titleCN":"生物质能","definition":"energy from wood, crop residues, biogas or other recently living matter","definitionCN":"来自木材、作物残余、沼气或其他近期生物质的能源","example":"Biomass counts as renewable energy only if the plants regrow.","exampleCN":"只有当植物重新长回时，生物质才算可再生能源。","why":"biomass is stored sunlight, and its renewability depends on replanting rather than on burning.","whyCN":"生物质是储存的阳光，其可再生性取决于补种，而非燃烧。"},{"no":"06","title":"Geothermal","titleCN":"地热能","definition":"heat drawn from the earth's interior for electricity or direct heating","definitionCN":"从地球内部取出的热，用于发电或直接供暖","example":"Geothermal is renewable energy that works day and night.","exampleCN":"地热能是一种昼夜都能工作的可再生能源。","why":"the earth's heat flows continuously from radioactive decay, so it does not depend on weather.","whyCN":"地球的热量由放射性衰变持续流出，因此不依赖天气。"},{"no":"07","title":"Variability","titleCN":"间歇性与波动性","definition":"the fluctuating output of sun and wind, which is a property of the category","definitionCN":"阳光与风的出力起伏，是这一类别本身的属性","example":"Variability is the main technical weakness of renewable energy.","exampleCN":"波动性是可再生能源的主要技术弱点。","why":"the fuel cannot be scheduled, so output follows weather rather than demand.","whyCN":"燃料无法排班，因此出力跟着天气而不是需求走。"},{"no":"08","title":"Storage and grid integration","titleCN":"储能与电网整合","definition":"batteries, pumped hydro and grid flexibility that make variable supply usable","definitionCN":"让波动供给可用的电池、抽水蓄能与电网灵活性","example":"Storage turns intermittent renewable energy into firm power.","exampleCN":"储能把间歇性的可再生能源变成稳定电力。","why":"a variable source needs a buffer before it can replace a dispatchable one.","whyCN":"波动来源在取代可调度电源之前，需要一个缓冲。"},{"no":"09","title":"Targets and shares","titleCN":"目标与占比","definition":"the policy figure for how much of a system's energy must come from renewable sources","definitionCN":"规定系统能源中必须有多少来自可再生来源的政策数字","example":"The province raised its renewable energy share to half the grid.","exampleCN":"该省把可再生能源占比提高到电网的一半。","why":"once counted, the category becomes a percentage that governments can legislate.","whyCN":"一旦可计量，这个类别就变成政府可以立法的百分比。"}],"etymology":{"intro":{"en":"Renewable energy joins a Latin-derived adjective meaning 'able to be made new' with Greek energeia, 'activity', which entered English through Latin. The phrase became standard in the 1970s, when oil shocks pushed governments to count flows rather than reserves.","cn":"renewable energy 把拉丁语源、意为「能够被更新」的形容词，接在希腊 energeia「活动、运作」上，后者经拉丁语进入英语。这个短语在石油危机促使各国开始计算流量而非储量的二十世纪七十年代成为标准说法。"},"items":[{"era":"GREEK ENERGEIA","en":"Energeia meant activity or operation, built from en- 'in' and ergon 'work'; Latin took it as energia.","cn":"energeia 意为活动或运作，由 en-「在内」与 ergon「工作」构成；拉丁语借作 energia。"},{"era":"ENERGY 1500S","en":"English energy first meant vigour of expression, and only in the nineteenth century became a quantity in physics.","cn":"英语 energy 最初指表达的力度，到十九世纪才成为物理学的量。"},{"era":"LATIN NOVARE","en":"Novare 'to make new' and re- 'again' produced renovare, the base of renew and renewable.","cn":"novare「使新」与 re-「再次」构成 renovare，是 renew 与 renewable 的词基。"},{"era":"FORESTRY 1800S","en":"Renewable was applied to crops, timber and fisheries that regrow after harvest.","cn":"renewable 被用于收割后能再长的作物、木材与渔业。"},{"era":"OIL CRISIS 1973","en":"Supply shocks made governments distinguish fuels that run out from flows that keep arriving.","cn":"供给冲击使各国政府把会耗尽的燃料与持续到来的流量区分开来。"},{"era":"THE PHRASE 1970S","en":"The compound renewable energy was fixed in policy documents and became a standard category.","cn":"renewable energy 这个复合词固定在政策文件中，成为标准类别。"}]},"similar":{"note":{"en":"Group one holds the labels that are often used as if they meant the same thing; group two holds the wider energy-policy terms.","cn":"第一组是常被当成同义的标签；第二组是更宽泛的能源政策术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"clean energy","ipa":"/kliːn ˈenədʒi/","tag":"pollution test","definition":"Energy that produces little or no pollution; nuclear power is clean by this test but not renewable.","definitionCN":"几乎不产生污染的能源；核能在这一标准下算清洁，却不算可再生。"},{"word":"green energy","ipa":"/ɡriːn ˈenədʒi/","tag":"a marketing label","definition":"A loosely defined label for environmentally preferable power; it is a claim about harm, not about replenishment.","definitionCN":"对环境影响较小的电力的宽泛标签；讲的是损害，而非补充。"},{"word":"alternative energy","ipa":"/ɔːlˈtɜːnətɪv ˈenədʒi/","tag":"defined by substitution","definition":"Energy intended to replace fossil fuels; the category is set by what it displaces, not by whether it renews.","definitionCN":"意在替代化石燃料的能源；类别由被替代的对象决定，而非由是否可再生决定。"},{"word":"renewable","ipa":"/rɪˈnjuːəbl/","tag":"the bare adjective","definition":"Capable of being replenished; it can describe fish, timber or a lease, not only energy.","definitionCN":"能被补充的；可以形容鱼、木材或租约，不只能源。"}]},{"heading":"NEAR MEANING","entries":[{"word":"sustainable energy","ipa":"/səˈsteɪnəbl ˈenədʒi/","tag":"a wider test","definition":"Energy that meets present needs without compromising future ones; it adds environmental and social conditions.","definitionCN":"满足当下需求而不损害后代需求的能源；它附加了环境与社会条件。"},{"word":"low-carbon energy","ipa":"/ləʊ ˈkɑːbən ˈenədʒi/","tag":"measured by emissions","definition":"Energy with a small carbon footprint per unit; the label is about emissions, not replenishment.","definitionCN":"单位碳足迹很小的能源；标签讲的是排放，不是补充。"},{"word":"energy transition","ipa":"/ˈenədʒi trænˈzɪʃn/","tag":"the process","definition":"The shift of a system from fossil fuels to low-carbon sources; it is the change, not the category.","definitionCN":"系统从化石燃料转向低碳来源的转变；它是变化过程，不是类别。"},{"word":"energy mix","ipa":"/ˈenədʒi mɪks/","tag":"the blend","definition":"The combination of sources supplying a system; renewable energy is one share within it.","definitionCN":"为系统供能的来源组合；可再生能源是其中一份。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Greek root of energy and the real physical sources of each technology.","cn":"正常联想：energy 的真实希腊词根，以及每项技术真实的物理来源。"},"normal":[{"en":"energy is energeia, 'in work': the word began as a description of activity, not a fuel.","cn":"energy 即 energeia「在运作中」：这个词起初描述活动，而非燃料。"},{"en":"Most renewables are sunlight in different costumes: wind, rain and biomass all start with the sun.","cn":"多数可再生能源是换了装扮的阳光：风、雨与生物质都从太阳开始。"},{"en":"Geothermal is the exception: its heat comes from the earth, not the sky.","cn":"地热是例外：它的热来自地下，而非天空。"},{"en":"Two problems to name: variability and storage.","cn":"要记住两个问题：波动性与储能。"},{"en":"The phrase is a category, so it takes a share, a target and a mix.","cn":"这个短语是一个类别，因此可以讲占比、目标与结构。"}],"abstract":[{"en":"Renewable energy is living on interest instead of spending the capital.","cn":"可再生能源是靠利息生活，而不是花掉本金。"},{"en":"It is a harvest that never empties the field.","cn":"它是一种永远不掏空田地的收获。"},{"en":"The wind does not bill us, but the grid still asks for punctuality.","cn":"风不向我们收费，但电网仍要求准时。"}]},"examples":[{"en":"The country now gets a third of its electricity from renewable energy.","cn":"该国如今三分之一的电力来自可再生能源。"},{"en":"Investment in renewable energy overtook fossil fuels in the past decade.","cn":"过去十年，可再生能源投资超过了化石燃料。"},{"en":"Renewable energy needs transmission lines as much as turbines.","cn":"可再生能源需要输电线，其重要性不亚于涡轮。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"renewable（可再生的）+ energy（能量）＝来自太阳、风、水、生物质与地热的能源类别；记两个难点：波动与储能。","word":"renewable energy"},"root":"renewable（拉丁 re-「再次」+ novare「使新」+ -able）+ energy（希腊 energeia「活动」，en-「在内」+ ergon「工作」）；短语为一九七〇年代能源政策所立。","sensesIntro":{"en":"Nine senses run through the category: the class itself, solar, wind, hydro, biomass, geothermal, variability, storage and policy share.","cn":"九个义项穿行于这个类别：类别本身、太阳能、风能、水能、生物质能、地热能、波动性、储能，以及政策占比。"},"semanticMap":{"core":{"en":"CORE IMAGE: sun, wind, water and earth-heat arrive from every side; machines only convert them, and the source is not diminished.","cn":"核心意象：阳光、风、水与地热从四面涌来，机器只负责转换，源头并不因此减少。"},"chain":["SUN DRIVES FLOWS","WIND AND RAIN","TURBINE CONVERTS","GRID CARRIES","STORAGE BUFFERS","DEMAND IS MET"],"branches":[{"senses":"S1 · S9","en":"THE CATEGORY AND ITS TARGET: the class as a label, then the percentage a government legislates.","cn":"类别与目标：先是作为标签的类别，再是政府立法的百分比。"},{"senses":"S2 · S3","en":"SKY SOURCES: sunlight captured by panels, wind turning turbines.","cn":"天空来源：光伏板捕获的阳光，推动涡轮的风。"},{"senses":"S4 · S5","en":"WATER AND PLANTS: falling water, then recently living matter.","cn":"水与植物：先是落水，再是近期生物质。"},{"senses":"S6","en":"THE UNDERGROUND SOURCE: heat from the earth that ignores weather.","cn":"地下来源：不受天气影响的地热。"},{"senses":"S7 · S8","en":"THE TWO PROBLEMS: fluctuating output, then the storage that smooths it.","cn":"两个问题：先是出力波动，再是把它抹平的储能。"}]},"affixes":{"intro":{"en":"Renewable energy is a two-word technical phrase: a Latin-derived adjective of renewal plus a Greek noun for activity.","cn":"renewable energy 是两词技术短语：拉丁语源的更新形容词，加一个希腊语源的活动名词。"},"latinIntro":{"en":"Latin novare and re- give renewable, and Latin energia, borrowed from Greek energeia, gives energy.","cn":"拉丁 novare 与 re- 给出 renewable；拉丁 energia 借自希腊 energeia，给出 energy。"},"items":[{"word":"energeia","structure":"energeia (Greek noun, 'activity, operation')","meaning":"being at work","meaningCN":"处于运作之中","example":"Energeia is the root of energy.","exampleCN":"energeia 是 energy 的词根。"},{"word":"energia","structure":"energia (Latin noun borrowed from Greek)","meaning":"activity; efficacy","meaningCN":"活动；效力","example":"Energia carried the word into European languages.","exampleCN":"energia 把这个词带入欧洲各语言。"},{"word":"energy","structure":"energy (English noun from Latin energia)","meaning":"the capacity to do work","meaningCN":"做功的能力","example":"Energy became a physical quantity in the nineteenth century.","exampleCN":"energy 在十九世纪成为物理量。"},{"word":"novare","structure":"novare (Latin verb)","meaning":"to make new","meaningCN":"使新","example":"Novare supplies the idea of renewal.","exampleCN":"novare 提供更新的观念。"},{"word":"renovare","structure":"re- + novare (Latin verb)","meaning":"to renew","meaningCN":"更新","example":"Renovare underlies renewable.","exampleCN":"renovare 是 renewable 的底层。"},{"word":"renewable","structure":"renew + -able","meaning":"capable of being replenished","meaningCN":"可被补充的","example":"Renewable narrows the class to flows.","exampleCN":"renewable 把这个类别收窄到流量。"},{"word":"renewables","structure":"renewable (adjective made plural noun)","meaning":"renewable sources collectively","meaningCN":"可再生来源的统称","example":"Renewables now attract the largest investment.","exampleCN":"可再生能源如今吸引最大的投资。"},{"word":"intermittent","structure":"inter- + mittere (Latin 'to send') + -ent","meaning":"stopping and starting","meaningCN":"时断时续的","example":"Intermittent sources need storage.","exampleCN":"间歇性来源需要储能。"}],"latinEntries":[{"word":"energia","structure":"energia, -ae (n., first declension, from Greek)","meaning":"activity; efficacy","meaningCN":"活动；效力"},{"word":"novare","structure":"novare (verb, first conjugation)","meaning":"to make new","meaningCN":"使新"},{"word":"mittere","structure":"mittere (verb, third conjugation)","meaning":"to send","meaningCN":"送出"}]}},{"word":"nonrenewable","ipa_uk":"/ˌnɒnrɪˈnjuːəbl/","ipa_us":"/ˌnɑːnrɪˈnuːəbl/","definition_zh":"不可再生的（储量有限、补充速度远慢于消耗，因而终会耗尽的资源，如化石燃料与多数矿产）","definition_en":"existing in a limited stock that is used far faster than nature can replace it, so that it is eventually exhausted","core_image":"一桶油从地下抽出，抽一桶少一桶；矿脉挖空只剩石渣，要再生成得等上地质年代","scene":"矿工在图表上把储量曲线一路往下画。Coal is a nonrenewable resource because it formed over millions of years.","sceneCN":"这里 nonrenewable 指「补充远慢于消耗、终会耗尽的」（第 1 个义项：资源属性）；句意为煤是不可再生资源，因为它需要数百万年才形成。","pos":[{"tag":"adj.","zh":"不可再生的（作定语，无比较级；英式拼写带连字符）"},{"tag":"n.","zh":"不可再生资源（名词化后常用复数形式）"}],"collocations":[{"phrase":"nonrenewable resource","zh":"不可再生资源"},{"phrase":"nonrenewable energy","zh":"不可再生能源"},{"phrase":"nonrenewable fossil fuels","zh":"不可再生的化石燃料"},{"phrase":"nonrenewable groundwater","zh":"不可再生的地下水"},{"phrase":"nonrenewable stock","zh":"不可再生存量"},{"phrase":"finite and nonrenewable","zh":"有限且不可再生"}],"forms":[{"label":"原级","form":"nonrenewable"},{"label":"连字符变体","form":"non-renewable"},{"label":"复数名词","form":"nonrenewables"},{"label":"反义形容词","form":"renewable"},{"label":"词基动词","form":"renew"}],"derivatives":[{"word":"non-","pos":"prefix","zh":"non-（拉丁 non「不」）→ 不、非：加在词前表示否定"},{"word":"renewable","pos":"adj.","zh":"renew + -able → 可再生的：使用后能被自然补充的"},{"word":"renew","pos":"v.","zh":"re-（再次）+ novare（使新）→ 更新、续期"},{"word":"exhaustible","pos":"adj.","zh":"ex-（向外）+ haurire（拉丁「汲取」）+ -ible → 会耗尽的：能被抽干的"},{"word":"deplete","pos":"v.","zh":"de-（去除）+ plere（拉丁「填满」）→ 耗尽：把填满的东西取空"},{"word":"finite","pos":"adj.","zh":"finis（拉丁「界限」）+ -ite → 有限的：有边界的"}],"senses":[{"no":"01","title":"The exhaustible resource","titleCN":"会耗尽的资源","definition":"a resource held in a fixed stock that shrinks with every unit taken","definitionCN":"储量为固定存量、每取用一单位就减少一单位的资源","example":"Coal is a nonrenewable resource because it formed over millions of years.","exampleCN":"煤是不可再生资源，因为它需要数百万年才形成。","why":"the word is about the ratio of use to replacement, not about whether replacement ever happens.","whyCN":"这个词讲的是使用与补充的比值，而不是补充是否可能发生。"},{"no":"02","title":"Fossil fuels","titleCN":"化石燃料","definition":"coal, oil and gas made from ancient life and burned far faster than they formed","definitionCN":"由远古生命形成、燃烧速度远快于形成速度的煤、石油与天然气","example":"The economy still runs mostly on nonrenewable fossil fuels.","exampleCN":"经济仍主要依靠不可再生的化石燃料运转。","why":"the clearest case is fuel that took epochs to make and minutes to burn.","whyCN":"最清楚的例子就是耗上纪元形成、几分钟烧完的燃料。"},{"no":"03","title":"Minerals and metals","titleCN":"矿产与金属","definition":"ore bodies and rare elements concentrated by geology and mined out of rock","definitionCN":"由地质作用富集、从岩石中采出的矿体与稀有元素","example":"Copper ore is nonrenewable even though copper can be recycled.","exampleCN":"铜矿是不可再生的，尽管铜可以被回收。","why":"the ore is the resource; recycling saves the metal but does not rebuild the deposit.","whyCN":"矿体才是资源；回收节省金属，却不会重建矿床。"},{"no":"04","title":"Fossil groundwater","titleCN":"古地下水","definition":"water stored in deep aquifers during wetter climates and recharged only over millennia","definitionCN":"在更湿润气候下储于深层含水层、只能以千年计补给的水","example":"Farming on fossil water is mining a nonrenewable reserve.","exampleCN":"靠古地下水耕作，等于开采一份不可再生的储备。","why":"water can be renewable or not depending on the aquifer's recharge rate.","whyCN":"水是否可再生，取决于含水层的补给速率。"},{"no":"05","title":"The rate-based test","titleCN":"按速率判定的标准","definition":"the criterion that compares consumption with replenishment over a human timescale","definitionCN":"在人类时间尺度上比较消耗与补充的标准","example":"A resource is nonrenewable if refilling takes longer than a human lifetime.","exampleCN":"如果补充时间长过人的一生，这种资源就是不可再生的。","why":"nothing on earth is truly destroyed; the question is whether it returns in time to matter.","whyCN":"地球上没有东西真正消失；问题在于它能否及时回来。"},{"no":"06","title":"Recyclable but still finite","titleCN":"可回收仍有限","definition":"materials that can be reused yet still lose quality or end in dispersal","definitionCN":"可以再利用、却仍会降质或最终散失的材料","example":"Aluminium is recyclable, yet its ore remains nonrenewable.","exampleCN":"铝可以回收，但其矿石仍不可再生。","why":"recycling slows depletion instead of changing the geology that made the deposit.","whyCN":"回收只是减慢耗竭，并不能改变形成矿床的地质过程。"},{"no":"07","title":"Nonrenewable energy","titleCN":"不可再生能源","definition":"the energy category of fuels that are consumed rather than replenished","definitionCN":"被消耗而非被补充的燃料能源类别","example":"Nonrenewable energy still supplies most of the world's heat and transport.","exampleCN":"不可再生能源仍供应了世界上大部分的供暖与运输。","why":"the adjective pairs with energy to name the opposite of the renewable category.","whyCN":"这个形容词与「能源」搭配，命名可再生能源类别的对立面。"},{"no":"08","title":"Policy and transition","titleCN":"政策与转型用语","definition":"the label used in phase-out laws, subsidy debates and stranded-asset warnings","definitionCN":"用于退场立法、补贴争论与搁浅资产警告的标签","example":"The law sets a date for ending nonrenewable heating.","exampleCN":"该法律为终止不可再生供暖设定了日期。","why":"policy needs a category to phase out, and this adjective supplies it.","whyCN":"政策需要一个要退场的类别，这个形容词提供了它。"},{"no":"09","title":"The figurative use","titleCN":"比喻用法：不可再生的东西","definition":"anything spent once and gone, such as time, trust or attention","definitionCN":"用掉一次就没有的东西，如时间、信任或注意力","example":"A teacher's patience is a nonrenewable resource in a large class.","exampleCN":"在大班里，教师的耐心是一种不可再生资源。","why":"the environmental word escaped its field because the underlying image is simply depletion.","whyCN":"这个环境词逸出了本领域，因为底层意象就是单纯的耗竭。"}],"etymology":{"intro":{"en":"Nonrenewable is Latin non 'not' plus renewable, whose base is re- 'again' and novare 'to make new'. The word is a twentieth-century formation, built when resource accounting needed a clean antonym for renewable.","cn":"nonrenewable 是拉丁 non「不」加 renewable，后者的词基是 re-「再次」与 novare「使新」。这个词是二十世纪的构造，产生于资源核算需要一个与 renewable 干净对立的反义词时。"},"items":[{"era":"LATIN NON","en":"Non meant 'not' and became the English prefix that negates a word without changing its grammar.","cn":"non 意为「不」，成为英语中否定一个词而不改变其语法的前缀。"},{"era":"LATIN NOVUS","en":"Novus 'new' and novare 'to make new' supply the middle of renewable.","cn":"novus「新」与 novare「使新」提供 renewable 的中段。"},{"era":"-ABLE","en":"Latin -abilis became English -able, marking a capacity rather than a fact.","cn":"拉丁 -abilis 成为英语 -able，标记能力而非事实。"},{"era":"ECONOMICS 1900S","en":"Resource economists of the early twentieth century separated exhaustible stocks from continuing yields.","cn":"二十世纪初的资源经济学家把会耗尽的存量与持续的产出区分开来。"},{"era":"THE WORD 1970S","en":"The energy debates of the 1970s fixed nonrenewable as the everyday opposite of renewable.","cn":"一九七〇年代的能源争论把 nonrenewable 固定为 renewable 的日常反义词。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (first date only): the earliest printed use of the derived adjective is not consistently dated, though its parts are fully documented.","cn":"来源不确定（仅首见年代存疑）：这个派生形容词最早的印刷使用各家年代不一，但其组成部分记载完整。"}]},"similar":{"note":{"en":"Group one holds the words most often used as if interchangeable with nonrenewable; group two holds the property words that describe depletion.","cn":"第一组是最常被当作可互换使用的词；第二组是描述耗竭性质的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"renewable","ipa":"/rɪˈnjuːəbl/","tag":"the direct opposite","definition":"Able to be replenished at least as fast as it is used; the two words form one pair, not two degrees of the same thing.","definitionCN":"补充速度至少与使用速度相当；两词构成一对，而不是同一事物的两个程度。"},{"word":"unrenewable","ipa":"/ˌʌnrɪˈnjuːəbl/","tag":"a rare variant","definition":"An uncommon synonym formed with un- instead of non-; it appears in older texts but never displaced the standard form.","definitionCN":"用 un- 而非 non- 构成的罕见同义词；见于较旧文本，但从未取代标准形式。"},{"word":"nonreturnable","ipa":"/ˌnɒnrɪˈtɜːnəbl/","tag":"packaging, not resources","definition":"Describing a container that cannot be sent back for reuse; the resemblance is only in the prefix.","definitionCN":"描述不能退回再用的容器；相似之处只在前缀。"},{"word":"nonexhaustible","ipa":"/ˌnɒnɪɡˈzɔːstəbl/","tag":"not the same claim","definition":"Incapable of being used up; this is a stronger and rarer claim than simply not renewable.","definitionCN":"无法被耗尽；这比「不可再生」更强也更罕见的断言。"}]},{"heading":"NEAR MEANING","entries":[{"word":"finite","ipa":"/ˈfaɪnaɪt/","tag":"bounded, not timed","definition":"Having a limit; a finite stock may still last centuries, so it says nothing about the rate of use.","definitionCN":"有界限的；有限的存量也可能维持数百年，因此不说明使用速率。"},{"word":"exhaustible","ipa":"/ɪɡˈzɔːstəbl/","tag":"the economist's word","definition":"Capable of being drained completely; it is the technical term in resource economics.","definitionCN":"能被完全抽干的；这是资源经济学中的技术术语。"},{"word":"depletable","ipa":"/dɪˈpliːtəbl/","tag":"about the stock","definition":"Able to be reduced in quantity by use; it stresses the shrinking store rather than the missing replacement.","definitionCN":"会因使用而减少数量；强调缩小的存量，而非缺失的补充。"},{"word":"fossil","ipa":"/ˈfɒsl/","tag":"origin, not renewability","definition":"Made from ancient life, as in fossil water or fossil fuel; origin and renewability are different questions.","definitionCN":"由远古生命形成，如古地下水或化石燃料；来源与可再生性是两回事。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin negation and the real rate comparison.","cn":"正常联想：真实的拉丁否定词，以及真实的速率比较。"},"normal":[{"en":"non- is Latin 'not': the word simply denies that the supply comes back in time.","cn":"non- 即拉丁「不」：这个词只是否认供给能及时回来。"},{"en":"Think of a barrel, not a field: every litre taken is gone.","cn":"想一只桶，而不是一片田：取走一升就少一升。"},{"en":"Three fossil fuels: coal, oil, gas, all made long before people existed.","cn":"三种化石燃料：煤、石油、天然气，都在人类出现之前很久就形成了。"},{"en":"Recyclable is not renewable: the metal returns, the ore does not.","cn":"可回收不等于可再生：金属回来了，矿体没有。"},{"en":"Fossil water is the hidden case: an aquifer that rains no longer reach.","cn":"古地下水是隐蔽的例子：雨水已到不了的含水层。"}],"abstract":[{"en":"Nonrenewable is a wallet with no income, only a balance.","cn":"nonrenewable 是一只没有收入、只有余额的钱包。"},{"en":"It is a clock that only runs down.","cn":"它是一只只会走慢的钟。"},{"en":"We are spending a bank account that no one is paying into.","cn":"我们在花一个无人存入的银行账户。"}]},"examples":[{"en":"Oil is the textbook nonrenewable resource.","cn":"石油是教科书式的不可再生资源。"},{"en":"The report separates renewable from nonrenewable investment.","cn":"报告把可再生与不可再生投资分开统计。"},{"en":"Even a nonrenewable aquifer can be managed to last longer.","cn":"即便是不可再生的含水层，也能通过管理维持更久。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"non（不）+ renewable（可再生的）＝不能再生的；判断标准是补充速度追不上使用速度。","word":"nonrenewable"},"root":"non-（拉丁 non「不」）+ renewable（re-「再次」+ novare「使新」+ -able）；词为二十世纪资源核算与能源争论所立。","sensesIntro":{"en":"Nine senses run from the core property to its figurative use: the exhaustible stock, fossil fuels, minerals, fossil water, the rate test, recycling, the energy category, policy and plain depletion.","cn":"九个义项从核心属性走到比喻用法：会耗尽的存量、化石燃料、矿产、古地下水、速率标准、回收、能源类别、政策，以及日常的耗竭意象。"},"semanticMap":{"core":{"en":"CORE IMAGE: a barrel is drawn down litre by litre, and no rain or growth refills it within a human life.","cn":"核心意象：一只桶一升一升地被抽空，而在人的一生里没有雨水或生长把它重新填满。"},"chain":["FIXED STOCK","EXTRACTION BEGINS","STOCK FALLS","REPLACEMENT TOO SLOW","COST RISES","STOCK ENDS"],"branches":[{"senses":"S1 · S5","en":"THE PROPERTY AND ITS TEST: a fixed stock, judged by the ratio of use to replenishment.","cn":"属性与标准：先是固定存量，再以使用与补充的比值判定。"},{"senses":"S2 · S7","en":"FUELS: coal, oil and gas, then the energy category they define.","cn":"燃料：先是煤、石油与天然气，再是它们所定义的能源类别。"},{"senses":"S3 · S6","en":"ORES: mined minerals, then the recycling that slows but does not renew them.","cn":"矿石：先是采出的矿产，再是减慢却不使其再生的回收。"},{"senses":"S4","en":"WATER: aquifers filled in wetter climates and never refilled now.","cn":"水：在更湿润气候中充填、如今不再补给的含水层。"},{"senses":"S8 · S9","en":"POLICY AND FIGURE: phase-out rules, then time and patience spent once.","cn":"政策与比喻：先是退场规则，再是用掉一次就没有的时间与耐心。"}]},"affixes":{"intro":{"en":"Nonrenewable is one Latin negative prefix on top of the Latin-based adjective renewable.","cn":"nonrenewable 是一个拉丁否定前缀，加在拉丁语源的形容词 renewable 之上。"},"latinIntro":{"en":"Latin non, re-, novare and -abilis supply every part; the word was assembled in English rather than borrowed whole.","cn":"拉丁 non、re-、novare 与 -abilis 提供了全部成分；这个词是在英语中拼装而成，而非整词借入。"},"items":[{"word":"non-","structure":"non- (Latin prefix)","meaning":"not","meaningCN":"不、非","example":"Non- negates without changing the word class.","exampleCN":"non- 只否定，不改变词类。"},{"word":"novus","structure":"novus (Latin adjective)","meaning":"new","meaningCN":"新的","example":"Novus is the core of renewable.","exampleCN":"novus 是 renewable 的核心。"},{"word":"novare","structure":"novare (Latin verb)","meaning":"to make new","meaningCN":"使新","example":"Novare turns the adjective into a process.","exampleCN":"novare 把这个形容词变成过程。"},{"word":"re-","structure":"re- (Latin prefix)","meaning":"again","meaningCN":"再次","example":"Re- marks repetition.","exampleCN":"re- 标记重复。"},{"word":"-able","structure":"-able (English suffix from Latin -abilis)","meaning":"capable of being","meaningCN":"能够被……的","example":"-able marks a capacity.","exampleCN":"-able 标记一种能力。"},{"word":"renewable","structure":"renew + -able","meaning":"capable of being replenished","meaningCN":"可被补充的","example":"Renewable is the positive member of the pair.","exampleCN":"renewable 是这一对中的肯定项。"},{"word":"nonrenewable","structure":"non- + renewable","meaning":"not capable of timely replenishment","meaningCN":"无法及时补充的","example":"Nonrenewable is the negative member.","exampleCN":"nonrenewable 是这一对中的否定项。"},{"word":"exhaustible","structure":"exhaurire (Latin 'to drain out') + -ible","meaning":"able to be drained completely","meaningCN":"能被抽干的","example":"Exhaustible is the economist's synonym.","exampleCN":"exhaustible 是经济学家的同义词。"}],"latinEntries":[{"word":"non","structure":"non (Latin adverb and negative particle)","meaning":"not","meaningCN":"不"},{"word":"novus","structure":"novus, -a, -um (adjective)","meaning":"new","meaningCN":"新的"},{"word":"exhaurire","structure":"exhaurire (verb, fourth conjugation)","meaning":"to drain out; to exhaust","meaningCN":"抽干；耗尽"}]}},{"word":"fossil fuel","ipa_uk":"/ˈfɒsl ˈfjuːəl/","ipa_us":"/ˈfɑːsl ˈfjuːəl/","definition_zh":"化石燃料（煤、石油与天然气等由远古生物遗骸经地质作用形成的可燃含碳燃料）","definition_en":"a combustible carbon-rich fuel such as coal, petroleum or natural gas, formed from the remains of ancient organisms over geological time","core_image":"远古沼泽里的蕨类死去、被泥沙压住，热与压力把生物量慢慢炼成煤、油与气，人再把它挖出来烧掉","scene":"地质学家在剖面上指出一层由远古植物压成的黑色岩层。Burning fossil fuel returns carbon that was buried for millions of years.","sceneCN":"这里 fossil fuel 指「由远古生物遗骸形成的可燃燃料」（第 1 个义项：作为类别总称）；句意为燃烧化石燃料把封存了数百万年的碳送回大气。","pos":[{"tag":"n.","zh":"化石燃料（可数名词短语，复数直接加 -s；常以复数统称）"}],"collocations":[{"phrase":"fossil fuel combustion","zh":"化石燃料燃烧"},{"phrase":"fossil fuel subsidy","zh":"化石燃料补贴"},{"phrase":"fossil fuel reserves","zh":"化石燃料储量"},{"phrase":"fossil fuel dependence","zh":"对化石燃料的依赖"},{"phrase":"fossil fuel phase-out","zh":"化石燃料逐步退场"},{"phrase":"fossil fuel industry","zh":"化石燃料产业"}],"forms":[{"label":"单数","form":"a fossil fuel"},{"label":"复数","form":"fossil fuels"},{"label":"限定成分","form":"fossil"},{"label":"核心名词","form":"fuel"},{"label":"相关名词","form":"hydrocarbon"}],"derivatives":[{"word":"fossil","pos":"n./adj.","zh":"fossilis（拉丁「挖出来的」）+ -il → 化石：从地下掘出的远古遗存"},{"word":"fossiliferous","pos":"adj.","zh":"fossil + -ferous（拉丁 ferre「携带」）→ 含化石的"},{"word":"fuel","pos":"n./v.","zh":"古法语 fouaille「柴火」，源自拉丁 focus「炉灶」→ 燃料：烧起来供热的物质"},{"word":"fossilise","pos":"v.","zh":"fossil + -ise（动词后缀）→ 石化：变成化石"},{"word":"hydrocarbon","pos":"n.","zh":"hydro-（希腊 hydōr「水」）+ carbon → 烃：只含氢与碳的化合物"},{"word":"combustion","pos":"n.","zh":"comburere（拉丁「烧尽」）+ -tion → 燃烧：放热的氧化反应"}],"senses":[{"no":"01","title":"The category","titleCN":"作为类别的化石燃料","definition":"the whole class of buried organic fuels, including coal, oil and gas","definitionCN":"埋藏有机燃料的整个类别，含煤、石油与天然气","example":"Burning fossil fuel returns carbon that was buried for millions of years.","exampleCN":"燃烧化石燃料把封存了数百万年的碳送回大气。","why":"the phrase names a family defined by a common origin, not by one particular substance.","whyCN":"这个短语命名的是一族共同来源的燃料，而不是某一种特定物质。"},{"no":"02","title":"Coal","titleCN":"煤","definition":"compressed swamp vegetation altered by heat and pressure into a burnable rock","definitionCN":"沼泽植物被压缩、经热与压力变成可燃岩石","example":"Coal was the first fossil fuel to power industry at scale.","exampleCN":"煤是第一种大规模驱动工业的化石燃料。","why":"coal is the solid end of the family, and its rock-like form shows the geological origin plainly.","whyCN":"煤是这一族中的固体一端，其岩石般的形态直白显示地质来源。"},{"no":"03","title":"Petroleum","titleCN":"石油","definition":"liquid hydrocarbons trapped in porous rock, refined into petrol, diesel and plastics","definitionCN":"被困在多孔岩石中的液态烃，炼成汽油、柴油与塑料","example":"Petroleum is the fossil fuel that reshaped transport.","exampleCN":"石油是重塑了交通的化石燃料。","why":"liquid fuel made portable power possible, which is why oil became strategically central.","whyCN":"液体燃料使便携动力成为可能，这也是石油成为战略中心的原因。"},{"no":"04","title":"Natural gas","titleCN":"天然气","definition":"mostly methane, the gaseous member of the family, used for heat and power","definitionCN":"主要成分是甲烷，这一族中的气体成员，用于供热与发电","example":"Natural gas is the fossil fuel with the lowest carbon content per unit of heat.","exampleCN":"天然气是单位热量含碳量最低的化石燃料。","why":"gas burns with less carbon per unit of heat, which is why it is often treated as a bridge fuel.","whyCN":"天然气单位热量含碳较少，因此常被当作过渡燃料。"},{"no":"05","title":"Formation","titleCN":"形成：地质时间的作用","definition":"the burial, heat and pressure that turn organic matter into fuel over millions of years","definitionCN":"数百万年里把有机质变成燃料的埋藏、加热与加压","example":"The formation of fossil fuel requires conditions that no human timescale can repeat.","exampleCN":"化石燃料的形成需要人类时间尺度无法重复的条件。","why":"the fuel's existence is geological, and that is exactly why it is nonrenewable.","whyCN":"这种燃料的存在属于地质过程，这正是它不可再生的原因。"},{"no":"06","title":"Combustion and emissions","titleCN":"燃烧与排放","definition":"the oxidation of fuel that yields heat, carbon dioxide and other pollutants","definitionCN":"燃料氧化产生热、二氧化碳与其他污染物","example":"Fossil fuel combustion is the largest source of carbon dioxide from human activity.","exampleCN":"化石燃料燃烧是人类活动中最大的二氧化碳来源。","why":"the carbon stored underground becomes an atmospheric gas when the fuel is burned.","whyCN":"地下储存的碳在燃料燃烧时变成大气中的气体。"},{"no":"07","title":"Reserves and resources","titleCN":"储量与资源量","definition":"the economically recoverable portion of a larger geological endowment","definitionCN":"较大地质蕴藏中在经济上可采出的部分","example":"Fossil fuel reserves are counted only where extraction is profitable.","exampleCN":"化石燃料储量只在开采有利可图处才被计入。","why":"a reserve is an economic estimate, not a fixed underground fact.","whyCN":"储量是一种经济估算，而非固定的地下事实。"},{"no":"08","title":"Industry and subsidies","titleCN":"产业与补贴","definition":"the extraction, refining and political economy built around these fuels","definitionCN":"围绕这些燃料建立的采掘、炼制与政治经济","example":"Fossil fuel subsidies keep prices below their full social cost.","exampleCN":"化石燃料补贴使价格低于其全部社会成本。","why":"the phrase names not only a substance but an entrenched system of infrastructure and rents.","whyCN":"这个短语不只命名一种物质，还命名一整套根深蒂固的基础设施与租金体系。"},{"no":"09","title":"Transition and stranded assets","titleCN":"转型与搁浅资产","definition":"the political question of leaving reserves unburned as climate limits tighten","definitionCN":"气候约束收紧时把储量留在地下不烧的政治问题","example":"Any serious climate plan has to leave some fossil fuel in the ground.","exampleCN":"任何认真的气候方案都必须把一部分化石燃料留在地下。","why":"if the carbon budget is fixed, then some booked reserves cannot be burned and become stranded.","whyCN":"如果碳预算固定，那么一部分已记账的储量就不能烧，成为搁浅资产。"}],"etymology":{"intro":{"en":"Fossil fuel pairs a Latin adjective meaning 'dug up' with an English word for burnable material that came from Latin focus 'hearth'. Fossil was applied to buried remains in the seventeenth century; the compound fossil fuel belongs to the nineteenth century, when coal and oil were understood as ancient life.","cn":"fossil fuel 把拉丁语中意为「挖出来的」形容词，与一个源自拉丁 focus「炉灶」的英语可燃物名词配在一起。fossil 在十七世纪用于指地下遗存；复合词 fossil fuel 属于十九世纪，当时人们已明白煤与石油来自远古生命。"},"items":[{"era":"LATIN FODERE","en":"Fodere meant to dig; its participle fossilis described anything dug out of the ground.","cn":"fodere 意为挖掘；其分词 fossilis 描述任何从地下掘出的东西。"},{"era":"FOSSIL 1600S","en":"English fossil first meant anything dug up, then narrowed to the remains of ancient organisms.","cn":"英语 fossil 最初指任何掘出之物，后收窄为远古生物的遗存。"},{"era":"LATIN FOCUS","en":"Focus meant hearth, the place of fire; Medieval Latin focalia named firewood, and Old French fouaille carried it to English.","cn":"focus 意为炉灶、生火之处；中世纪拉丁 focalia 指柴火，古法语 fouaille 把它带到英语。"},{"era":"FUEL 1300S","en":"English fuel first meant firewood and later any material burned for heat or power.","cn":"英语 fuel 最初指柴火，后来指任何为供热或动力而燃烧的物质。"},{"era":"COAL AND OIL 1800S","en":"Geologists recognised coal seams and oil seeps as transformed ancient life, which made the compound meaningful.","cn":"地质学家认识到煤层与油苗是远古生命的转化物，这使这个复合词有了意义。"},{"era":"THE PHRASE 1800S","en":"Fossil fuel appeared in nineteenth-century industrial writing as a contrast to wood, water and wind.","cn":"fossil fuel 在十九世纪工业文献中出现，以区别于木柴、水力和风力。"}]},"similar":{"note":{"en":"Group one holds the look-alike terms that name one member or one related object; group two holds the wider energy categories.","cn":"第一组是命名某一成员或相关对象的形近术语；第二组是更宽的能源类别。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"fossil","ipa":"/ˈfɒsl/","tag":"the remains, not the fuel","definition":"The preserved trace of an ancient organism; only some fossils became fuel, and most did not.","definitionCN":"远古生物留下的保存痕迹；只有部分化石变成燃料，多数没有。"},{"word":"hydrocarbon","ipa":"/ˌhaɪdrəˈkɑːbən/","tag":"the chemistry","definition":"Any compound of hydrogen and carbon; fuels are hydrocarbons, but so are plastics and solvents.","definitionCN":"任何由氢与碳构成的化合物；燃料是烃，塑料与溶剂也是。"},{"word":"biofuel","ipa":"/ˈbaɪəfuːəl/","tag":"recent life, not ancient","definition":"Fuel made from recently grown plants or waste; it shares the chemistry but not the geological age.","definitionCN":"由近期生长的植物或废物制成的燃料；化学相似，但地质年龄不同。"},{"word":"fossil record","ipa":"/ˈfɒsl ˈrekɔːd/","tag":"the archive","definition":"The total evidence of past life in rock; it is a scientific archive, not an energy source.","definitionCN":"岩石中过去生命的全部证据；它是科学档案，不是能源。"}]},{"heading":"NEAR MEANING","entries":[{"word":"coal","ipa":"/kəʊl/","tag":"one member","definition":"The solid fossil fuel formed from compressed swamp plants; it is a type, not the category.","definitionCN":"由压缩沼泽植物形成的固体化石燃料；它是一个种类，不是类别。"},{"word":"petroleum","ipa":"/pəˈtrəʊliəm/","tag":"one member","definition":"Liquid fossil fuel trapped in rock; the category includes it along with coal and gas.","definitionCN":"困在岩石中的液态化石燃料；类别中还有煤与天然气。"},{"word":"conventional fuel","ipa":"/kənˈvenʃənl ˈfjuːəl/","tag":"an industry label","definition":"Fuels produced by established methods, often fossil; the contrast is with unconventional extraction, not with age.","definitionCN":"用成熟方法生产的燃料，多为化石燃料；对照的是非常规开采，而非年龄。"},{"word":"nonrenewable energy","ipa":"/ˌnɒnrɪˈnjuːəbl ˈenədʒi/","tag":"the wider class","definition":"All energy from finite stocks, including nuclear fuel; fossil fuel is its largest member.","definitionCN":"所有来自有限存量的能源，含核燃料；化石燃料是其中最大的一员。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin roots of fossil and fuel, and the real sequence from swamp to flame.","cn":"正常联想：fossil 与 fuel 的真实拉丁词根，以及从沼泽到火焰的真实顺序。"},"normal":[{"en":"Fossil is fossilis, 'dug up': the fuel is dug from rock, not grown in a field.","cn":"fossil 即 fossilis「挖出来的」：这种燃料从岩石中挖出，而非在田里种出。"},{"en":"Fuel is focus, a hearth: the word began as the stuff you put in a fireplace.","cn":"fuel 即 focus「炉灶」：这个词起初指你放进壁炉的东西。"},{"en":"Three members: rock (coal), liquid (oil), gas (methane).","cn":"三个成员：固体（煤）、液体（石油）、气体（甲烷）。"},{"en":"The recipe is time, burial, heat and pressure, none of which can be hurried.","cn":"配方是时间、埋藏、热与压力，没有一样能催快。"},{"en":"Burn it and the buried carbon becomes air; that is the whole climate problem in one sentence.","cn":"烧掉它，埋藏的碳就变成空气；整个气候问题一句话说完。"}],"abstract":[{"en":"Fossil fuel is bottled sunlight from a world that no longer exists.","cn":"化石燃料是一个已不存在的世界装瓶的阳光。"},{"en":"It is an inheritance spent as if it were income.","cn":"它是一笔被当作收入花掉的遗产。"},{"en":"Every tank of petrol is a small geological withdrawal.","cn":"每一箱汽油都是一次小小的地质提款。"}]},"examples":[{"en":"The country pledged to cut fossil fuel use in half by the end of the decade.","cn":"该国承诺在十年内把化石燃料使用减半。"},{"en":"Fossil fuel prices fell sharply during the lockdown.","cn":"封锁期间化石燃料价格大幅下跌。"},{"en":"Investors now ask whether fossil fuel assets will lose their value.","cn":"投资者如今在问化石燃料资产是否会失去价值。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"fossil（挖出来的化石）+ fuel（燃料）＝由远古生物遗骸变成的煤、石油与天然气；记三成员与四条件。","word":"fossil fuel"},"root":"fossil（拉丁 fossilis「挖出来的」，源自 fodere「挖掘」）+ fuel（古法语 fouaille「柴火」，源自拉丁 focus「炉灶」）；短语为十九世纪工业文献所立。","sensesIntro":{"en":"Nine senses run from the category to the climate debate: the family, coal, oil, gas, formation, combustion, reserves, industry and stranded assets.","cn":"九个义项从类别走到气候争论：类别、煤、石油、天然气、形成、燃烧、储量、产业，以及搁浅资产。"},"semanticMap":{"core":{"en":"CORE IMAGE: swamp plants die, sediment buries them, heat and pressure cook them for ages, and a drill brings the result up to be burned.","cn":"核心意象：沼泽植物死去，泥沙把它们埋住，热与压力煮了许多年代，钻头把产物带上来烧掉。"},"chain":["ANCIENT LIFE","BURIAL","HEAT AND PRESSURE","COAL OIL GAS","EXTRACTION","COMBUSTION"],"branches":[{"senses":"S1 · S5","en":"THE FAMILY AND ITS ORIGIN: three fuels sharing one geological recipe.","cn":"族类与来源：三种燃料共享同一份地质配方。"},{"senses":"S2 · S3","en":"SOLID AND LIQUID: coal that powered industry, oil that reshaped transport.","cn":"固体与液体：先是驱动工业的煤，再是重塑交通的石油。"},{"senses":"S4","en":"GAS: methane, the lightest member and the usual bridge fuel.","cn":"气体：甲烷，最轻的成员，也是常见的过渡燃料。"},{"senses":"S6 · S7","en":"BURN AND COUNT: emissions from combustion, then the reserve estimates.","cn":"燃烧与计量：先是燃烧排放，再是储量估算。"},{"senses":"S8 · S9","en":"SYSTEM AND TRANSITION: subsidies and infrastructure, then reserves left unburned.","cn":"体系与转型：先是补贴与基础设施，再是留在地下不烧的储量。"}]},"affixes":{"intro":{"en":"Fossil fuel is a two-word technical phrase: a Latin-derived adjective of burial plus an English noun whose root means hearth.","cn":"fossil fuel 是两词技术短语：拉丁语源的埋藏形容词，加一个词根意为炉灶的英语名词。"},"latinIntro":{"en":"Latin fodere gives fossil and fossilis; Latin focus gives fuel through Medieval Latin focalia and Old French fouaille.","cn":"拉丁 fodere 给出 fossil 与 fossilis；拉丁 focus 经中世纪拉丁 focalia 与古法语 fouaille 给出 fuel。"},"items":[{"word":"fodere","structure":"fodere (Latin verb, third conjugation)","meaning":"to dig","meaningCN":"挖掘","example":"Fodere is the verb behind fossil.","exampleCN":"fodere 是 fossil 背后的动词。"},{"word":"fossilis","structure":"fossilis (Latin adjective, 'dug up')","meaning":"dug out of the earth","meaningCN":"从地下挖出的","example":"Fossilis gave English fossil.","exampleCN":"fossilis 给出英语 fossil。"},{"word":"fossil","structure":"fossil (English noun and adjective)","meaning":"an ancient remain; dug-up","meaningCN":"远古遗存；挖出的","example":"Fossil marks the origin of the fuel.","exampleCN":"fossil 标记燃料的来源。"},{"word":"focus","structure":"focus, -i (Latin noun, 'hearth')","meaning":"fireplace; hearth","meaningCN":"壁炉；炉灶","example":"Focus is the root of fuel.","exampleCN":"focus 是 fuel 的词根。"},{"word":"focalia","structure":"focalia (Medieval Latin noun, 'firewood')","meaning":"wood for burning","meaningCN":"燃烧用的木柴","example":"Focalia became Old French fouaille.","exampleCN":"focalia 变成古法语 fouaille。"},{"word":"fouaille","structure":"fouaille (Old French noun, 'firewood')","meaning":"firewood","meaningCN":"柴火","example":"Fouaille entered English as fuel.","exampleCN":"fouaille 进入英语成为 fuel。"},{"word":"fuel","structure":"fuel (English noun from Old French)","meaning":"material burned for heat","meaningCN":"为供热而燃烧的材料","example":"Fuel widened from wood to oil and gas.","exampleCN":"fuel 从木柴扩展到石油与天然气。"},{"word":"combustion","structure":"comburere (Latin 'to burn up') + -tion","meaning":"burning with heat and light","meaningCN":"伴随热与光的燃烧","example":"Combustion releases the buried carbon.","exampleCN":"燃烧释放埋藏的碳。"},{"word":"hydrocarbon","structure":"hydro- (Greek 'water') + carbon","meaning":"a compound of hydrogen and carbon","meaningCN":"氢与碳的化合物","example":"Hydrocarbon names the chemistry of oil and gas.","exampleCN":"烃命名石油与天然气的化学本质。"}],"latinEntries":[{"word":"fodere","structure":"fodere (verb, third conjugation)","meaning":"to dig","meaningCN":"挖掘"},{"word":"fossilis","structure":"fossilis, -e (adjective)","meaning":"dug up","meaningCN":"挖出的"},{"word":"focus","structure":"focus, -i (n., second declension)","meaning":"hearth; fireplace","meaningCN":"炉灶；壁炉"},{"word":"comburere","structure":"comburere (verb, third conjugation)","meaning":"to burn up","meaningCN":"烧尽"}]}},{"word":"energy resource","ipa_uk":"/ˈenədʒi rɪˈzɔːs/","ipa_us":"/ˈenərdʒi rɪˈzɔːrs/","definition_zh":"能源资源（可被用来提供能量或动力的自然资源，如煤、石油、天然气、风、水、太阳与地热）","definition_en":"a natural resource that can be converted into energy or power, such as coal, oil, gas, wind, water, sunlight or geothermal heat","core_image":"地下的煤层、天上的阳光、河上的落差与山口的风并列成一张清单，每一项都能被转换成功","scene":"规划者在图上把煤、风与水流标成同一张清单上的不同项目。Wind is an energy resource that never has to be mined.","sceneCN":"这里 energy resource 指「可用来提供能量的自然资源」（第 1 个义项：作为类别总称）；句意为风是一种无需开采的能源资源。","pos":[{"tag":"n.","zh":"能源资源（可数名词短语，复数直接加 -s；指具体某一项时常带限定词）"}],"collocations":[{"phrase":"renewable energy resource","zh":"可再生能源资源"},{"phrase":"domestic energy resources","zh":"本国能源资源"},{"phrase":"energy resource assessment","zh":"能源资源评估"},{"phrase":"energy resource base","zh":"能源资源基础"},{"phrase":"depletion of energy resources","zh":"能源资源的耗竭"},{"phrase":"access to energy resources","zh":"获取能源资源"}],"forms":[{"label":"单数","form":"an energy resource"},{"label":"复数","form":"energy resources"},{"label":"限定成分","form":"energy"},{"label":"核心名词","form":"resource"},{"label":"相关术语","form":"energy source"}],"derivatives":[{"word":"energy","pos":"n.","zh":"希腊 energeia（「活动、运作」，en-「在内」+ ergon「工作」）→ 能量：做功的能力"},{"word":"energetic","pos":"adj.","zh":"energy + -etic（希腊 -ētikos）→ 精力充沛的；与能量有关的"},{"word":"resource","pos":"n.","zh":"re-（再次）+ source（古法语 ressource，源自拉丁 resurgere「再涌起」）→ 资源：可反复取用的来源"},{"word":"resourceful","pos":"adj.","zh":"resource + -ful（形容词后缀）→ 足智多谋的：善于调动手边资源"},{"word":"reserve","pos":"n.","zh":"reservare（拉丁「保存」）→ 储量、储备：留待将来使用的部分"},{"word":"renewable","pos":"adj.","zh":"re- + novare（使新）+ -able → 可再生的：能被自然补充的"}],"senses":[{"no":"01","title":"The category","titleCN":"作为类别的能源资源","definition":"any natural source that can be converted into useful energy","definitionCN":"任何能被转换成有用能量的自然资源","example":"Wind is an energy resource that never has to be mined.","exampleCN":"风是一种无需开采的能源资源。","why":"the phrase names a class of natural inputs, not a particular fuel or machine.","whyCN":"这个短语命名一类自然投入，而不是某种燃料或机器。"},{"no":"02","title":"Primary resources","titleCN":"一次能源资源","definition":"resources used as they are found, such as coal, crude oil, gas, uranium, sunlight and wind","definitionCN":"按原样使用的资源，如煤、原油、天然气、铀、阳光与风","example":"Coal is a primary energy resource, used before any conversion.","exampleCN":"煤是一次能源资源，在任何转换之前就被使用。","why":"the accounting starts at the point of extraction, so the raw material is the first entry.","whyCN":"核算从开采点开始，因此原料是第一项。"},{"no":"03","title":"Secondary energy","titleCN":"二次能源","definition":"energy carriers such as electricity, refined petrol or hydrogen, made from primary resources","definitionCN":"由一次资源制成的能源载体，如电力、精炼汽油或氢","example":"Electricity is a secondary energy resource made from many primaries.","exampleCN":"电力是由多种一次资源制成的二次能源。","why":"some resources are already transformed before use, so the category has a second layer.","whyCN":"有些资源在使用前已被转化，因此这个类别还有第二层。"},{"no":"04","title":"Resources versus reserves","titleCN":"资源量与储量的区别","definition":"the distinction between what exists geologically and what is economically recoverable","definitionCN":"地质上存在的量与经济上可采出的量之间的区别","example":"The energy resource base is larger than the reserves that can be booked.","exampleCN":"能源资源基础大于可计入的储量。","why":"a resource is a physical estimate, while a reserve is a commercial one.","whyCN":"资源是物理估算，储量是商业估算。"},{"no":"05","title":"Renewable and nonrenewable","titleCN":"可再生与不可再生之分","definition":"the division between flows that continue and stocks that run down","definitionCN":"持续流动的资源与逐渐耗尽的存量之间的划分","example":"Every energy resource is either a flow or a stock.","exampleCN":"每种能源资源要么是流量，要么是存量。","why":"the most basic classification of the category is whether the supply returns.","whyCN":"这个类别最基本的分类，是供给是否会回来。"},{"no":"06","title":"Energy as a service","titleCN":"能源服务与效率","definition":"the useful work or comfort obtained, rather than the fuel itself","definitionCN":"所获得的有用功或舒适，而非燃料本身","example":"Efficiency turns the same energy resource into more light and less heat.","exampleCN":"效率把同一份能源资源变成更多光和更少热。","why":"people want warm rooms, not coal; defining the resource as a service clarifies the whole chain.","whyCN":"人要的是暖房间，不是煤；把资源定义为服务能厘清整条链。"},{"no":"07","title":"Security and policy","titleCN":"能源安全与政策","definition":"the strategic question of who controls access to resources and at what price","definitionCN":"谁控制资源的获取渠道、以什么价格获取的战略问题","example":"Import dependence makes an energy resource a foreign-policy issue.","exampleCN":"进口依赖使一项能源资源变成外交议题。","why":"because resources sit under specific territories, geology becomes politics.","whyCN":"资源埋在特定领土之下，地质因此变成政治。"},{"no":"08","title":"An economic input","titleCN":"经济投入要素","definition":"a factor of production whose price shapes industry and growth","definitionCN":"价格塑造产业与增长的生产要素","example":"Cheap energy resources once decided where factories were built.","exampleCN":"廉价的能源资源曾决定工厂建在哪里。","why":"energy is an input to nearly every good, so the phrase also belongs to economics.","whyCN":"能源几乎是每种商品的投入，因此这个短语也属于经济学。"},{"no":"09","title":"Assessment and modelling","titleCN":"资源评估与建模","definition":"the quantified estimate of how much of a source exists and how fast it can be developed","definitionCN":"对某一来源存在多少、能以多快速度开发的量化估算","example":"The energy resource assessment mapped wind speeds across the coast.","exampleCN":"能源资源评估绘出了整条海岸的风速分布。","why":"before building anything, planners must turn a natural feature into a number.","whyCN":"在动工之前，规划者必须把自然特征变成一个数字。"}],"etymology":{"intro":{"en":"Energy resource joins Greek energeia 'activity' with Old French ressource, from Latin resurgere 'to rise again'. Energy became a physical quantity in the nineteenth century; the compound is a twentieth-century term of engineering and economics.","cn":"energy resource 把希腊 energeia「活动」与古法语 ressource（源自拉丁 resurgere「再涌起」）接在一起。energy 在十九世纪成为物理量；这个复合词是二十世纪工程与经济学的术语。"},"items":[{"era":"GREEK ENERGEIA","en":"Energeia meant activity or operation, from en- 'in' and ergon 'work'; Latin took it as energia.","cn":"energeia 意为活动或运作，由 en-「在内」与 ergon「工作」构成；拉丁语借作 energia。"},{"era":"ENERGY 1800S","en":"English energy moved from vigour of speech to the physical capacity for work during the nineteenth century.","cn":"英语 energy 在十九世纪由言语的力度转为物理上的做功能力。"},{"era":"OLD FRENCH RESSOURCE","en":"Ressource meant a means of recovery or help, built on resourdre 'to rise again'.","cn":"ressource 意为恢复或求助的手段，构自 resourdre「再涌起」。"},{"era":"LATIN RESURGERE","en":"Resurgere combined re- 'again' with surgere 'to rise', the image behind a resource that can be drawn on again.","cn":"resurgere 由 re-「再次」与 surgere「升起」组成，正是资源可再次取用的意象。"},{"era":"RESOURCE 1700S","en":"English resource first meant a expedient or source of help, and only later a natural supply.","cn":"英语 resource 最初指应急手段或帮助来源，后来才指自然供给。"},{"era":"THE PHRASE 1900S","en":"Twentieth-century energy economics joined the two words to name natural inputs valued for their capacity to do work.","cn":"二十世纪的能源经济学把两词连接，命名因做功能力而被估值的自然投入。"}]},"similar":{"note":{"en":"Group one holds the look-alike terms that name a related object rather than the resource itself; group two holds the technical energy-chain terms.","cn":"第一组是命名相关对象而非资源本身的形近术语；第二组是能源链条上的技术术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"energy source","ipa":"/ˈenədʒi sɔːs/","tag":"the origin point","definition":"The physical origin of energy, such as the sun or a reactor; a resource is that source seen as something usable and finite or renewable.","definitionCN":"能量的物理来源，如太阳或反应堆；资源是把该来源看作可用、有限或可再生的东西。"},{"word":"energy reserve","ipa":"/ˈenədʒi rɪˈzɜːv/","tag":"the booked portion","definition":"The part of a resource proven and economically recoverable; it is a subset, not the whole.","definitionCN":"资源中被证实且经济可采的部分；它是子集，不是整体。"},{"word":"natural resource","ipa":"/ˈnætʃrəl rɪˈzɔːs/","tag":"the wider class","definition":"Any material or feature supplied by nature, including water, timber and minerals; energy resources are one branch.","definitionCN":"自然提供的任何物质或特征，包括水、木材与矿产；能源资源是其中一个分支。"},{"word":"power","ipa":"/ˈpaʊə/","tag":"rate, not stock","definition":"The rate at which energy is delivered; a resource is the supply, while power is how fast it flows.","definitionCN":"能量输送的速率；资源是供给，功率是流动的快慢。"}]},{"heading":"NEAR MEANING","entries":[{"word":"fuel","ipa":"/ˈfjuːəl/","tag":"the burnable subset","definition":"Material burned or reacted to release energy; wind and sunlight are resources but not fuels.","definitionCN":"燃烧或反应以释放能量的材料；风与阳光是资源，却不是燃料。"},{"word":"energy carrier","ipa":"/ˈenədʒi ˈkæriə/","tag":"the transported form","definition":"A substance or system that moves energy, such as electricity or hydrogen; it may be made from a resource.","definitionCN":"输送能量的物质或系统，如电力或氢；它可由某种资源制成。"},{"word":"primary energy","ipa":"/ˈpraɪməri ˈenədʒi/","tag":"the accounting stage","definition":"Energy in the form first captured from nature, before conversion; it is a stage of the chain, not a resource type.","definitionCN":"从自然首次获取、尚未转换的能量；它是链条的一环，不是资源类型。"},{"word":"energy supply","ipa":"/ˈenədʒi səˈplaɪ/","tag":"the delivered flow","definition":"The energy actually made available to users; it depends on resources but also on infrastructure.","definitionCN":"实际提供给使用者的能量；它取决于资源，也取决于基础设施。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Greek root of energy and the real Latin image inside resource.","cn":"正常联想：energy 的真实希腊词根，以及 resource 内的真实拉丁意象。"},"normal":[{"en":"energy is energeia, 'at work': a resource is anything nature gives that can be put to work.","cn":"energy 即 energeia「在运作中」：资源就是自然给出、能被投入运作的东西。"},{"en":"resource is re-plus-surgere, 'rise again': the image is a spring that keeps coming back.","cn":"resource 是 re- 加 surgere「升起」：意象是一口不断回涌的泉。"},{"en":"Two columns: stocks that run down and flows that return.","cn":"两栏：会耗尽的存量与会回来的流量。"},{"en":"Resources are counted, reserves are booked, supply is delivered.","cn":"资源被估算，储量被记账，供给被输送。"},{"en":"Every resource passes through a conversion before it becomes a service.","cn":"每种资源在变成服务之前都要经过一次转换。"}],"abstract":[{"en":"An energy resource is a locked drawer that nature forgot to label.","cn":"能源资源是一只自然忘了贴标签的上锁抽屉。"},{"en":"It is a promise written in geology and read by economics.","cn":"它是一句用地质写、由经济读的承诺。"},{"en":"Power is the verb; resource is the noun.","cn":"功率是动词，资源是名词。"}]},"examples":[{"en":"The report ranks every energy resource by cost and emissions.","cn":"报告按成本与排放对每种能源资源排序。"},{"en":"Sunlight is an energy resource that arrives without a supply chain.","cn":"阳光是一种无需供应链就会到来的能源资源。"},{"en":"Wars have been fought over access to energy resources.","cn":"历史上为获取能源资源而发生的战争并不少见。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"energy（能量）+ resource（来源）＝能提供能量的自然资源；记两栏：会耗尽的存量与会回来的流量。","word":"energy resource"},"root":"energy（希腊 energeia「活动」，en-「在内」+ ergon「工作」）+ resource（古法语 ressource，源自拉丁 resurgere「再涌起」）；短语为二十世纪能源经济学所立。","sensesIntro":{"en":"Nine senses follow the chain from nature to service: the category, primary and secondary layers, resources versus reserves, renewable and nonrenewable, energy services, security, economics and assessment.","cn":"九个义项沿从自然到服务的链条展开：类别、一次与二次两层、资源量与储量、可再生与不可再生、能源服务、安全、经济学，以及评估。"},"semanticMap":{"core":{"en":"CORE IMAGE: coal seams, sunlight, river drops and ridge winds are listed side by side, and each can be turned into work.","cn":"核心意象：煤层、阳光、河流落差与山脊的风并列在一张清单上，每一项都能被转换成功。"},"chain":["NATURE SUPPLIES","EXTRACT OR CAPTURE","CONVERT","DELIVER","USE AS SERVICE","ACCOUNT THE COST"],"branches":[{"senses":"S1 · S8","en":"THE WHOLE AND THE ECONOMY: the class of natural inputs, then energy as a factor of production.","cn":"整体与经济：先是自然投入的类别，再是作为生产要素的能源。"},{"senses":"S2 · S3","en":"TWO LAYERS: raw primaries, then carriers made from them.","cn":"两层：先是原始的一次资源，再是由它们制成的载体。"},{"senses":"S4 · S5","en":"HOW MUCH AND WHAT KIND: resources against reserves, flows against stocks.","cn":"多少与何种：资源量对储量，流量对存量。"},{"senses":"S6 · S7","en":"SERVICE AND SECURITY: useful work and comfort, then who controls access.","cn":"服务与安全：先是有用功与舒适，再是谁控制获取渠道。"},{"senses":"S9","en":"ASSESSMENT: turning a natural feature into a quantified estimate.","cn":"评估：把自然特征变成可量化的估算。"}]},"affixes":{"intro":{"en":"Energy resource is a two-word technical phrase: a Greek-derived noun for work plus a French-derived noun for a source that rises again.","cn":"energy resource 是两词技术短语：希腊语源的「工作」名词，加一个法语语源、意为「再涌起之源」的名词。"},"latinIntro":{"en":"Latin energia, borrowed from Greek, gives energy; Latin resurgere gives resource through Old French ressource.","cn":"拉丁 energia 借自希腊语，给出 energy；拉丁 resurgere 经古法语 ressource 给出 resource。"},"items":[{"word":"energeia","structure":"energeia (Greek noun)","meaning":"activity; operation","meaningCN":"活动；运作","example":"Energeia is the root of energy.","exampleCN":"energeia 是 energy 的词根。"},{"word":"ergon","structure":"ergon (Greek noun)","meaning":"work; deed","meaningCN":"工作；行为","example":"Ergon supplies the work inside energy.","exampleCN":"ergon 提供 energy 中的「工作」。"},{"word":"energia","structure":"energia (Latin noun from Greek)","meaning":"activity; efficacy","meaningCN":"活动；效力","example":"Energia carried the word into Latin.","exampleCN":"energia 把这个词带入拉丁语。"},{"word":"energy","structure":"energy (English noun from Latin energia)","meaning":"capacity to do work","meaningCN":"做功的能力","example":"Energy became a physical quantity.","exampleCN":"energy 成为物理量。"},{"word":"surgere","structure":"surgere (Latin verb, third conjugation)","meaning":"to rise","meaningCN":"升起","example":"Surgere underlies resource.","exampleCN":"surgere 是 resource 的底层。"},{"word":"resurgere","structure":"re- + surgere (Latin verb)","meaning":"to rise again","meaningCN":"再涌起","example":"Resurgere gives the image of a returning supply.","exampleCN":"resurgere 给出供给回涌的意象。"},{"word":"ressource","structure":"ressource (Old French noun)","meaning":"means of recovery; source of help","meaningCN":"恢复的手段；帮助的来源","example":"Ressource became English resource.","exampleCN":"ressource 变成英语 resource。"},{"word":"resource","structure":"resource (English noun from Old French)","meaning":"a supply that can be drawn on","meaningCN":"可取用的供给","example":"Resource widened to natural supplies.","exampleCN":"resource 扩展到自然供给。"},{"word":"reserve","structure":"reservare (Latin 'to keep back')","meaning":"a store kept for future use","meaningCN":"留待将来使用的储备","example":"Reserve narrows resource to a booked part.","exampleCN":"reserve 把 resource 收窄为已记账的部分。"}],"latinEntries":[{"word":"energia","structure":"energia, -ae (n., first declension, from Greek)","meaning":"activity; efficacy","meaningCN":"活动；效力"},{"word":"resurgere","structure":"resurgere (verb, third conjugation)","meaning":"to rise again","meaningCN":"再涌起"},{"word":"reservare","structure":"reservare (verb, first conjugation)","meaning":"to keep back; to reserve","meaningCN":"保留；储备"}]}},{"word":"geothermal","ipa_uk":"/ˌdʒiːəʊˈθɜːml/","ipa_us":"/ˌdʒiːoʊˈθɜːrml/","definition_zh":"地热的（与地球内部热量有关的，尤指可用来发电或供暖的地下热能）","definition_en":"relating to the heat inside the earth, especially heat that can be used for power generation or heating","core_image":"钻头打到地下深处，热水与蒸汽沿井筒冲上来推动涡轮；地球内部缓慢衰变的放射性物质，就是那口永不熄火的灶","scene":"钻机在雪山上打到了热水层，白汽从井口冒出。The geothermal plant draws steam from a reservoir two kilometres below the surface.","sceneCN":"这里 geothermal 指「与地下热能有关的」（第 1 个义项：热量来源属性）；句意为这座地热电厂从地表下两公里的储层取汽。","pos":[{"tag":"adj.","zh":"地热的（作定语，无比较级与最高级；副词形式不常用，一般用介词短语表示方式）"}],"collocations":[{"phrase":"geothermal energy","zh":"地热能"},{"phrase":"geothermal power plant","zh":"地热发电厂"},{"phrase":"geothermal heat pump","zh":"地源热泵"},{"phrase":"geothermal reservoir","zh":"地热储层"},{"phrase":"geothermal gradient","zh":"地温梯度"},{"phrase":"geothermal field","zh":"地热田"}],"forms":[{"label":"原级","form":"geothermal"},{"label":"名词（学科）","form":"geothermics"},{"label":"名词（热量测量）","form":"geothermometry"},{"label":"罕见变体","form":"geothermic"},{"label":"复合名词","form":"geothermal energy"}],"derivatives":[{"word":"geothermics","pos":"n.","zh":"geo-（希腊 gē「大地」）+ thermē（「热」）+ -ics（学科后缀）→ 地热学：研究地下热量的学科"},{"word":"geothermometry","pos":"n.","zh":"geo- + thermo- + -metry（希腊 metron「测量」）→ 地温测量：用矿物或流体推算古温度"},{"word":"geothermic","pos":"adj.","zh":"geo- + thermē + -ic（形容词后缀）→ 地热的（罕见变体，与 geothermal 同义）"},{"word":"thermal","pos":"adj.","zh":"thermē（希腊「热」）+ -al → 热的：与温度有关的"},{"word":"thermometer","pos":"n.","zh":"thermo- + -meter（希腊 metron「测量」）→ 温度计：测量热的仪器"},{"word":"hydrothermal","pos":"adj.","zh":"hydro-（希腊 hydōr「水」）+ thermal → 热液的：地下热水参与形成的"}],"senses":[{"no":"01","title":"Of the earth's heat","titleCN":"与地球内部热量有关","definition":"relating to heat produced or stored beneath the earth's surface","definitionCN":"与地表之下产生或储存的热有关","example":"The geothermal plant draws steam from a reservoir two kilometres below the surface.","exampleCN":"这座地热电厂从地表下两公里的储层取汽。","why":"geo- is earth and thermē is heat: the adjective simply locates heat below ground.","whyCN":"geo- 是大地，thermē 是热：这个形容词只是把热定位在地下。"},{"no":"02","title":"The temperature gradient","titleCN":"地温梯度","definition":"the rise in rock temperature with depth, the physical reason geothermal heat is reachable","definitionCN":"岩石温度随深度上升，这是地热可及的原因","example":"The geothermal gradient makes deep drilling a heat resource.","exampleCN":"地温梯度使深钻成为一种热资源。","why":"heat is not evenly spread, and the gradient is what makes depth worth the cost.","whyCN":"热并不均匀分布，正是这个梯度让深度值得付出成本。"},{"no":"03","title":"Geothermal energy","titleCN":"地热能","definition":"the heat extracted from the earth and counted as a renewable energy source","definitionCN":"从地下取出的热，计为一种可再生能源","example":"Geothermal energy works whether or not the sun shines.","exampleCN":"无论是否出太阳，地热能都能工作。","why":"the heat flows continuously from radioactive decay, so it qualifies as renewable.","whyCN":"热量由放射性衰变持续流出，因此它算可再生能源。"},{"no":"04","title":"Shallow heat exchange","titleCN":"浅层换热与地源热泵","definition":"describing systems that use the stable temperature a few metres down to heat or cool buildings","definitionCN":"用地下数米处稳定温度给建筑供暖或制冷的系统","example":"A geothermal heat pump uses the ground as a steady thermal battery.","exampleCN":"地源热泵把土地当作一块稳定的热电池。","why":"the shallow ground stays near constant temperature, so the adjective covers low-temperature use as well as power.","whyCN":"浅层地温几乎恒定，因此这个形容词也涵盖低温利用，不只发电。"},{"no":"05","title":"The reservoir","titleCN":"地热储层","definition":"a body of hot water or steam trapped in permeable rock","definitionCN":"困在可渗透岩石中的热水或蒸汽体","example":"The geothermal reservoir must be recharged by rain or magma.","exampleCN":"地热储层必须由雨水或岩浆补给。","why":"to use the heat you need a medium that carries it, and that medium is the reservoir.","whyCN":"要利用热量就需要搬运它的介质，这个介质就是储层。"},{"no":"06","title":"The power plant","titleCN":"地热发电厂","definition":"describing flash, dry-steam or binary plants that turn steam into electricity","definitionCN":"描述把蒸汽变成电的闪蒸、干蒸汽或双循环电厂","example":"Geothermal power plants run continuously, unlike solar farms.","exampleCN":"地热电厂可以持续运行，不像光伏电站。","why":"the adjective before power plant names the fuel, which here is steam from rock.","whyCN":"放在「发电厂」前的这个形容词命名燃料，而这里的燃料是来自岩石的蒸汽。"},{"no":"07","title":"Surface hot water","titleCN":"地表的温泉与间歇泉","definition":"describing hot springs, geysers, fumaroles and other visible signs of underground heat","definitionCN":"描述温泉、间歇泉、喷气孔等地下热的可见迹象","example":"Geothermal features attract visitors to the valley.","exampleCN":"地热景观吸引游客来到这条山谷。","why":"before any drilling, the heat announces itself at the surface in water and steam.","whyCN":"在钻探之前，热就通过水与蒸汽在地表自我宣告。"},{"no":"08","title":"Exploration and drilling","titleCN":"勘探与钻探","definition":"describing surveys, wells and resource assessment needed to find and reach the heat","definitionCN":"描述寻找并到达热量所需的勘测、井与资源评估","example":"Geothermal exploration begins with mapping faults and hot springs.","exampleCN":"地热勘探从测绘断层与温泉开始。","why":"heat has no market until a well proves it, so the adjective also labels the search phase.","whyCN":"在井证明之前，热没有市场，因此这个形容词也标记寻找阶段。"},{"no":"09","title":"Sustainability and reinjection","titleCN":"可持续性与回灌","definition":"describing the management of pressure, water and heat so a field lasts decades","definitionCN":"描述对压力、水与热的管理，使地热田维持数十年","example":"Geothermal sustainability depends on returning water to the reservoir.","exampleCN":"地热的可持续性取决于把水回灌到储层。","why":"heat can be mined out like any stock if the water is not returned.","whyCN":"如果不把水送回，热也会像任何存量一样被采空。"}],"etymology":{"intro":{"en":"Geothermal is Greek gē 'earth' plus thermē 'heat', with the English adjective ending -al. The word is a nineteenth-century scientific coinage, formed when geologists began measuring temperature with depth; its exact first printed use is uncertain (source uncertain for the date only).","cn":"geothermal 是希腊 gē「大地」加 thermē「热」，再接英语形容词词尾 -al。这个词是十九世纪的科学造词，形成于地质学家开始测量温度随深度变化之时；它最早的印刷使用年代不确定（仅年代存疑）。"},"items":[{"era":"GREEK GĒ","en":"Gē meant earth or ground, and supplies the geo- of geology, geography and geothermal.","cn":"gē 意为大地或地面，提供 geology、geography 与 geothermal 的 geo-。"},{"era":"GREEK THERMĒ","en":"Thermē meant heat, from thermos 'hot', and gives thermal, thermometer and thermos.","cn":"thermē 意为热，源自 thermos「热的」，给出 thermal、thermometer 与 thermos。"},{"era":"GEO- COMPOUNDS 1700S","en":"Enlightenment science built compounds such as geography and geology from Greek geo-, accustoming English to the pattern.","cn":"启蒙时代的科学用希腊 geo- 构成 geography 与 geology 等复合词，使英语习惯了这个模式。"},{"era":"HEAT MEASUREMENT 1800S","en":"Nineteenth-century miners and geologists measured rock temperature in deep shafts and found it rising with depth.","cn":"十九世纪的矿工与地质学家在深井中测量岩石温度，发现它随深度上升。"},{"era":"THE WORD 1800S","en":"Geothermal entered technical writing to describe that deep heat and later the systems built to use it.","cn":"geothermal 进入技术写作，用来描述那种深部热量，后来也指利用它的系统。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (first date only): the adjective's earliest printed use is usually placed in the nineteenth century, but no single year is settled.","cn":"来源不确定（仅首见年代存疑）：这个形容词最早的印刷使用通常定在十九世纪，但没有公认的具体年份。"}]},"similar":{"note":{"en":"Group one holds the closely related forms and fixed phrases built on the same adjective; group two holds the neighbouring heat words with different sources.","cn":"第一组是基于同一形容词的近亲形式与固定搭配；第二组是来源不同的邻近热学词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"geothermic","ipa":"/ˌdʒiːəʊˈθɜːmɪk/","tag":"a rare variant","definition":"An uncommon synonym built with -ic instead of -al; it appears in older technical prose but is rarely used now.","definitionCN":"用 -ic 而非 -al 构成的罕见同义词；见于较旧的技术文字，如今少用。"},{"word":"geothermal energy","ipa":"/ˌdʒiːəʊˈθɜːml ˈenədʒi/","tag":"the resource, not the adjective","definition":"The heat resource itself; the adjective alone only describes something as belonging to underground heat.","definitionCN":"热资源本身；单独形容词只描述某物属于地下热。"},{"word":"geothermal gradient","ipa":"/ˌdʒiːəʊˈθɜːml ˈɡreɪdiənt/","tag":"a measurement","definition":"The rate at which temperature rises with depth; it is a quantity, not a category of energy.","definitionCN":"温度随深度上升的速率；它是一个量，不是能源类别。"},{"word":"geothermal heat pump","ipa":"/ˌdʒiːəʊˈθɜːml ˈhiːt pʌmp/","tag":"a device","definition":"A machine that exchanges heat with the shallow ground; it uses geothermal conditions but is not the heat itself.","definitionCN":"与浅层地下交换热量的机器；它利用地热条件，但不是热本身。"}]},{"heading":"NEAR MEANING","entries":[{"word":"thermal","ipa":"/ˈθɜːml/","tag":"heat anywhere","definition":"Relating to heat or temperature in general; it says nothing about where the heat comes from.","definitionCN":"与热或温度有关，泛指；不说明热来自何处。"},{"word":"hydrothermal","ipa":"/ˌhaɪdrəʊˈθɜːml/","tag":"hot water in rock","definition":"Relating to hot water circulating underground, as at vents and hot springs; geothermal is the broader heat term.","definitionCN":"与地下循环的热水有关，如喷口与温泉；geothermal 是更宽的热量词。"},{"word":"volcanic","ipa":"/vɒlˈkænɪk/","tag":"magma, not all heat","definition":"Relating to volcanoes and magma; volcanism is one source of geothermal heat, not its definition.","definitionCN":"与火山和岩浆有关；火山作用是地热的一个来源，而非其定义。"},{"word":"ground-source","ipa":"/ˈɡraʊnd sɔːs/","tag":"the shallow case","definition":"Describing heat-exchange systems that use the upper ground; it is the low-temperature branch of geothermal use.","definitionCN":"描述利用上层地温的换热系统；它是地热利用中的低温分支。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the two real Greek roots and the real depth-temperature relationship.","cn":"正常联想：两个真实的希腊词根，以及真实的深度与温度关系。"},"normal":[{"en":"geo is earth, thermē is heat: the word is simply earth-heat.","cn":"geo 是大地，thermē 是热：这个词就是地下的热。"},{"en":"The deeper you go, the hotter the rock: that is the gradient.","cn":"越往深处，岩石越热：这就是梯度。"},{"en":"Two uses: shallow heat pumps for buildings, deep steam for turbines.","cn":"两种用途：浅层热泵给建筑用，深层蒸汽推涡轮。"},{"en":"The heat comes from radioactive decay in rock, not from the sun.","cn":"热量来自岩石中的放射性衰变，而不是太阳。"},{"en":"A field lasts only if water goes back in.","cn":"只有把水回灌，地热田才能维持。"}],"abstract":[{"en":"Geothermal is a stove that was lit before the first fire.","cn":"地热是第一堆火之前就已点着的灶。"},{"en":"It is a well that brings up buried weather.","cn":"它是一口把埋藏的天气带上来的井。"},{"en":"The earth's heat is patient capital.","cn":"地球的热量是极有耐心的资本。"}]},"examples":[{"en":"Iceland heats most of its homes with geothermal water.","cn":"冰岛用地下热水为大多数家庭供暖。"},{"en":"Geothermal drilling is expensive before the first well proves the reservoir.","cn":"在第一口井证明储层之前，地热钻探成本很高。"},{"en":"The team mapped the geothermal potential of the valley.","cn":"团队测绘了这条山谷的地热潜力。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"geo（大地）+ thermal（热的）＝地下的热；两种用途：浅层热泵与深层蒸汽发电。","word":"geothermal"},"root":"geo-（希腊 gē「大地」）+ thermal（希腊 thermē「热」，源自 thermos「热的」）+ -al（拉丁 -alis）；词为十九世纪科学造词。","sensesIntro":{"en":"Nine senses go from the general property to the field: earth heat, the gradient, the energy, shallow exchange, reservoirs, plants, surface features, exploration and reinjection.","cn":"九个义项从一般属性走到具体地热田：地下热、梯度、能源、浅层换热、储层、电厂、地表景观、勘探，以及回灌。"},"semanticMap":{"core":{"en":"CORE IMAGE: a drill reaches hot rock, water flashes to steam, the steam spins a turbine, and the cooled water is sent back down.","cn":"核心意象：钻头到达热岩，水闪蒸成汽，汽推动涡轮，冷却的水又被送回地下。"},"chain":["EARTH HEAT","DEEP WATER","WELL","STEAM","TURBINE","REINJECTION"],"branches":[{"senses":"S1 · S2","en":"THE PROPERTY AND ITS PHYSICS: underground heat, then the gradient that makes depth useful.","cn":"属性与物理：先是地下热，再是让深度变得可用的梯度。"},{"senses":"S3 · S4","en":"HIGH AND LOW TEMPERATURE: the energy resource, then shallow heat exchange.","cn":"高温与低温：先是能源资源，再是浅层换热。"},{"senses":"S5 · S6","en":"THE FIELD AND THE PLANT: the reservoir, then the turbines it feeds.","cn":"地热田与电厂：先是储层，再是它供给的涡轮。"},{"senses":"S7","en":"THE SURFACE SIGN: hot springs and geysers announcing heat before drilling.","cn":"地表迹象：温泉与间歇泉在钻探之前宣告热的存在。"},{"senses":"S8 · S9","en":"FINDING AND KEEPING: exploration, then reinjection to make the field last.","cn":"寻找与维持：先是勘探，再是让地热田持久的回灌。"}]},"affixes":{"intro":{"en":"Geothermal is a Greek compound: earth plus heat, closed with the Latin-derived adjective ending -al.","cn":"geothermal 是希腊语复合词：大地加热，再用拉丁语源形容词词尾 -al 收束。"},"latinIntro":{"en":"Both roots are Greek and have no native Latin cognates; Latin only supplied the adjective ending -alis.","cn":"两个词根都属希腊语，在拉丁语中无本土同族词；拉丁语只提供了形容词词尾 -alis。"},"items":[{"word":"gē","structure":"gē (Greek noun)","meaning":"earth; ground","meaningCN":"大地；地面","example":"Gē supplies the geo- of the word.","exampleCN":"gē 提供这个词的 geo-。"},{"word":"thermē","structure":"thermē (Greek noun)","meaning":"heat","meaningCN":"热","example":"Thermē supplies the thermal half.","exampleCN":"thermē 提供 thermal 那一半。"},{"word":"thermos","structure":"thermos (Greek adjective)","meaning":"hot","meaningCN":"热的","example":"Thermos is the adjective behind thermē.","exampleCN":"thermos 是 thermē 背后的形容词。"},{"word":"-al","structure":"-al (English adjective suffix from Latin -alis)","meaning":"relating to","meaningCN":"与……有关的","example":"-al turns the compound into an adjective.","exampleCN":"-al 把复合词变成形容词。"},{"word":"geothermal","structure":"geo- + thermal","meaning":"relating to heat in the earth","meaningCN":"与地下热有关的","example":"Geothermal labels both the heat and its uses.","exampleCN":"geothermal 既标记热，也标记其利用。"},{"word":"geothermics","structure":"geo- + thermē + -ics","meaning":"the study of underground heat","meaningCN":"研究地下热的学科","example":"Geothermics grew with deep drilling.","exampleCN":"地热学随深钻发展起来。"},{"word":"geothermometry","structure":"geo- + thermo- + -metry","meaning":"measurement of ancient temperatures","meaningCN":"对古温度的测量","example":"Geothermometry reads minerals as thermometers.","exampleCN":"地温测量把矿物当作温度计来读。"},{"word":"hydrothermal","structure":"hydro- + thermal","meaning":"relating to hot water underground","meaningCN":"与地下热水有关的","example":"Hydrothermal vents sit on the sea floor.","exampleCN":"热液喷口位于海底。"},{"word":"thermal","structure":"thermē + -al","meaning":"relating to heat","meaningCN":"与热有关的","example":"Thermal is the general adjective.","exampleCN":"thermal 是泛指热的形容词。"}],"latinEntries":[]}},{"word":"geothermal energy","ipa_uk":"/ˌdʒiːəʊˈθɜːml ˈenədʒi/","ipa_us":"/ˌdʒiːoʊˈθɜːrml ˈenərdʒi/","definition_zh":"地热能（从地球内部提取、用于发电或直接供暖的热能，属可再生能源）","definition_en":"heat taken from the earth's interior and used to generate electricity or to heat buildings directly, counted as a renewable source","core_image":"地球深处像一口永不熄火的灶，钻井把热水与蒸汽带到地面转成电，用过的水再灌回岩层","scene":"山脚的电厂把地下蒸汽送进涡轮，冷却的水又沿另一口井回到岩层。Geothermal energy supplies steady power to the nearby town.","sceneCN":"这里 geothermal energy 指「从地下提取的热能」（第 1 个义项：作为能源类别）；句意为地热能为附近小镇提供稳定电力。","pos":[{"tag":"n.","zh":"地热能（不可数类别名词；具体项目可加不定冠词）"}],"collocations":[{"phrase":"geothermal energy production","zh":"地热能生产"},{"phrase":"geothermal energy capacity","zh":"地热能装机容量"},{"phrase":"geothermal energy potential","zh":"地热能潜力"},{"phrase":"geothermal energy development","zh":"地热能开发"},{"phrase":"direct use of geothermal energy","zh":"地热能直接利用"},{"phrase":"geothermal energy plant","zh":"地热能电厂"}],"forms":[{"label":"不可数用法","form":"geothermal energy"},{"label":"限定成分","form":"geothermal"},{"label":"核心名词","form":"energy"},{"label":"相关名词","form":"geothermal power"},{"label":"相关形容词","form":"geothermal"}],"derivatives":[{"word":"geothermal","pos":"adj.","zh":"geo-（希腊 gē「大地」）+ thermē（「热」）+ -al → 地热的：与地下热有关的"},{"word":"energy","pos":"n.","zh":"希腊 energeia（「活动、运作」）+ 拉丁 energia → 能量：做功的能力"},{"word":"geothermics","pos":"n.","zh":"geothermal + -ics（学科后缀）→ 地热学：研究地下热的学科"},{"word":"geothermally","pos":"adv.","zh":"geothermal + -ly（副词后缀）→ 以地热方式地（修饰供暖或发电方式）"},{"word":"reinjection","pos":"n.","zh":"re-（再次）+ injection（拉丁 inicere「投入」）→ 回灌：把流体重新压回地下"}],"senses":[{"no":"01","title":"The category","titleCN":"作为类别的地热能","definition":"the class of heat drawn from the earth and used as an energy source","definitionCN":"从地下取出并作为能源使用的热的类别","example":"Geothermal energy supplies steady power to the nearby town.","exampleCN":"地热能为附近小镇提供稳定电力。","why":"the phrase names a source of heat, not a machine or a site.","whyCN":"这个短语命名一种热源，而不是一台机器或一个场址。"},{"no":"02","title":"High-temperature fields","titleCN":"高温地热田","definition":"volcanic or tectonic settings where steam reaches temperatures high enough for efficient turbines","definitionCN":"蒸汽温度足以高效推动涡轮的火山或构造环境","example":"High-temperature geothermal energy is concentrated along plate boundaries.","exampleCN":"高温地热能集中在板块边界一带。","why":"the hotter the steam, the more electricity each kilogram can deliver.","whyCN":"蒸汽越热，每公斤能发出的电就越多。"},{"no":"03","title":"Low-temperature direct use","titleCN":"低温直接利用","definition":"warm water used directly for district heating, greenhouses, fish farms and baths","definitionCN":"温水直接用于区域供暖、温室、养鱼场与浴场","example":"Low-temperature geothermal energy heats whole districts without generating electricity.","exampleCN":"低温地热能可为整个城区供暖，而不用来发电。","why":"heat below boiling is still useful for warmth, so the resource has a second, larger use.","whyCN":"低于沸点的热对取暖依然有用，因此这种资源有第二种更大的用途。"},{"no":"04","title":"Electricity generation","titleCN":"地热发电","definition":"flash, dry-steam or binary plants that convert steam or hot water into electric power","definitionCN":"把蒸汽或热水转成电力的闪蒸、干蒸汽或双循环电厂","example":"Geothermal energy produced a tenth of the island's electricity.","exampleCN":"地热能提供了该岛十分之一的电力。","why":"the same heat can be turned into a current, which is why the resource is classed with power sources.","whyCN":"同样的热也能变成电流，因此这种资源被归入电力来源。"},{"no":"05","title":"Shallow heat exchange","titleCN":"浅层换热","definition":"ground-source heat pumps that borrow the stable temperature a few metres down","definitionCN":"借用地下数米处稳定温度的地源热泵","example":"Shallow geothermal energy keeps offices cool in summer.","exampleCN":"浅层地热能在夏天为办公室降温。","why":"the adjective covers any use of underground heat, including the very shallow kind.","whyCN":"这个形容词涵盖地下热的任何利用，包括极浅层的那一种。"},{"no":"06","title":"Reservoir and steam","titleCN":"储层与蒸汽","definition":"the physical body of hot water and steam in permeable rock that makes extraction possible","definitionCN":"可渗透岩石中使开采成为可能的热水与蒸汽体","example":"A geothermal energy project lives or dies with its reservoir.","exampleCN":"一个地热能项目的成败取决于它的储层。","why":"heat without a carrier cannot be pumped, so the reservoir is the resource in practice.","whyCN":"没有载体的热无法被泵出，因此现实中储层就是资源。"},{"no":"07","title":"Sustainability","titleCN":"可持续性与回灌","definition":"the balance of extraction and reinjection that keeps pressure and heat available for decades","definitionCN":"使压力与热量数十年可用的开采与回灌平衡","example":"Sustainability in geothermal energy means returning as much water as you take.","exampleCN":"地热能的可持续性意味着取多少水就回灌多少。","why":"a field is a stock as well as a flow, so careless use can mine it out.","whyCN":"地热田既是流量也是存量，疏忽使用会把存量采空。"},{"no":"08","title":"Exploration and economics","titleCN":"勘探与经济性","definition":"the surveys, wells and capital costs that decide whether heat can be sold","definitionCN":"决定热能否被卖出的勘测、钻井与资本成本","example":"Exploration is the riskiest stage of geothermal energy.","exampleCN":"勘探是地热能风险最高的一环。","why":"the fuel is free but the well is not, so economics decides which fields are developed.","whyCN":"燃料免费，井却要花钱，因此经济性决定哪些地热田会被开发。"},{"no":"09","title":"The low-carbon label","titleCN":"低碳与能源结构中的位置","definition":"the role of geothermal heat as a firm, low-carbon supply in a renewable mix","definitionCN":"地热在可再生能源结构中作为稳定低碳供给的角色","example":"Geothermal energy is prized because it does not depend on weather.","exampleCN":"地热能受重视，因为它不依赖天气。","why":"a source that runs at night fills the gap that sun and wind leave open.","whyCN":"一种夜里也运行的来源，正好补上阳光与风留下的缺口。"}],"etymology":{"intro":{"en":"Geothermal energy joins Greek gē 'earth' and thermē 'heat' to energeia 'activity'. The adjective geothermal is a nineteenth-century coinage; the compound with energy belongs to twentieth-century power engineering, when steam from wells first turned turbines.","cn":"geothermal energy 把希腊 gē「大地」、thermē「热」与 energeia「活动」接在一起。形容词 geothermal 是十九世纪的造词；与 energy 组成的复合词属于二十世纪的动力工程，当时井中的蒸汽开始推动涡轮。"},"items":[{"era":"GREEK GĒ","en":"Gē meant earth or ground, and supplies the geo- of geology and geothermal.","cn":"gē 意为大地或地面，提供 geology 与 geothermal 的 geo-。"},{"era":"GREEK THERMĒ","en":"Thermē meant heat, from thermos 'hot', and gives thermal and thermometer.","cn":"thermē 意为热，源自 thermos「热的」，给出 thermal 与 thermometer。"},{"era":"GREEK ENERGEIA","en":"Energeia meant activity, from en- 'in' and ergon 'work'; Latin took it as energia.","cn":"energeia 意为活动，由 en-「在内」与 ergon「工作」构成；拉丁语借作 energia。"},{"era":"GEOTHERMAL 1800S","en":"Deep mines and geological surveys showed rock temperature rising with depth, and the adjective named that heat.","cn":"深井与地质调查显示岩石温度随深度上升，这个形容词便为那种热命名。"},{"era":"ENERGY 1800S","en":"Energy became the physical quantity for work during the same century, making the compound possible.","cn":"energy 在同一世纪成为功的物理量，使这个复合词成为可能。"},{"era":"THE PHRASE 1900S","en":"Italian and Icelandic plants of the early twentieth century turned geothermal steam into electricity and fixed the phrase.","cn":"二十世纪初意大利与冰岛的工厂把地热蒸汽转成电，固定了这个短语。"}]},"similar":{"note":{"en":"Group one holds the look-alike forms that name an aspect of the same resource; group two holds the energy labels it overlaps with.","cn":"第一组是命名同一资源某一方面的形近形式；第二组是与它重叠的能源标签。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"geothermal","ipa":"/ˌdʒiːəʊˈθɜːml/","tag":"the adjective","definition":"Describing anything related to underground heat; without energy it does not name a resource category.","definitionCN":"描述任何与地下热有关的事物；不带 energy 时并不命名资源类别。"},{"word":"geothermal power","ipa":"/ˌdʒiːəʊˈθɜːml ˈpaʊə/","tag":"electricity, not heat","definition":"Electricity generated from geothermal heat; it is one output of the resource, not the resource.","definitionCN":"由地热产生的电；它是这种资源的一项产物，而非资源本身。"},{"word":"hydrothermal energy","ipa":"/ˌhaɪdrəʊˈθɜːml ˈenədʒi/","tag":"hot water only","definition":"Energy from hot water circulating underground; it covers hydrothermal systems but not hot dry rock.","definitionCN":"来自地下循环热水的能量；涵盖热液系统，却不含干热岩。"},{"word":"ground-source heat","ipa":"/ˈɡraʊnd sɔːs hiːt/","tag":"the shallow case","definition":"Heat exchanged with the upper ground for building comfort; it is the shallow branch of geothermal energy.","definitionCN":"与上层地温交换用于建筑舒适的热；它是地热能的浅层分支。"}]},{"heading":"NEAR MEANING","entries":[{"word":"renewable energy","ipa":"/rɪˈnjuːəbl ˈenədʒi/","tag":"the parent category","definition":"Energy from continually replenished sources; geothermal energy is one member of it.","definitionCN":"来自持续补充来源的能源；地热能是其中一个成员。"},{"word":"thermal energy","ipa":"/ˈθɜːml ˈenədʒi/","tag":"heat anywhere","definition":"The energy associated with temperature; it may come from the sun, a furnace or the earth.","definitionCN":"与温度相关的能量；可能来自太阳、炉子或地下。"},{"word":"district heating","ipa":"/ˈdɪstrɪkt ˈhiːtɪŋ/","tag":"the distribution system","definition":"A network that delivers heat from a central plant to many buildings; geothermal energy can feed it.","definitionCN":"从中心厂向许多建筑输送热的网络；地热能可以为其供能。"},{"word":"heat pump","ipa":"/ˈhiːt pʌmp/","tag":"the device","definition":"A machine that moves heat from one place to another; it is the hardware, not the source.","definitionCN":"把热从一处搬到另一处的机器；它是硬件，不是来源。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the three real Greek roots and the real difference between deep steam and shallow exchange.","cn":"正常联想：三个真实的希腊词根，以及深层蒸汽与浅层换热的真实区别。"},"normal":[{"en":"geo is earth, thermē is heat, energeia is activity: earth heat put to work.","cn":"geo 是大地，thermē 是热，energeia 是活动：把地下热投入运作。"},{"en":"Deep fields make steam; shallow ground makes comfort.","cn":"深部地热田产蒸汽，浅层地下产舒适。"},{"en":"The fuel is free; the well is what costs money.","cn":"燃料免费，花钱的是那口井。"},{"en":"Reinjection is the word that keeps a field alive.","cn":"回灌是让地热田活下去的那个词。"},{"en":"It is the renewable that works at night.","cn":"它是夜里也能工作的可再生能源。"}],"abstract":[{"en":"Geothermal energy is a bank loan from the planet's interior.","cn":"地热能是向行星内部借的一笔款。"},{"en":"It is the only renewable that never looks at the sky.","cn":"它是唯一从不看天空的可再生能源。"},{"en":"We drill a hole and borrow an old fire.","cn":"我们钻一个孔，借来一团古老的火。"}]},"examples":[{"en":"Geothermal energy provides heat and electricity from the same well.","cn":"地热能可以从同一口井提供热与电。"},{"en":"The island meets half its needs with geothermal energy.","cn":"该岛一半的需求由地热能满足。"},{"en":"Geothermal energy projects are capital-intensive but cheap to run.","cn":"地热能项目资本密集，但运行成本低。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"geothermal（地热的）+ energy（能量）＝从地下取出的热；深层产蒸汽发电，浅层换热供暖。","word":"geothermal energy"},"root":"geothermal（geo- 希腊 gē「大地」+ thermē「热」+ -al）+ energy（希腊 energeia「活动」，en-「在内」+ ergon「工作」）；短语为二十世纪动力工程所立。","sensesIntro":{"en":"Nine senses follow the heat from the reservoir to the grid: the category, high- and low-temperature use, electricity, shallow exchange, reservoirs, sustainability, economics and the low-carbon role.","cn":"九个义项跟热从储层走到电网：类别、高温与低温利用、发电、浅层换热、储层、可持续性、经济性，以及低碳角色。"},"semanticMap":{"core":{"en":"CORE IMAGE: a well taps hot rock, steam rises, a turbine spins, and cooled water is sent back down the second well.","cn":"核心意象：井打到热岩，蒸汽上升，涡轮转动，冷却的水沿第二口井被送回地下。"},"chain":["DEEP HEAT","RESERVOIR WATER","PRODUCTION WELL","STEAM TO TURBINE","ELECTRICITY OR HEAT","REINJECTION WELL"],"branches":[{"senses":"S1 · S9","en":"THE CATEGORY AND ITS ROLE: the resource as a class, then its place as firm low-carbon supply.","cn":"类别与角色：先是作为类别的资源，再是它作为稳定低碳供给的位置。"},{"senses":"S2 · S3","en":"HOT AND WARM: high-temperature steam for turbines, low-temperature water for buildings.","cn":"热与温：高温蒸汽供涡轮，低温热水供建筑。"},{"senses":"S4 · S5","en":"TWO CONVERSIONS: power plants, then shallow heat pumps.","cn":"两种转换：先是电厂，再是浅层热泵。"},{"senses":"S6","en":"THE STORE: the reservoir of hot water and steam that makes extraction possible.","cn":"储库：使开采成为可能的热水与蒸汽储层。"},{"senses":"S7 · S8","en":"KEEPING AND FUNDING: reinjection for longevity, then exploration and capital cost.","cn":"维持与融资：先是延寿的回灌，再是勘探与资本成本。"}]},"affixes":{"intro":{"en":"Geothermal energy is a two-word technical phrase: a Greek compound adjective plus a Greek-derived noun for work.","cn":"geothermal energy 是两词技术短语：希腊语复合形容词，加一个希腊语源的「工作」名词。"},"latinIntro":{"en":"Gē and thermē are Greek with no Latin cognates; energia is the Latin borrowing of Greek energeia, and Latin -alis gives the adjective ending.","cn":"gē 与 thermē 属希腊语，拉丁语中无同族词；energia 是拉丁语对希腊 energeia 的借入，拉丁 -alis 提供形容词词尾。"},"items":[{"word":"gē","structure":"gē (Greek noun)","meaning":"earth; ground","meaningCN":"大地；地面","example":"Gē supplies the geo- of the phrase.","exampleCN":"gē 提供这个短语的 geo-。"},{"word":"thermē","structure":"thermē (Greek noun)","meaning":"heat","meaningCN":"热","example":"Thermē supplies the thermal half.","exampleCN":"thermē 提供 thermal 那一半。"},{"word":"energeia","structure":"energeia (Greek noun)","meaning":"activity; operation","meaningCN":"活动；运作","example":"Energeia is the root of energy.","exampleCN":"energeia 是 energy 的词根。"},{"word":"energia","structure":"energia (Latin borrowing of Greek energeia)","meaning":"activity; efficacy","meaningCN":"活动；效力","example":"Energia carried energy into Latin.","exampleCN":"energia 把 energy 带入拉丁语。"},{"word":"energy","structure":"energy (English noun from Latin energia)","meaning":"capacity to do work","meaningCN":"做功的能力","example":"Energy is the second half of the phrase.","exampleCN":"energy 是短语的后半。"},{"word":"geothermal","structure":"geo- + thermal + -al","meaning":"relating to heat in the earth","meaningCN":"与地下热有关的","example":"Geothermal names the source.","exampleCN":"geothermal 命名来源。"},{"word":"-al","structure":"-al (English adjective suffix from Latin -alis)","meaning":"relating to","meaningCN":"与……有关的","example":"The suffix makes the compound adjectival.","exampleCN":"这个后缀使复合词成为形容词。"},{"word":"reinjection","structure":"re- + injection (from Latin inicere 'to throw in')","meaning":"putting fluid back underground","meaningCN":"把流体重新压回地下","example":"Reinjection sustains the reservoir.","exampleCN":"回灌维持着储层。"},{"word":"geothermics","structure":"geo- + thermē + -ics","meaning":"the study of underground heat","meaningCN":"研究地下热的学科","example":"Geothermics guides drilling decisions.","exampleCN":"地热学指导钻探决策。"}],"latinEntries":[{"word":"energia","structure":"energia, -ae (n., first declension, from Greek)","meaning":"activity; efficacy","meaningCN":"活动；效力"}]}}]);
